window.STUDY_DATA = {"modules": [{"id": 1, "title": "CodeIgniter foundations", "subtitle": "MVC · setup · routing · views", "framework": "CodeIgniter", "file": "IT0049 - M1 - CodeIgniter Foundations.pdf", "pages": 54, "notes": [{"title": "The MVC handoff", "body": "Browser → route → controller → model → controller → view → response. Model handles data; View presents it; Controller coordinates.", "page": 15}, {"title": "Know the folders", "body": "app/Controllers, app/Models, app/Views, and app/Config hold application code. public/ is the document root. writable/ holds logs and cache.", "page": 24}, {"title": "Routes choose the action", "body": "$routes->get('/about', 'Pages::about');\n$routes->get('/profile/(:num)', 'Pages::profile/$1');\n// Explicit routes choose the action; index() is not called before every method.", "page": 35}, {"title": "Data becomes variables", "body": "return view('about', ['name' => 'Pages']);\n// about.php receives $name.\nreturn view('directory-name/about');", "page": 49}, {"title": "Do not mix up the tools", "body": "CodeIgniter uses Spark. php spark serve starts the server. A base URL needs a trailing slash. Keep the server pointed at public/.", "page": 27}]}, {"id": 2, "title": "CodeIgniter data layer", "subtitle": "Configuration · models · queries", "framework": "CodeIgniter", "file": "IT0049 - M2 - CodeIgniter Data Layer.pdf", "pages": 36, "notes": [{"title": "Connection settings", "body": ".env overrides matching Database.php defaults. Know hostname, database, username, password, and DBDriver. Credentials stay out of shared version control.", "page": 10}, {"title": "A model describes its table", "body": "protected $table = 'tasks';\nprotected $primaryKey = 'id';\nprotected $allowedFields = ['title', 'status'];", "page": 20}, {"title": "Build, then retrieve", "body": "$tasks = $model->where('status', 'pending')\n    ->orderBy('created_at', 'DESC')->findAll();\n$task = $model->find($id); // null if absent", "page": 26}, {"title": "Display deliberately", "body": "return view('tasks/index', ['tasks' => $tasks]);\n// In the view, loop through $tasks and escape output:\nesc($task['title']);", "page": 30}, {"title": "A page load is not always a connection test", "body": "The module’s page-visit test requires a page that actually performs a database query. A static page can load without touching the database.", "page": 14}]}, {"id": 3, "title": "CI forms, uploads & CRUD", "subtitle": "Validation · records · attachments", "framework": "CodeIgniter", "file": "IT0049 - M3 - Forms, Validation, File Upload, and CRUD.pdf", "pages": 36, "notes": [{"title": "Validate before writing", "body": "$rules = ['title' => 'required|min_length[3]'];\nif (! $this->validate($rules)) {\n    return redirect()->back()->withInput();\n}", "page": 12}, {"title": "Preserve useful feedback", "body": "old('title', $task['title']);\nvalidation_show_error('title');\n// Match the form field name to the validation key.", "page": 14}, {"title": "The CRUD method map", "body": "$model->insert($data);\n$model->findAll();\n$model->find($id);\n$model->update($id, $data);\n$model->delete($id);", "page": 19}, {"title": "The upload pipeline", "body": "multipart/form-data → uploaded/max_size/mime_in validation → getFile() → getRandomName() → move() → save filename → construct display URL.", "page": 34}, {"title": "One field, several checks", "body": "'uploaded[attachment]'\n'max_size[attachment,2048]'\n'mime_in[attachment,image/jpeg,image/png]'\n// File rules are different from ordinary text rules.", "page": 26}]}, {"id": 4, "title": "CI authentication & sessions", "subtitle": "Login · passwords · filters", "framework": "CodeIgniter", "file": "IT0049 - M4 - CodeIgniter Authentication and Sessions.pdf", "pages": 36, "notes": [{"title": "Sessions remember small values", "body": "session()->set('username', 'admin');\nsession()->get('username');\nsession()->remove('username');\nsession()->destroy();", "page": 8}, {"title": "Flash data survives the redirect", "body": "session()->setFlashdata('message', 'Task added!');\nreturn redirect()->to('/tasks');\n// On the next request:\nsession()->getFlashdata('message');", "page": 10}, {"title": "Hash and verify are a pair", "body": "$hash = password_hash($plainPassword, PASSWORD_DEFAULT);\npassword_verify($typedPassword, $storedHash);\n// Store the hash, never the plain password.", "page": 19}, {"title": "Protect the route", "body": "AuthFilter implements FilterInterface. before() checks login state; register auth in app/Config/Filters.php and attach it to protected routes.", "page": 29}, {"title": "Identity is only one check", "body": "A login filter establishes authentication. Role and ownership checks require additional logic. Keep only user_id, username, and small login values in session.", "page": 31}]}, {"id": 5, "title": "Laravel foundations", "subtitle": "Artisan · routes · Blade", "framework": "Laravel", "file": "IT0049 - M5 - Laravel Foundations.pdf", "pages": 34, "notes": [{"title": "Find the Laravel equivalents", "body": "Routes: routes/web.php. Controllers: app/Http/Controllers. Views: resources/views/*.blade.php. Local settings: .env. Public entry point: public/.", "page": 20}, {"title": "Artisan commands", "body": "php artisan serve\nphp artisan list\nphp artisan route:list\nphp artisan make:controller PageController", "page": 26}, {"title": "Connect a page", "body": "Route::get('/about', [PageController::class, 'about']);\n// Controller:\nreturn view('about', ['course' => 'IT0049']);\n// Blade:\n{{ $course }}", "page": 27}, {"title": "Static pages and parameters", "body": "Route::view('/about', 'about');\nRoute::get('/tasks/{id}', function ($id) {\n    return 'Task ID: ' . $id;\n});", "page": 21}, {"title": "Escape normal output", "body": "{{ $title }} escapes its value. {!! $title !!} prints raw output and should not be used for untrusted input.", "page": 32}]}, {"id": 6, "title": "Laravel data layer", "subtitle": "Migrations · seeders · Eloquent", "framework": "Laravel", "file": "IT0049 - M6 - Laravel Data Layer.pdf", "pages": 34, "notes": [{"title": "Four database responsibilities", "body": "Settings live in .env; schema in migrations; sample data in seeders; record logic in Eloquent models.", "page": 6}, {"title": "Schema tools", "body": "$table->id();\n$table->string('title', 150);\n$table->string('status', 20)->default('pending');\n$table->timestamps();", "page": 10}, {"title": "Know the reset differences", "body": "migrate runs pending migrations. migrate:rollback undoes the last batch. migrate:fresh rebuilds all tables and erases existing data.", "page": 12}, {"title": "Eloquent retrieval", "body": "Task::all();\nTask::where('status', 'pending')\n    ->orderBy('created_at', 'desc')->get();\nTask::findOrFail($id);", "page": 24}, {"title": "Records become model objects", "body": "protected $fillable = ['title', 'status'];\nreturn view('tasks.index', compact('tasks'));\n// In Blade:\n@foreach ($tasks as $task)\n    {{ $task->title }}\n@endforeach", "page": 19}]}, {"id": 7, "title": "Laravel forms & uploads", "subtitle": "Requests · updates · storage", "framework": "Laravel", "file": "IT0049 - M7 - Laravel Forms, Validation, and File Upload.pdf", "pages": 35, "notes": [{"title": "Create versus store", "body": "GET /tasks/create calls create() to show a form. POST /tasks calls store() to accept the submitted data. Include @csrf.", "page": 8}, {"title": "Validation and feedback", "body": "$validated = $request->validate([\n    'title' => ['required', 'string', 'max:100'],\n]);\n// Blade: @error('title') ... {{ $message }} ... @enderror\n// old('title') restores submitted input.", "page": 13}, {"title": "Updates use method spoofing", "body": "<form method=\"POST\" action=\"...\">\n    @csrf\n    @method('PATCH')\n    <input name=\"title\" value=\"{{ old('title', $task->title) }}\">\n</form>", "page": 22}, {"title": "Public upload pipeline", "body": "$path = $request->file('attachment')\n    ->store('attachments', 'public');\n$task->update(['attachment' => $path]);\n// Run php artisan storage:link for public display.", "page": 25}, {"title": "Keep replacement files safe", "body": "Validate type and size first. Store the replacement successfully, update the saved path, and then clean up the old file. The final checklist clarifies the shortened example on page 28.", "page": 33}, {"title": "Move larger rule sets", "body": "php artisan make:request UpdateTaskRequest creates a Form Request class. Put the longer rules in rules() to keep the controller focused.", "page": 30}]}, {"id": 8, "title": "Laravel CRUD, auth & email", "subtitle": "Resources · access · mail", "framework": "Laravel", "file": "IT0049 - M8 - Laravel Full CRUD, Auth, and Email Notifications.pdf", "pages": 35, "notes": [{"title": "The seven resource actions", "body": "index = list; create = new form; store = insert; show = details; edit = edit form; update = save edits; destroy = delete.", "page": 10}, {"title": "Protect resource routes", "body": "Route::middleware('auth')->group(function () {\n    Route::resource('tasks', TaskController::class);\n});", "page": 19}, {"title": "Scope tasks to their owner", "body": "$request->user()->tasks()->create($validated);\n$tasks = $request->user()->tasks()->latest()->get();\n// User: hasMany(Task::class); tasks table: user_id foreign key.", "page": 21}, {"title": "A mailable has a view", "body": "php artisan make:mail TaskCompletedMail --markdown=mail.tasks.completed\n// app/Mail/TaskCompletedMail.php\n// resources/views/mail/tasks/completed.blade.php", "page": 26}, {"title": "Send after the successful update", "body": "if ($task->wasChanged('status') && $task->status === 'done') {\n    Mail::to($request->user()->email)\n        ->send(new TaskCompletedMail($task));\n}", "page": 33}, {"title": "Read classroom examples in context", "body": "Breeze is the scaffold shown in this module. SMTP settings live in .env. Authentication protects entry; checking the owner of a specific record remains a separate access decision.", "page": 18}]}], "questions": [{"id": "m1q1", "module": 1, "page": 8, "topic": "Frameworks", "prompt": "Why use a web application framework?", "answer": "To reuse tools for repetitive web tasks", "choices": ["To reuse tools for repetitive web tasks", "To generate every application's business rule automatically", "To make all server-side validation unnecessary", "To combine data access and HTML into every route"], "explanation": "The module describes routing, database access, validation, and organization as repeated tasks a framework helps handle.", "kind": "concept"}, {"id": "m1q2", "module": 1, "page": 12, "topic": "MVC", "prompt": "Which MVC component manages data and business rules?", "answer": "Model", "choices": ["Model", "Controller", "View", "Router"], "explanation": "The Model retrieves and changes data and holds business rules; it does not handle HTML presentation.", "kind": "concept"}, {"id": "m1q3", "module": 1, "page": 14, "topic": "MVC", "prompt": "Which MVC component coordinates the request, Model, and View?", "answer": "Controller", "choices": ["Controller", "Model", "View", "Database driver"], "explanation": "The Controller receives the request, asks the Model for data, and passes data to a View.", "kind": "concept"}, {"id": "m1q4", "module": 1, "page": 13, "topic": "MVC", "prompt": "Which folder contains CodeIgniter view templates?", "answer": "app/Views", "choices": ["app/Views", "app/Controllers", "app/Models", "app/Config"], "explanation": "CodeIgniter views are PHP templates in app/Views. resources/views belongs to Laravel.", "kind": "concept"}, {"id": "m1q5-v2", "module": 1, "page": 15, "topic": "MVC responsibilities", "prompt": "A task-list page needs a new layout, but its records and filtering stay the same. Where should the main change occur?", "answer": "The view that presents the supplied records", "choices": ["The view that presents the supplied records", "The model that selects pending records", "The route that captures a numeric ID", "The database connection configuration"], "explanation": "A presentation change belongs in the view. The controller can pass the same data, and the model can keep the same query.", "kind": "application"}, {"id": "m1q6", "module": 1, "page": 26, "topic": "Structure", "prompt": "Which directory should be the web server document root?", "answer": "public/", "choices": ["public/", "The entire project root", "app/", "writable/"], "explanation": "Only public/ should be directly web accessible. Application files, logs, and dependencies stay outside it.", "kind": "concept"}, {"id": "m1q7", "module": 1, "page": 27, "topic": "CLI", "prompt": "Which command starts CodeIgniter’s development server?", "answer": "php spark serve", "choices": ["php spark serve", "php spark routes", "php artisan serve", "composer create-project"], "explanation": "Spark is CodeIgniter’s command-line tool; serve starts the development server.", "kind": "concept"}, {"id": "m1q8-v2", "module": 1, "page": 14, "topic": "MVC responsibilities", "prompt": "Two pages need the same pending-task query. Which arrangement best preserves MVC responsibilities?", "answer": "Reuse the data-access logic and supply each view through its controller", "choices": ["Reuse the data-access logic and supply each view through its controller", "Copy the SQL into both view templates", "Move the templates into the model", "Make the route contain the SQL and HTML"], "explanation": "Shared data-access logic belongs in the data layer. Separate views can display the same records without duplicating database work.", "kind": "application"}, {"id": "m1q9", "module": 1, "page": 35, "topic": "Routing", "prompt": "What does 'Pages::about' identify in a route?", "answer": "The about() method of the Pages controller", "choices": ["The about() method of the Pages controller", "The Pages view and its about variable", "The Pages model and its about attribute", "A public file path Pages/about.php"], "explanation": "The text before :: is the controller and the text after it is its action method.", "kind": "concept"}, {"id": "m1q10", "module": 1, "page": 37, "topic": "Routing", "prompt": "In '/profile/(:num)' → 'Pages::profile/$1', what is $1?", "answer": "The first captured route value", "choices": ["The first captured route value", "The first database result automatically", "The first query-string value automatically", "The number of components in the URL"], "explanation": "The numeric URL segment is captured and passed as the first argument to profile().", "kind": "concept"}, {"id": "m1q11", "module": 1, "page": 38, "topic": "Routing", "prompt": "Which route placeholder restricts a match to a single segment without a slash?", "answer": "(:segment)", "choices": ["(:segment)", "(:any)", "(:num)", "(:alpha)"], "explanation": "(:segment) excludes forward slashes; (:any) may include multiple segments.", "kind": "concept"}, {"id": "m1q12-v2", "module": 1, "page": 15, "topic": "Request flow", "prompt": "A controller receives records correctly, but the browser shows an empty list. Which connection should you inspect next?", "answer": "The data passed to the view and the variable the view reads", "choices": ["The data passed to the view and the variable the view reads", "The Composer version used to install PHP packages", "The public folder's favicon filename", "The HTTP method of an unrelated About route"], "explanation": "Trace the existing evidence: retrieval already works. Check the controller-to-view data key and the view's loop before changing the query.", "kind": "application"}, {"id": "m1q13", "module": 1, "page": 45, "topic": "Views", "prompt": "Which helper renders a CodeIgniter view?", "answer": "view()", "choices": ["view()", "model()", "redirect()", "session()"], "explanation": "view() loads a template from app/Views and renders it.", "kind": "concept"}, {"id": "m1q14", "module": 1, "page": 49, "topic": "Views", "prompt": "If a controller passes ['name' => 'Pages'] to view(), what variable is available?", "answer": "$name", "choices": ["$name", "$Pages", "$data['name'] automatically", "$view['Pages'] automatically"], "explanation": "Each key in the data array becomes a variable inside the view.", "kind": "concept"}, {"id": "m1q15-v2", "module": 1, "page": 35, "topic": "Route matching", "prompt": "Only GET /about is registered. A form sends POST /about. Why does that handler not match?", "answer": "The request method differs from the registered route method", "choices": ["The request method differs from the registered route method", "The view name must also be about.post", "POST always calls the controller's index method", "The URL must include the controller namespace"], "explanation": "A route matches both the HTTP method and path. Sharing a path does not make a GET route accept POST.", "kind": "application"}, {"id": "m1q16", "module": 1, "page": 51, "topic": "Views", "prompt": "Which view name loads app/Views/directory-name/about.php?", "answer": "directory-name/about", "choices": ["directory-name/about", "directory-name.about", "app/Views/directory-name/about.php", "directory-name/about.blade"], "explanation": "The CodeIgniter view name includes its relative subdirectory with a slash.", "kind": "concept"}, {"id": "m1q17-v2", "module": 1, "page": 37, "topic": "Route parameters", "prompt": "A numeric route sends /profile/42 to Pages::profile/$1. What value should profile receive?", "answer": "42 from the captured path component", "choices": ["42 from the captured path component", "The first row returned by a model", "The number of path components", "The literal string $1"], "explanation": "The placeholder captures the numeric path component. The handler's $1 forwards that capture; it does not query a database.", "kind": "application"}, {"id": "m1q18-v2", "module": 1, "page": 47, "topic": "Render versus redirect", "prompt": "An action must render an About template during the current request. Which operation matches that goal?", "answer": "return view('about')", "choices": ["return view('about')", "return redirect()->to('/about')", "Create an about.php file without returning content", "Change app.baseURL to /about"], "explanation": "Rendering returns template content in the current response. A redirect tells the browser to make another request.", "kind": "application"}, {"id": "m1q19-v2", "module": 1, "page": 50, "topic": "View composition", "prompt": "A controller renders a header and footer, but returns only the main view string. What should combine the fragments?", "answer": "Concatenate the intended view results with the dot operator", "choices": ["Concatenate the intended view results with the dot operator", "Call the model once for each fragment", "Register each fragment as a separate GET route", "Put the header filename in app.baseURL"], "explanation": "The rendered views are strings. Concatenation returns the fragments in the intended order as one response body.", "kind": "application"}, {"id": "m1q20-v2", "module": 1, "page": 27, "topic": "Local setup", "prompt": "php spark serve fails because the shell cannot find spark. PHP itself works. What should you check first?", "answer": "Whether the shell is inside the CodeIgniter project directory", "choices": ["Whether the shell is inside the CodeIgniter project directory", "Whether the About view has a heading", "Whether the database contains a tasks table", "Whether the browser has a login cookie"], "explanation": "Spark is the project's command-line entry file. A valid PHP installation does not make that project file available from every directory.", "kind": "application"}, {"id": "m1q21-v2", "module": 1, "page": 29, "topic": "Testing assumptions", "prompt": "The welcome page loads. Which conclusion is justified?", "answer": "The application can serve that page", "choices": ["The application can serve that page", "All database queries work", "All form submissions pass validation", "All private routes require authentication"], "explanation": "A successful page verifies only the code path it exercises. It does not test database access, form validation, or protected routes automatically.", "kind": "application"}, {"id": "m1q22-v2", "module": 1, "page": 33, "topic": "URL interpretation", "prompt": "For /reports/monthly?page=2, which part belongs to the query string?", "answer": "page=2", "choices": ["page=2", "reports/monthly", "monthly?page", "The GET method"], "explanation": "The question mark separates query data from the path. A query value is not another slash-separated route component.", "kind": "application"}, {"id": "m1q23-v2", "module": 1, "page": 14, "topic": "MVC responsibilities", "prompt": "A developer changes a task view so it directly performs SQL queries. What problem does this introduce?", "answer": "Presentation now contains data-access responsibilities", "choices": ["Presentation now contains data-access responsibilities", "The route automatically becomes a POST route", "The model becomes unnecessary for every other page", "The database connection becomes private automatically"], "explanation": "Mixing data access into templates makes responsibilities harder to test and reuse. The controller should obtain records through the data layer.", "kind": "application"}, {"id": "m1q24-v2", "module": 1, "page": 31, "topic": "Configuration", "prompt": "The app moves from one local address to another, but generated links still use the old address. What should you inspect?", "answer": "app.baseURL for the active environment", "choices": ["app.baseURL for the active environment", "The primary-key setting of the task model", "The namespace of every view file", "The number of Composer dependencies"], "explanation": "The base URL supplies the application's base address. Route and template correctness do not update a stale base-address setting.", "kind": "application"}, {"id": "m1q25-v2", "module": 1, "page": 8, "topic": "Framework purpose", "prompt": "A developer says a framework automatically decides whether users may delete a task. What is the best correction?", "answer": "The developer still defines and applies the application's access rules", "choices": ["The developer still defines and applies the application's access rules", "MVC gives every authenticated user deletion permission", "Using Composer automatically protects every route", "A view's Delete button establishes server permission"], "explanation": "A framework supplies reusable tools and structure. Application-specific permissions still need deliberate checks and correct configuration.", "kind": "application"}, {"id": "m1q26-v2", "module": 1, "page": 16, "topic": "MVC without a database", "prompt": "A static contact page only needs a template. Which design fits the taught MVC approach?", "answer": "A route and controller can return the view without a model query", "choices": ["A route and controller can return the view without a model query", "Every request must read a database table", "The view must create a dummy model", "The model must return the contact page HTML"], "explanation": "MVC separates responsibilities; it does not require every action to use every layer. A static page does not need artificial database work.", "kind": "application"}, {"id": "m1q27-v2", "module": 1, "page": 24, "topic": "Folders and roles", "prompt": "Logs fail to save, while public images load correctly. Which folder's role is relevant to investigate?", "answer": "writable/ and its write access", "choices": ["writable/ and its write access", "app/Views/ as the only writable folder", "vendor/ as the public upload directory", "app/Controllers/ as the log destination"], "explanation": "CodeIgniter uses writable/ for generated internal data such as logs and cache. Public asset delivery is a different responsibility.", "kind": "application"}, {"id": "m1q28-v2", "module": 1, "page": 34, "topic": "Route diagnosis", "prompt": "A new controller method exists, but the intended URL does not reach it. What is the most useful first comparison?", "answer": "The registered method/path/handler against the actual request", "choices": ["The registered method/path/handler against the actual request", "The number of tables against the number of views", "The page title against the project directory name", "The Composer package count against the route count"], "explanation": "A controller method alone does not establish an explicit route. Check the request method, URL pattern, and selected controller method together.", "kind": "application"}, {"id": "m1q29-v2", "module": 1, "page": 38, "topic": "Route parameters", "prompt": "A route uses (:num) for an ID. Why does /profile/alex fail to match that pattern?", "answer": "The captured component is not numeric", "choices": ["The captured component is not numeric", "The controller must first render a view", "The query string contains no id key", "The framework requires every ID in a session"], "explanation": "The route restricts the path component to digits. A readable word requires a compatible pattern and matching application behavior.", "kind": "application"}, {"id": "m1q30", "module": 1, "page": 21, "topic": "Routes, MVC & setup", "prompt": "Which command checks Composer's installation?", "answer": "composer --version", "choices": ["composer --version", "php --version", "composer install", "composer create-project"], "explanation": "composer --version. The module lists PHP 8.1 or newer, Composer, an editor, and a local PHP/MySQL setup such as XAMPP. Treat the stated PHP version as the PDF’s classroom requirement; an actual framework release may require a different minimum. Composer manages PHP packages. Install it on the machine, then check it with composer --version.", "kind": "concept"}, {"id": "m1q31-v2", "module": 1, "page": 38, "topic": "Route parameters", "prompt": "An article route needs exactly one slug component, excluding slashes. Which placeholder best states that requirement?", "answer": "(:segment)", "choices": ["(:segment)", "(:any)", "(:num)", "(:alpha)"], "explanation": "A segment accepts one component without a slash. any can span slashes, num accepts digits, and alpha would reject slugs containing hyphens.", "kind": "application"}, {"id": "m1q32-v2", "module": 1, "page": 38, "topic": "Route parameters", "prompt": "A download handler intentionally receives folders/report.pdf as one captured remainder. Which pattern fits?", "answer": "(:any)", "choices": ["(:any)", "(:segment)", "(:num)", "(:alpha)"], "explanation": "The any placeholder can capture across slashes. Use it only when the handler intentionally accepts the remaining path.", "kind": "application"}, {"id": "m1q33-v2", "module": 1, "page": 26, "topic": "Public directory", "prompt": "A server lets visitors download internal application files. Which configuration should you inspect first?", "answer": "Whether the document root points to public/", "choices": ["Whether the document root points to public/", "Whether the controller extends BaseController", "Whether the title is passed as a view variable", "Whether the About route uses GET"], "explanation": "The document root defines the publicly served boundary. Serving the entire project can expose source and configuration files.", "kind": "application"}, {"id": "m1q34", "module": 1, "page": 24, "topic": "Routes, MVC & setup", "prompt": "Which folder contains Composer packages?", "answer": "vendor/", "choices": ["vendor/", "app/Config/", "writable/", "public/"], "explanation": "vendor/. Framework directories separate source, public files, and generated data. Putting a file in another role can break that boundary.", "kind": "concept"}, {"id": "m1q35", "module": 1, "page": 25, "topic": "Routes, MVC & setup", "prompt": "Where is Routes.php in CodeIgniter?", "answer": "app/Config/", "choices": ["app/Config/", "app/Controllers/", "app/Views/", "public/"], "explanation": "app/Config/. CI_ENVIRONMENT selects environment behavior. app.baseURL is the application’s base address; <mark>keep its trailing slash</mark>. Match it to the server you actually use. app/Config/App.php provides application configuration too; .env can supply the local value. The PDF also sets $indexPage = '' to omit index.php from generated URLs. That setting alone does not configure Apache rewriting.", "kind": "concept"}, {"id": "m1q36", "module": 1, "page": 26, "topic": "Routes, MVC & setup", "prompt": "Why keep app/ outside the public document root?", "answer": "To prevent direct public access to internal source files", "choices": ["To prevent direct public access to internal source files", "To disable requests to every controller", "To make public assets unavailable", "To make the model create database tables automatically"], "explanation": "The web root defines the public file boundary. Internal source and credentials belong outside that publicly served directory.", "kind": "concept"}, {"id": "m1q37", "module": 1, "page": 26, "topic": "Routes, MVC & setup", "prompt": "What does URL rewriting direct requests through?", "answer": "The front controller index.php", "choices": ["The front controller index.php", "Every URL directly to its view file", "Only the first migration in the project", "The browser's local PHP interpreter"], "explanation": "URL rewriting sends a clean incoming path through the front controller. It is distinct from merely omitting index.php when generating links.", "kind": "concept"}, {"id": "m1q38", "module": 1, "page": 27, "topic": "Routes, MVC & setup", "prompt": "From which directory should php spark serve run?", "answer": "The CodeIgniter project directory", "choices": ["The CodeIgniter project directory", "Any folder containing a PHP file", "Only the public directory", "Only the vendor directory"], "explanation": "Spark belongs to the CodeIgniter project. Run the command from the directory that contains its spark entry file.", "kind": "concept"}, {"id": "m1q39-v2", "module": 1, "page": 32, "topic": "Clean URLs", "prompt": "Generated links omit index.php after a configuration change, but clean URLs still fail under Apache. What remains to check?", "answer": "Apache rewriting and its public-directory setup", "choices": ["Apache rewriting and its public-directory setup", "Whether view strings use the dot operator", "Whether all routes return JSON", "Whether every controller defines a model"], "explanation": "The indexPage setting changes generated URLs. Apache must still direct the incoming clean URL through the front controller.", "kind": "application"}, {"id": "m1q40", "module": 1, "page": 29, "topic": "Routes, MVC & setup", "prompt": "What does the default welcome page confirm?", "answer": "The application starts and serves that page", "choices": ["The application starts and serves that page", "Every database credential is correct", "Every write route validates its input", "All private records have ownership checks"], "explanation": "A test verifies only the path it exercises. A welcome page does not prove database access, validation, or route protection.", "kind": "concept"}, {"id": "m1q41", "module": 1, "page": 30, "topic": "Routes, MVC & setup", "prompt": "Which variable selects the CI environment?", "answer": "CI_ENVIRONMENT", "choices": ["CI_ENVIRONMENT", "APP_ENV", "app.baseURL", "app.indexPage"], "explanation": "CI_ENVIRONMENT. CI_ENVIRONMENT selects environment behavior. app.baseURL is the application’s base address; <mark>keep its trailing slash</mark>. Match it to the server you actually use. app/Config/App.php provides application configuration too; .env can supply the local value. The PDF also sets $indexPage = '' to omit index.php from generated URLs. That setting alone does not configure Apache rewriting.", "kind": "concept"}, {"id": "m1q42-v2", "module": 1, "page": 49, "topic": "View data", "prompt": "A controller calls view('profile', ['displayName' => $name]). The template reads $name and reports an undefined variable. What is the direct correction?", "answer": "Read $displayName or change the data key to name", "choices": ["Read $displayName or change the data key to name", "Rename the route to displayName", "Store $name in the database first", "Call index() before rendering the template"], "explanation": "The view-data array key becomes the view variable. The local controller variable name does not automatically become the view variable.", "kind": "application"}, {"id": "m1q43", "module": 1, "page": 32, "topic": "Routes, MVC & setup", "prompt": "What does an empty indexPage setting affect?", "answer": "The index.php segment in generated URLs", "choices": ["The index.php segment in generated URLs", "The web server's rewrite configuration automatically", "The controller action selected by every route", "The database's primary-key column"], "explanation": "indexPage controls the entry-file segment in generated URLs. The web server must separately handle incoming clean paths.", "kind": "concept"}, {"id": "m1q44-v2", "module": 1, "page": 33, "topic": "Routes, MVC & setup", "prompt": "In the URL suffix ?page=2, what is page=2?", "answer": "The query string", "choices": ["The query string", "A path segment after reports", "An HTTP response header", "The controller namespace"], "explanation": "The question mark introduces query data. page=2 is not a slash-separated path component or a controller method.", "kind": "concept"}, {"id": "m1q45", "module": 1, "page": 34, "topic": "Routes, MVC & setup", "prompt": "Where are explicit CI route rules kept?", "answer": "app/Config/Routes.php", "choices": ["app/Config/Routes.php", "app/Controllers/Routes.php", "routes/web.php", "public/Routes.php"], "explanation": "app/Config/Routes.php. An explicit CodeIgniter route combines HTTP method + path pattern + handler. Routes belong in app/Config/Routes.php.", "kind": "concept"}, {"id": "m1q46", "module": 1, "page": 35, "topic": "Routes, MVC & setup", "prompt": "In Pages::about, what is about?", "answer": "The controller method", "choices": ["The controller method", "The view-data key", "The PHP namespace", "The route's HTTP method"], "explanation": "The handler string identifies a controller and selected action. Its action name is not a template or database setting.", "kind": "concept"}, {"id": "m1q47", "module": 1, "page": 35, "topic": "Routes, MVC & setup", "prompt": "Which request matches a get() route?", "answer": "GET", "choices": ["GET", "POST", "PATCH", "DELETE"], "explanation": "GET. A web application lets a user work through a browser while application code runs on a server. In this course, PHP is the server-side language. The browser sends an HTTP request, such as GET /about. The server runs the matching code and sends a response, often HTML. The browser displays that response; it does not execute the server’s PHP source.", "kind": "concept"}, {"id": "m1q48", "module": 1, "page": 37, "topic": "Routes, MVC & setup", "prompt": "What does $1 refer to in the handler string?", "answer": "The first captured route value", "choices": ["The first captured route value", "The first returned row automatically", "The first session value automatically", "A result limit of one"], "explanation": "The captured path value is forwarded to the handler. It is not automatically a database row or session value.", "kind": "concept"}, {"id": "m1q49", "module": 1, "page": 38, "topic": "Routes, MVC & setup", "prompt": "Which placeholder accepts one path component without a slash?", "answer": "(:segment)", "choices": ["(:segment)", "(:any)", "(:num)", "(:alpha)"], "explanation": "(:segment). Check the complete route match. A route requires the correct HTTP method and path. A public controller method does not register its own explicit route. (:any) can capture multiple path components, while (:segment) captures one. (:hash) communicates the intended identifier type but does not hash, decode, or validate an identifier's ownership.", "kind": "concept"}, {"id": "m1q50", "module": 1, "page": 38, "topic": "Routes, MVC & setup", "prompt": "Which placeholder can capture the remaining path across slashes?", "answer": "(:any)", "choices": ["(:any)", "(:segment)", "(:num)", "(:alpha)"], "explanation": "(:any). Check the complete route match. A route requires the correct HTTP method and path. A public controller method does not register its own explicit route. (:any) can capture multiple path components, while (:segment) captures one. (:hash) communicates the intended identifier type but does not hash, decode, or validate an identifier's ownership.", "kind": "concept"}, {"id": "m1q51", "module": 1, "page": 38, "topic": "Routes, MVC & setup", "prompt": "Which placeholder communicates a hashed-ID intent but matches like segment?", "answer": "(:hash)", "choices": ["(:hash)", "(:segment)", "(:any)", "(:num)"], "explanation": "(:hash). Check the complete route match. A route requires the correct HTTP method and path. A public controller method does not register its own explicit route. (:any) can capture multiple path components, while (:segment) captures one. (:hash) communicates the intended identifier type but does not hash, decode, or validate an identifier's ownership.", "kind": "concept"}, {"id": "m1q52", "module": 1, "page": 38, "topic": "Routes, MVC & setup", "prompt": "Which placeholder accepts alphabetic characters?", "answer": "(:alpha)", "choices": ["(:alpha)", "(:segment)", "(:any)", "(:num)"], "explanation": "alpha restricts a matching component to letters. Numeric and multi-segment placeholders express different accepted shapes.", "kind": "concept"}, {"id": "m1q53-v2", "module": 1, "page": 51, "topic": "View paths", "prompt": "A template exists at app/Views/account/profile.php. Which view identifier loads it?", "answer": "account/profile", "choices": ["account/profile", "account.profile.blade", "App\\Controllers\\account\\profile", "public/account/profile.php"], "explanation": "CodeIgniter's view identifier refers to the path beneath app/Views without the .php extension. Laravel's dot convention is a separate framework pattern.", "kind": "application"}, {"id": "m1q54", "module": 1, "page": 40, "topic": "Routes, MVC & setup", "prompt": "Which namespace fits a CodeIgniter controller at app/Controllers/Pages.php?", "answer": "App\\Controllers", "choices": ["App\\Controllers", "App\\Models", "App\\Config", "CodeIgniter\\Controllers"], "explanation": "A controller under app/Controllers uses the matching application controller namespace. Namespaces determine class resolution, not URLs.", "kind": "concept"}, {"id": "m1q55", "module": 1, "page": 42, "topic": "Routes, MVC & setup", "prompt": "Does an explicit Pages::about route run index() first?", "answer": "No; it targets about()", "choices": ["No; it targets about()", "Yes; index always runs first", "Yes; help actions inherit index output automatically", "Only when the handler returns a view"], "explanation": "An explicit handler invokes its selected action. index is a conventional default method, not a mandatory predecessor.", "kind": "concept"}, {"id": "m1q56-v2", "module": 1, "page": 44, "topic": "Routes, MVC & setup", "prompt": "Which change can expose internal files when attempting to remove /public from a deployment URL?", "answer": "Moving public entry files into the project root without preserving the public boundary", "choices": ["Moving public entry files into the project root without preserving the public boundary", "Pointing the document root at public/", "Keeping credentials outside public access", "Keeping controller source under app/"], "explanation": "Keep the intended public-directory boundary. Removing index.php from a URL does not justify exposing internal source files.", "kind": "concept"}, {"id": "m1q57-v2", "module": 1, "page": 42, "topic": "Controller dispatch", "prompt": "GET /help explicitly targets Pages::help. Which statement describes index() for this request?", "answer": "It does not run automatically before help()", "choices": ["It does not run automatically before help()", "It always runs immediately before help()", "It supplies every view variable implicitly", "It replaces help() whenever no model exists"], "explanation": "An explicit route targets the selected method. index() is a conventional default action, not a mandatory first step for other methods.", "kind": "application"}, {"id": "m1q58", "module": 1, "page": 47, "topic": "Routes, MVC & setup", "prompt": "What does return view('about') do?", "answer": "Render the about template", "choices": ["Render the about template", "Redirect the browser to /about", "Create a template file named about.php", "Invoke Pages::about automatically"], "explanation": "Render the about template. A route selects an action; the action passes named data into a view. A template identifier is separate from a browser URL.", "kind": "concept"}, {"id": "m1q59", "module": 1, "page": 50, "topic": "Routes, MVC & setup", "prompt": "Which PHP operator joins rendered view strings?", "answer": "The dot operator", "choices": ["The dot operator", "The addition operator", "The object-access operator", "The null-coalescing operator"], "explanation": "The dot operator. A route selects an action; the action passes named data into a view. A template identifier is separate from a browser URL.", "kind": "concept"}, {"id": "m1q60", "module": 1, "page": 51, "topic": "Routes, MVC & setup", "prompt": "What does view('directory-name/about') identify?", "answer": "A view in a subdirectory", "choices": ["A view in a subdirectory", "A controller in a nested namespace", "An absolute filesystem path", "A database table with a slash in its name"], "explanation": "A view in a subdirectory. A route selects an action; the action passes named data into a view. A template identifier is separate from a browser URL.", "kind": "concept"}, {"id": "m2q1", "module": 2, "page": 6, "topic": "Persistence", "prompt": "Why does a task manager need a database?", "answer": "To persist records across requests and restarts", "choices": ["To persist records across requests and restarts", "To make every input valid automatically", "To make a local controller array persist automatically", "To let the browser execute SQL directly"], "explanation": "A database stores persistent, shared records instead of temporary page values.", "kind": "concept"}, {"id": "m2q2-v2", "module": 2, "page": 15, "topic": "Connection diagnosis", "prompt": "A task page reports Connection refused before executing its query. Which check comes first?", "answer": "Check whether the database service accepts connections at the configured host and port", "choices": ["Check whether the database service accepts connections at the configured host and port", "Rewrite the Blade loop", "Add esc() to the page heading", "Change the task status filter"], "explanation": "Connection refusal concerns reaching the service. A display change or different WHERE condition cannot repair that connection.", "kind": "application"}, {"id": "m2q3-v2", "module": 2, "page": 12, "topic": "Configuration", "prompt": "When a matching database key is set in both .env and Database.php, which takes precedence?", "answer": ".env", "choices": [".env", "Database.php always ignores .env", "The last view rendered", "The request's query-string values automatically"], "explanation": "The matching .env value overrides the fallback configured in app/Config/Database.php.", "kind": "concept"}, {"id": "m2q4-v2", "module": 2, "page": 13, "topic": "Configuration", "prompt": "Why keep database credentials in an uncommitted .env file?", "answer": "They differ by environment and should stay out of shared code", "choices": ["They differ by environment and should stay out of shared code", "They are encrypted automatically by every editor", "They must be visible in a public URL", "They replace all database validation"], "explanation": "The module separates local credentials from application code to reduce accidental sharing.", "kind": "concept"}, {"id": "m2q5-v2", "module": 2, "page": 15, "topic": "Connection diagnosis", "prompt": "The database server responds with Unknown database. What is the most direct investigation?", "answer": "Compare the configured database name with the databases that exist", "choices": ["Compare the configured database name with the databases that exist", "Replace every model with a view", "Change DESC to ASC", "Add more allowed fields"], "explanation": "The service responds, but cannot select the named database. Check the name and database creation before rewriting query logic.", "kind": "application"}, {"id": "m2q6", "module": 2, "page": 19, "topic": "Models", "prompt": "Which built-in class does TaskModel extend?", "answer": "CodeIgniter\\Model", "choices": ["CodeIgniter\\Model", "CodeIgniter\\Controller", "Illuminate\\Database\\Eloquent\\Model", "App\\Controllers\\BaseController"], "explanation": "TaskModel extends CodeIgniter’s Model to inherit common record operations.", "kind": "concept"}, {"id": "m2q7", "module": 2, "page": 20, "topic": "Models", "prompt": "Which model property selects the database table?", "answer": "$table", "choices": ["$table", "$primaryKey", "$allowedFields", "$returnType"], "explanation": "protected $table = 'tasks' identifies the table managed by TaskModel.", "kind": "concept"}, {"id": "m2q8", "module": 2, "page": 20, "topic": "Models", "prompt": "Which property allows specified columns to be saved from input?", "answer": "$allowedFields", "choices": ["$allowedFields", "$table", "$primaryKey", "$returnType"], "explanation": "CodeIgniter uses $allowedFields. Laravel’s corresponding mass-assignment list is $fillable.", "kind": "concept"}, {"id": "m2q9", "module": 2, "page": 22, "topic": "Queries", "prompt": "Which model call retrieves all task rows?", "answer": "$model->findAll()", "choices": ["$model->findAll()", "$model->find(1)", "$model->first()", "$model->countAllResults()"], "explanation": "findAll() returns multiple records; find($id) retrieves a record by primary key.", "kind": "concept"}, {"id": "m2q10", "module": 2, "page": 23, "topic": "Queries", "prompt": "Which model call retrieves the row with primary key 3?", "answer": "$model->find(3)", "choices": ["$model->find(3)", "$model->findAll(3)", "$model->limit(3)->findAll()", "$model->where('status', '3')->first()"], "explanation": "find(3) looks up the primary key value 3.", "kind": "concept"}, {"id": "m2q11", "module": 2, "page": 24, "topic": "Queries", "prompt": "What does $model->where('status', 'pending')->findAll() return?", "answer": "Only rows whose status is pending", "choices": ["Only rows whose status is pending", "All rows sorted by their status", "One row whose primary key is pending", "The number of pending rows only"], "explanation": "where() filters the rows; findAll() retrieves the matching records.", "kind": "concept"}, {"id": "m2q12", "module": 2, "page": 25, "topic": "Queries", "prompt": "What is the effect of orderBy('created_at', 'DESC')?", "answer": "Newest creation dates first", "choices": ["Newest creation dates first", "Oldest creation dates first", "Only completed tasks", "A limit of one newest record"], "explanation": "Descending creation timestamps place the most recent records first.", "kind": "concept"}, {"id": "m2q13", "module": 2, "page": 27, "topic": "Queries", "prompt": "Which method counts matching rows rather than retrieving them?", "answer": "countAllResults()", "choices": ["countAllResults()", "findAll()", "find()", "first()"], "explanation": "countAllResults() returns the count of matching results.", "kind": "concept"}, {"id": "m2q14-v2", "module": 2, "page": 15, "topic": "Connection diagnosis", "prompt": "A database connection returns Access denied. Which information is most relevant?", "answer": "The configured account, password, and permitted access", "choices": ["The configured account, password, and permitted access", "The task view's heading level", "The number of rows requested by findAll()", "The order of the route declarations"], "explanation": "Access denied points to database account authentication or privileges. It does not by itself indicate a template problem.", "kind": "application"}, {"id": "m2q15", "module": 2, "page": 32, "topic": "Views", "prompt": "What variable is created by view('tasks/show', ['task' => $task])?", "answer": "$task", "choices": ["$task", "$tasks", "$show", "$data['task'] automatically"], "explanation": "The array key task becomes the $task variable inside the show view.", "kind": "concept"}, {"id": "m2q16", "module": 2, "page": 34, "topic": "Missing records", "prompt": "What does CodeIgniter find($id) return when the row does not exist?", "answer": "null", "choices": ["null", "An empty collection of all tasks", "A new unsaved task model automatically", "A rendered 404 page automatically"], "explanation": "The controller must check for null and deliberately respond with a not-found exception.", "kind": "concept"}, {"id": "m2q17-v2", "module": 2, "page": 27, "topic": "Count versus records", "prompt": "A badge needs the number of pending tasks, not their full titles. Which approach best matches that output?", "answer": "Filter pending tasks and call countAllResults()", "choices": ["Filter pending tasks and call countAllResults()", "Call find(1) and count its title characters", "Call view('tasks') and count HTML tags", "Use orderBy('status') without executing the query"], "explanation": "A count query returns a number for matching rows. A row query or rendered HTML answers a different question.", "kind": "application"}, {"id": "m2q18-v2", "module": 2, "page": 30, "topic": "Output escaping", "prompt": "A stored task title contains <script>alert(1)</script>. Which operation protects its HTML text display?", "answer": "Escape the title at output with esc()", "choices": ["Escape the title at output with esc()", "Sort the title in descending order", "Add title to $allowedFields", "Change the database password"], "explanation": "Output escaping makes the value display as text in the relevant context. Writable-field protection and sorting do not make HTML output safe.", "kind": "application"}, {"id": "m2q19-v2", "module": 2, "page": 21, "topic": "Query values versus output", "prompt": "A developer escapes HTML output and concludes SQL string concatenation is now safe. What distinction is missing?", "answer": "HTML escaping and safe database query construction address different contexts", "choices": ["HTML escaping and safe database query construction address different contexts", "HTML escaping automatically binds every SQL parameter", "Query Builder removes the need for view escaping", "A route placeholder sanitizes all database values"], "explanation": "Use model or Query Builder methods for normal query values, and escape output for its display context. Neither operation replaces the other.", "kind": "application"}, {"id": "m2q20-v2", "module": 2, "page": 29, "topic": "View-data contract", "prompt": "The controller passes ['items' => $tasks], but the view loops over $tasks. Which correction directly addresses the mismatch?", "answer": "Use the same data key and view variable", "choices": ["Use the same data key and view variable", "Change the tasks table name to items", "Remove the model's primary key", "Call countAllResults() instead of findAll()"], "explanation": "The array key passed to view() defines the view variable. The table name does not need to match that presentation variable.", "kind": "application"}, {"id": "m2q21-v2", "module": 2, "page": 30, "topic": "Result shape", "prompt": "A CI model returns array rows. The template uses $task->title. What should you check or change?", "answer": "Use the array access form $task['title'] for that return type", "choices": ["Use the array access form $task['title'] for that return type", "Change the route from GET to POST", "Rename the title column to task", "Call insert() before displaying the row"], "explanation": "The view must match the model's return shape. Array access and object property access are different PHP operations.", "kind": "application"}, {"id": "m2q22-v2", "module": 2, "page": 7, "topic": "Schema defaults", "prompt": "The status column defaults to pending. An insert omits status entirely. What value does that schema supply?", "answer": "pending, assuming the insert succeeds with that default", "choices": ["pending, assuming the insert succeeds with that default", "done because the row is new", "NULL regardless of the default", "The value of the preceding row's status"], "explanation": "A database default supplies the omitted column value. It does not copy another row or infer completion from record creation.", "kind": "application"}, {"id": "m2q23-v2", "module": 2, "page": 7, "topic": "Primary keys", "prompt": "Two tasks have the same title. Which field should a details URL use to identify one row reliably?", "answer": "The unique primary key", "choices": ["The unique primary key", "The repeated title alone", "The current table row position", "The formatted creation date alone"], "explanation": "A primary key identifies the row uniquely. Titles and display order can repeat or change.", "kind": "application"}, {"id": "m2q24-v2", "module": 2, "page": 12, "topic": "Configuration precedence", "prompt": "Database.php has correct credentials, but the active .env specifies another database. Which values should you inspect when the wrong database opens?", "answer": "The matching active .env values", "choices": ["The matching active .env values", "Only the view-data key", "Only the route placeholder", "Only the HTML form action"], "explanation": "Matching environment settings supply local configuration. A correct default does not correct a conflicting active environment value.", "kind": "application"}, {"id": "m2q25-v2", "module": 2, "page": 7, "topic": "Schema constraints", "prompt": "A title column is NOT NULL. Which input is still not rejected merely by that constraint?", "answer": "An empty string", "choices": ["An empty string", "SQL NULL", "An omitted value when no default can satisfy the constraint", "A request to store SQL NULL explicitly"], "explanation": "NOT NULL rejects SQL NULL, not all unusable text. Application validation must enforce meaningful title requirements such as required and minimum length.", "kind": "application"}, {"id": "m2q26-v2", "module": 2, "page": 14, "topic": "Testing evidence", "prompt": "The welcome page works, but nobody has executed a database query yet. What test checks the database connection?", "answer": "Run an action that actually performs a database operation", "choices": ["Run an action that actually performs a database operation", "Refresh the same static welcome page", "Open a CSS file from public/", "Change the browser theme"], "explanation": "A static response does not exercise the database. Test the database through a real operation before concluding its settings work.", "kind": "application"}, {"id": "m2q27-v2", "module": 2, "page": 7, "topic": "Schema versus model", "prompt": "A developer adds notes to $allowedFields, but the tasks table has no notes column. What is still required?", "answer": "A matching database schema change", "choices": ["A matching database schema change", "A new view variable named allowedFields", "A route named notes", "A different sort direction"], "explanation": "allowedFields controls writable model fields. It does not create columns or change the database schema.", "kind": "application"}, {"id": "m2q28-v2", "module": 2, "page": 20, "topic": "Field protection", "prompt": "A submitted field exists in the table but is absent from $allowedFields. Why should the developer inspect the model before changing the form?", "answer": "The model restricts which fields normal writes may persist", "choices": ["The model restricts which fields normal writes may persist", "The table automatically removes all excluded columns", "The route cannot receive any POST fields", "The view must use object syntax for all rows"], "explanation": "Model field protection filters the permitted write fields. The database schema and form inputs are separate parts of the workflow.", "kind": "application"}, {"id": "m2q29-v2", "module": 2, "page": 28, "topic": "Model imports", "prompt": "A controller calls new TaskModel(), but PHP cannot find that class in its namespace. What should you inspect?", "answer": "The model namespace and its import in the controller", "choices": ["The model namespace and its import in the controller", "The database row count", "The order direction in findAll()", "The HTML table caption"], "explanation": "PHP resolves class names through namespaces and imports. A missing import can fail before any database query runs.", "kind": "application"}, {"id": "m2q30-v2", "module": 2, "page": 6, "topic": "Persistence", "prompt": "Tasks stored only in a local controller array disappear on the next fresh request. Which design addresses persistent shared records?", "answer": "Store the records in the database and retrieve them through the model", "choices": ["Store the records in the database and retrieve them through the model", "Add more HTML rows to the same response", "Rename the controller variable on every request", "Call view() twice"], "explanation": "A database persists records across requests. A local variable created during one request is not persistent application storage.", "kind": "application"}, {"id": "m2q31-v2", "module": 2, "page": 27, "topic": "Search intent", "prompt": "A task search should match titles containing a keyword rather than an exact title. Which CI query method expresses that requirement?", "answer": "like('title', $keyword)", "choices": ["like('title', $keyword)", "where('title', $keyword)", "orderBy('title', 'ASC')", "countAllResults() without a title condition"], "explanation": "like() expresses pattern matching. Equality, ordering, and an unfiltered count do not select titles containing the search term.", "kind": "application"}, {"id": "m2q32-v2", "module": 2, "page": 34, "topic": "Failure localization", "prompt": "The controller logs the correct task array, but the details page accesses a different variable name. Which layer needs the immediate correction?", "answer": "The view-data handoff or template variable", "choices": ["The view-data handoff or template variable", "The database service startup", "The schema's AUTO_INCREMENT setting", "The model's table selection"], "explanation": "The successful lookup narrows the failure to presentation and its data contract. Correct that mismatch before changing unrelated database settings.", "kind": "application"}, {"id": "m2q33-v2", "module": 2, "page": 23, "topic": "Single versus multiple records", "prompt": "Task IDs are 2, 8, and 15. What does $model->find(8) select?", "answer": "The row whose primary key is 8", "choices": ["The row whose primary key is 8", "The eighth row in the current display order", "Eight rows beginning at the first record", "Every row with an eight-character title"], "explanation": "find() uses the configured primary key. Its argument is neither a collection position nor a result limit.", "kind": "application"}, {"id": "m2q34", "module": 2, "page": 13, "topic": "Queries & model configuration", "prompt": "Why keep real credentials out of committed config files?", "answer": "To avoid exposing environment secrets", "choices": ["To avoid exposing environment secrets", "To make all database passwords blank", "To remove the database driver", "To disable SQL queries"], "explanation": "Environment credentials vary between machines and can expose private service access. Keep real secrets out of shared committed source.", "kind": "concept"}, {"id": "m2q35", "module": 2, "page": 14, "topic": "Queries & model configuration", "prompt": "Which page is useful for testing actual database access?", "answer": "A page that runs a database query", "choices": ["A page that runs a database query", "A static welcome page with no query", "A public CSS file", "The route table without an executed database action"], "explanation": "Database connectivity requires an actual database operation. Serving a static page exercises neither connection credentials nor a query.", "kind": "concept"}, {"id": "m2q36", "module": 2, "page": 15, "topic": "Queries & model configuration", "prompt": "What does Unknown database usually indicate?", "answer": "The named database does not exist", "choices": ["The named database does not exist", "The configured account has insufficient permission", "The database service refused the connection", "The result set contains no matching tasks"], "explanation": "The server is reachable but cannot select the configured database name. Check its existence and spelling before changing presentation code.", "kind": "concept"}, {"id": "m2q37", "module": 2, "page": 15, "topic": "Queries & model configuration", "prompt": "What does Access denied suggest checking?", "answer": "The database account and password", "choices": ["The database account and password", "Only the configured database name", "Only the table's sort order", "Only whether a Blade file exists"], "explanation": "The service rejects the attempted database account access. Check the configured account, password, and relevant privileges.", "kind": "concept"}, {"id": "m2q38", "module": 2, "page": 15, "topic": "Queries & model configuration", "prompt": "What does Connection refused suggest checking first?", "answer": "Whether the database service is running", "choices": ["Whether the database service is running", "Only whether the requested row exists", "Only whether title is in allowedFields", "Only whether the view uses escaped output"], "explanation": "The connection fails before normal query execution. Check whether the service is running and reachable at the configured address.", "kind": "concept"}, {"id": "m2q39", "module": 2, "page": 18, "topic": "Queries & model configuration", "prompt": "What does the CI model extend?", "answer": "CodeIgniter\\Model", "choices": ["CodeIgniter\\Model", "CodeIgniter\\Controller", "Illuminate\\Database\\Eloquent\\Model", "App\\Controllers\\BaseController"], "explanation": "The framework Model class supplies standard table operations. A controller or template class has a different responsibility.", "kind": "concept"}, {"id": "m2q40", "module": 2, "page": 19, "topic": "Queries & model configuration", "prompt": "Where is TaskModel.php stored?", "answer": "app/Models/", "choices": ["app/Models/", "app/Controllers/", "app/Views/", "app/Config/"], "explanation": "app/Models/. Save this as app/Models/TaskModel.php. The class extends CodeIgniter’s Model, which provides common record methods. $table selects the database table. $primaryKey identifies the column used by primary-key operations such as find($id). $allowedFields lists fields accepted by protected mass-assignment-style writes through the model.", "kind": "concept"}, {"id": "m2q41", "module": 2, "page": 20, "topic": "Queries & model configuration", "prompt": "Which property selects the database table?", "answer": "$table", "choices": ["$table", "$primaryKey", "$allowedFields", "$returnType"], "explanation": "$table. class TaskModel extends Model\n{\n    protected $table = 'tasks';\n    protected $primaryKey = 'id';\n    protected $allowedFields = ['title', 'status'];\n}", "kind": "concept"}, {"id": "m2q42", "module": 2, "page": 20, "topic": "Queries & model configuration", "prompt": "Which property identifies the key used by find($id)?", "answer": "$primaryKey", "choices": ["$primaryKey", "$table", "$allowedFields", "$returnType"], "explanation": "$primaryKey. Choose retrieval by the required result: one primary-key row, a filtered list, or a count. Handle the missing-row case before reading fields.", "kind": "concept"}, {"id": "m2q43", "module": 2, "page": 20, "topic": "Queries & model configuration", "prompt": "Does allowedFields create database columns?", "answer": "No; the schema creates columns", "choices": ["No; the schema creates columns", "Yes; each writable field becomes a column at startup", "Yes; but only after findAll()", "Yes; but only after the view renders"], "explanation": "No; the schema creates columns. Schema columns, writable fields, and validation rules have different responsibilities. A model property does not create a database column.", "kind": "concept"}, {"id": "m2q44-v2", "module": 2, "page": 34, "topic": "Missing records", "prompt": "A details action calls find($id), then immediately reads $task['title']. A nonexistent ID causes an error. What belongs between those operations?", "answer": "Check for a missing result and return an appropriate not-found response", "choices": ["Check for a missing result and return an appropriate not-found response", "Run findAll() and display the first row instead", "Insert an empty task automatically", "Escape the ID as the page title"], "explanation": "A null result has no title field. Detect the missing record before accessing fields; showing another record hides the actual failure.", "kind": "application"}, {"id": "m2q45", "module": 2, "page": 22, "topic": "Queries & model configuration", "prompt": "What is the purpose of new TaskModel()?", "answer": "Create a model object", "choices": ["Create a model object", "Insert a row immediately", "Create the database schema", "Execute findAll() automatically"], "explanation": "Construction creates the PHP model object. It does not itself insert a row, create a table, or render the task list.", "kind": "concept"}, {"id": "m2q46", "module": 2, "page": 22, "topic": "Queries & model configuration", "prompt": "Which helper supplies the alternative model-construction style?", "answer": "model()", "choices": ["model()", "view()", "redirect()", "session()"], "explanation": "model(). class Tasks extends BaseController\n{\n    public function index()\n    {\n        $model = new TaskModel();\n        $data['tasks'] = $model->findAll();\n        return view('tasks/index', $data);\n    }\n}", "kind": "concept"}, {"id": "m2q47", "module": 2, "page": 23, "topic": "Queries & model configuration", "prompt": "What does find(3) use 3 as?", "answer": "A primary-key value", "choices": ["A primary-key value", "The third row in the current display order", "The maximum number of returned rows", "A status value to match"], "explanation": "A primary-key value. Choose retrieval by the required result: one primary-key row, a filtered list, or a count. Handle the missing-row case before reading fields.", "kind": "concept"}, {"id": "m2q48-v2", "module": 2, "page": 24, "topic": "Query execution", "prompt": "A CI model query sets where('status', 'pending') but never executes a retrieval method. What is missing when the controller needs rows?", "answer": "A terminal retrieval such as findAll()", "choices": ["A terminal retrieval such as findAll()", "A call to view() on the query builder", "A change to app.baseURL", "An extra status column"], "explanation": "The filter describes the query. A retrieval method executes it and supplies rows for the controller and view.", "kind": "application"}, {"id": "m2q49", "module": 2, "page": 24, "topic": "Queries & model configuration", "prompt": "Which condition selects pending tasks?", "answer": "where('status', 'pending')", "choices": ["where('status', 'pending')", "orderBy('status', 'ASC')", "where('title', 'pending')", "limit(1)"], "explanation": "where('status', 'pending'). // Return a number instead of the matching rows.\n$count = $model->where('status', 'pending')->countAllResults();", "kind": "concept"}, {"id": "m2q50", "module": 2, "page": 25, "topic": "Queries & model configuration", "prompt": "Which order places larger or later values first?", "answer": "DESC", "choices": ["DESC", "ASC", "The table's insertion order regardless of query", "No ordering clause"], "explanation": "DESC. Query Builder lets PHP method calls describe a query. Normal value arguments are escaped/bound by the framework rather than being pasted into hand-built SQL. This reduces routine SQL mistakes; it does not make arbitrary raw SQL fragments or unvalidated user-chosen SQL identifiers safe.", "kind": "concept"}, {"id": "m2q51", "module": 2, "page": 25, "topic": "Queries & model configuration", "prompt": "Which order places smaller or earlier values first?", "answer": "ASC", "choices": ["ASC", "DESC", "The primary key's type alone", "No ordering clause"], "explanation": "ASC. Read the chain as: keep matching rows → choose their order → retrieve them. where() restricts results; orderBy() sorts them. DESC means descending and ASC ascending. For a creation date, descending usually places newer records first. Equal timestamps may need an additional ordering key if a precise tie order matters.", "kind": "concept"}, {"id": "m2q52", "module": 2, "page": 26, "topic": "Queries & model configuration", "prompt": "Which call retrieves the rows after the CI filter/order chain?", "answer": "findAll()", "choices": ["findAll()", "find()", "first()", "countAllResults()"], "explanation": "findAll(). class Tasks extends BaseController\n{\n    public function index()\n    {\n        $model = new TaskModel();\n        $data['tasks'] = $model->findAll();\n        return view('tasks/index', $data);\n    }\n}", "kind": "concept"}, {"id": "m2q53", "module": 2, "page": 27, "topic": "Queries & model configuration", "prompt": "Which method adds keyword matching?", "answer": "like()", "choices": ["like()", "findAll()", "find()", "first()"], "explanation": "like expresses pattern matching. Equality selects an exact value, while ordering and limiting change different query properties.", "kind": "concept"}, {"id": "m2q54", "module": 2, "page": 27, "topic": "Queries & model configuration", "prompt": "Which method limits the result count?", "answer": "limit()", "choices": ["limit()", "findAll()", "find()", "first()"], "explanation": "A limit restricts the maximum returned row count. It does not select a row by primary key or guarantee which rows appear without ordering.", "kind": "concept"}, {"id": "m2q55", "module": 2, "page": 27, "topic": "Queries & model configuration", "prompt": "Which method returns a count rather than fetched rows?", "answer": "countAllResults()", "choices": ["countAllResults()", "findAll()", "find()", "first()"], "explanation": "countAllResults(). // Return a number instead of the matching rows.\n$count = $model->where('status', 'pending')->countAllResults();", "kind": "concept"}, {"id": "m2q56-v2", "module": 2, "page": 25, "topic": "Filtering and sorting", "prompt": "The page needs pending tasks with the newest creation time first. Which chain expresses both requirements?", "answer": "where('status', 'pending')->orderBy('created_at', 'DESC')->findAll()", "choices": ["where('status', 'pending')->orderBy('created_at', 'DESC')->findAll()", "where('status', 'pending')->orderBy('created_at', 'ASC')->findAll()", "orderBy('status', 'DESC')->findAll()", "where('created_at', 'pending')->findAll()"], "explanation": "WHERE selects pending rows. ORDER BY created_at DESC orders those rows by decreasing creation time; sorting alone does not filter them.", "kind": "application"}, {"id": "m2q57", "module": 2, "page": 29, "topic": "Queries & model configuration", "prompt": "Which view-data key produces $tasks in the view?", "answer": "tasks", "choices": ["tasks", "task", "TaskModel", "items"], "explanation": "tasks. INSERT INTO tasks (title, status, created_at) VALUES\n('Buy groceries', 'pending', NOW()),\n('Submit report', 'pending', NOW()),\n('Fix login bug', 'done', NOW());", "kind": "concept"}, {"id": "m2q58-v2", "module": 2, "page": 27, "topic": "Query limits", "prompt": "A dashboard needs only five recent tasks. Which pair of query operations is relevant before retrieval?", "answer": "Order by creation time descending, then limit the result to five", "choices": ["Order by creation time descending, then limit the result to five", "Count the records, then render that number as five rows", "Sort titles ascending and ignore result size", "Change the primary key to 5"], "explanation": "Ordering defines which records come first; limiting restricts how many return. The number 5 is a limit here, not a selected primary key.", "kind": "application"}, {"id": "m2q59", "module": 2, "page": 32, "topic": "Queries & model configuration", "prompt": "Which route pattern captures a numeric task ID?", "answer": "/tasks/(:num)", "choices": ["/tasks/(:num)", "/tasks/(:segment) without a numeric restriction", "/tasks/(:alpha)", "/tasks?id=(:num) as a path capture"], "explanation": "The numeric placeholder captures digits in the path. The controller still needs to retrieve and check the selected task.", "kind": "concept"}, {"id": "m2q60", "module": 2, "page": 34, "topic": "Queries & model configuration", "prompt": "What must happen before reading fields from a possibly missing task?", "answer": "Check whether the result is null", "choices": ["Check whether the result is null", "Read the title first and check later", "Display the first task when the requested one is absent", "Assume the route's numeric shape guarantees a row"], "explanation": "Check whether the result is null. Schema columns, writable fields, and validation rules have different responsibilities. A model property does not create a database column.", "kind": "concept"}, {"id": "m3q1", "module": 3, "page": 7, "topic": "Routes", "prompt": "Which command lists registered CodeIgniter routes?", "answer": "php spark routes", "choices": ["php spark routes", "php spark serve", "php artisan route:list", "composer show"], "explanation": "php spark routes helps confirm that the GET and POST routes were registered.", "kind": "concept"}, {"id": "m3q2-v2", "module": 3, "page": 7, "topic": "Route diagnosis", "prompt": "The new-task form loads, but submitting it fails. Only GET /tasks/new exists. What is missing?", "answer": "A receiving POST route matching the form action", "choices": ["A receiving POST route matching the form action", "A second GET route to the same form", "A new primary-key column", "A session variable containing the HTML"], "explanation": "Displaying the form and receiving its submission are separate requests. The form's method and action must match a receiving route.", "kind": "application"}, {"id": "m3q3", "module": 3, "page": 8, "topic": "CSRF", "prompt": "Which CodeIgniter helper inserts the hidden CSRF token field?", "answer": "csrf_field()", "choices": ["csrf_field()", "csrf_token() by itself", "old()", "validation_show_error()"], "explanation": "csrf_field() adds a token field for CSRF protection when the corresponding protection is enabled.", "kind": "concept"}, {"id": "m3q4", "module": 3, "page": 10, "topic": "Validation", "prompt": "What does required|min_length[3]|max_length[150] require?", "answer": "A nonempty value between 3 and 150 characters", "choices": ["A nonempty value between 3 and 150 characters", "An optional value with at most 150 characters", "A value of exactly three characters", "A required value with no upper bound"], "explanation": "The rules require a value and set its minimum and maximum string lengths.", "kind": "concept"}, {"id": "m3q5", "module": 3, "page": 11, "topic": "Validation", "prompt": "Which CodeIgniter rule checks whether a task title is already in the table?", "answer": "is_unique[tasks.title]", "choices": ["is_unique[tasks.title]", "is_unique[tasks.id]", "max_length[150]", "required"], "explanation": "is_unique[tasks.title] checks uniqueness against the title column in tasks.", "kind": "concept"}, {"id": "m3q6", "module": 3, "page": 12, "topic": "Validation", "prompt": "What does redirect()->back()->withInput() preserve after failure?", "answer": "The submitted form input for redisplay", "choices": ["The submitted form input for redisplay", "The already saved database record only", "The browser's selected file bytes automatically", "A new task ID generated by the redirect"], "explanation": "withInput() makes previous input available when the form is shown again.", "kind": "concept"}, {"id": "m3q7", "module": 3, "page": 14, "topic": "Feedback", "prompt": "Which helper displays the validation error for the title field?", "answer": "validation_show_error('title')", "choices": ["validation_show_error('title')", "old('title')", "validation_errors() as a field-specific call", "csrf_field()"], "explanation": "validation_show_error() displays a field error; old() restores its previous value.", "kind": "concept"}, {"id": "m3q8", "module": 3, "page": 18, "topic": "CRUD", "prompt": "Which model method inserts a new task row?", "answer": "insert()", "choices": ["insert()", "update()", "delete()", "findAll()"], "explanation": "After validation, insert() writes a new row through the Model.", "kind": "concept"}, {"id": "m3q9", "module": 3, "page": 19, "topic": "CRUD", "prompt": "Which call changes one existing task by id?", "answer": "$model->update($id, $data)", "choices": ["$model->update($id, $data)", "$model->insert($data)", "$model->find($id)", "$model->update($data, $id)"], "explanation": "update() receives the target primary key and the fields to change.", "kind": "concept"}, {"id": "m3q10-v2", "module": 3, "page": 10, "topic": "Validation decisions", "prompt": "A title must contain 3–150 characters and cannot be empty. Which rule set states that requirement?", "answer": "required, min_length[3], max_length[150]", "choices": ["required, min_length[3], max_length[150]", "max_length[150] alone", "min_length[150]", "required and is_unique[tasks.id]"], "explanation": "required handles missing input; the length rules establish both bounds. A maximum alone does not establish the minimum or presence requirement.", "kind": "application"}, {"id": "m3q11", "module": 3, "page": 22, "topic": "Old input", "prompt": "What does old('title', $task['title']) prefer?", "answer": "Failed submitted input, then the saved title", "choices": ["Failed submitted input, then the saved title", "The saved title even when failed input exists", "The validation error message as the input value", "The primary key instead of either title"], "explanation": "The first argument names old input; the second provides the saved fallback.", "kind": "concept"}, {"id": "m3q12", "module": 3, "page": 25, "topic": "Uploads", "prompt": "Which form encoding is required to send file bytes?", "answer": "multipart/form-data", "choices": ["multipart/form-data", "application/x-www-form-urlencoded", "text/plain", "application/json without a multipart upload"], "explanation": "The file upload form must use enctype=\"multipart/form-data\".", "kind": "concept"}, {"id": "m3q13", "module": 3, "page": 26, "topic": "Uploads", "prompt": "Which CodeIgniter file rule checks that attachment was uploaded?", "answer": "uploaded[attachment]", "choices": ["uploaded[attachment]", "is_image[attachment]", "max_size[attachment,2048]", "mime_in[attachment,image/png]"], "explanation": "The module uses file-specific rules: uploaded, max_size, and mime_in.", "kind": "concept"}, {"id": "m3q14", "module": 3, "page": 27, "topic": "Uploads", "prompt": "Which method generates a safer server-side upload name?", "answer": "getRandomName()", "choices": ["getRandomName()", "getName()", "getClientName()", "getExtension()"], "explanation": "A generated name avoids relying on a user-supplied original filename.", "kind": "concept"}, {"id": "m3q15-v2", "module": 3, "page": 12, "topic": "Validation order", "prompt": "A controller inserts a task and only then checks whether its title is valid. What is the main failure?", "answer": "Invalid data can already be saved before rejection", "choices": ["Invalid data can already be saved before rejection", "The insert automatically becomes an update", "The route changes from POST to GET", "The browser loses its ability to show errors"], "explanation": "Validate before writing. Feedback after the insert cannot prevent invalid persistence that already occurred.", "kind": "application"}, {"id": "m3q16-v2", "module": 3, "page": 12, "topic": "Validation feedback", "prompt": "After a failed title check, the form becomes blank and shows no explanation. Which pair improves the correction workflow?", "answer": "Preserve old input and display field validation errors", "choices": ["Preserve old input and display field validation errors", "Insert the row anyway and show a success message", "Disable the required rule and reload", "Replace the form with the task list silently"], "explanation": "Old input preserves the submitted value; errors explain the required correction. Both support retrying without saving invalid data.", "kind": "application"}, {"id": "m3q17-v2", "module": 3, "page": 26, "topic": "File validation", "prompt": "A user renames a non-image file to image.png. Which approach best addresses the upload requirement?", "answer": "Apply the intended file type, MIME, and size checks on the server", "choices": ["Apply the intended file type, MIME, and size checks on the server", "Trust the visible extension alone", "Trust the input's accept attribute alone", "Store the original name and skip validation"], "explanation": "The browser and filename do not establish safe file content. Server-side file validation checks the intended upload constraints.", "kind": "application"}, {"id": "m3q18-v2", "module": 3, "page": 26, "topic": "Upload size", "prompt": "A rule uses max_size[attachment,2048]. Which interpretation is correct?", "answer": "The attachment limit is 2048 KB", "choices": ["The attachment limit is 2048 KB", "The attachment must be exactly 2048 bytes", "Only 2048 pixels are permitted in width", "Only 2048 uploads may exist in the table"], "explanation": "CodeIgniter's max_size file rule uses kilobytes. File size and image dimensions are separate constraints.", "kind": "application"}, {"id": "m3q19-v2", "module": 3, "page": 27, "topic": "Generated filenames", "prompt": "Two visitors upload different files both named photo.png. Which approach reduces filename collisions?", "answer": "Generate a server-side filename for each accepted upload", "choices": ["Generate a server-side filename for each accepted upload", "Always overwrite photo.png", "Use the visitor's title as the folder permissions", "Store both files at the same path and keep two rows"], "explanation": "A generated name separates stored files from repeated client names. It still requires validation and correct storage handling.", "kind": "application"}, {"id": "m3q20-v2", "module": 3, "page": 29, "topic": "File movement", "prompt": "The database stores a new attachment name, but moving the file failed. Why is the page's success message misleading?", "answer": "The saved reference points to a file that was not stored successfully", "choices": ["The saved reference points to a file that was not stored successfully", "The database automatically contains a copy of the bytes", "The file is guaranteed to appear after a redirect", "The browser can reconstruct the file from its name"], "explanation": "A database filename is only a reference. Check file movement and any processing before reporting a completed upload.", "kind": "application"}, {"id": "m3q21-v2", "module": 3, "page": 31, "topic": "Database references", "prompt": "An upload is stored in public/uploads under a generated name. What should the attachment column represent in this pattern?", "answer": "The generated filename used to rebuild its public URL", "choices": ["The generated filename used to rebuild its public URL", "The entire file contents automatically", "The visitor's local C: drive path", "The HTML img element"], "explanation": "The course pattern stores a filename, not a client path or HTML. The view combines it with the intended public upload location.", "kind": "application"}, {"id": "m3q22-v2", "module": 3, "page": 32, "topic": "Paths versus URLs", "prompt": "The file exists at a server filesystem path. What should the img src use?", "answer": "A public URL built for the stored attachment", "choices": ["A public URL built for the stored attachment", "The server's absolute filesystem path", "The table's primary-key setting", "The controller namespace"], "explanation": "The browser requests URLs, not private server filesystem paths. Build the public upload URL and escape it for the HTML attribute context.", "kind": "application"}, {"id": "m3q23-v2", "module": 3, "page": 30, "topic": "Image preparation", "prompt": "A layout requires square thumbnails with a consistent crop. Which operation is more appropriate than merely saving the filename?", "answer": "Apply the intended image fit or crop operation after validating the image", "choices": ["Apply the intended image fit or crop operation after validating the image", "Change the task ID to the desired image width", "Store the file again without processing", "Rename a PDF with a .jpg extension"], "explanation": "A stored name does not change dimensions. Image processing produces the required geometry and must succeed before reporting that preparation as complete.", "kind": "application"}, {"id": "m3q24-v2", "module": 3, "page": 18, "topic": "Server-controlled fields", "prompt": "New tasks must start pending even if a client submits status=done. Where should that initial value be enforced?", "answer": "In the server's intended insert data after validation", "choices": ["In the server's intended insert data after validation", "Only in a hidden input", "Only in the button's label", "Only in the browser's required attribute"], "explanation": "Clients can alter request fields. The server defines fields such as the initial status when the application controls them.", "kind": "application"}, {"id": "m3q25-v2", "module": 3, "page": 19, "topic": "Missing targets", "prompt": "An update receives a nonexistent task ID. What should happen before writing?", "answer": "Detect the missing task and return an appropriate failure response", "choices": ["Detect the missing task and return an appropriate failure response", "Silently edit the first available task", "Create a replacement task without asking", "Skip the ID and update every row"], "explanation": "The requested identity matters. Check the target before changing data; substituting or broadening the update performs a different operation.", "kind": "application"}, {"id": "m3q26-v2", "module": 3, "page": 29, "topic": "Upload directories", "prompt": "The upload handler targets a directory that does not exist. Which check belongs before claiming success?", "answer": "Create or verify the intended directory and its usable write permissions", "choices": ["Create or verify the intended directory and its usable write permissions", "Add another title validation error", "Rename the GET route", "Set the database status to done first"], "explanation": "A correct filename and database field do not create a usable destination. The handler must handle directory and file-operation failures.", "kind": "application"}, {"id": "m3q27-v2", "module": 3, "page": 18, "topic": "Redirect after writing", "prompt": "After a successful insert, the controller redirects to the list. What is the purpose of this separation?", "answer": "The next GET displays the result without repeating the original POST on an ordinary refresh", "choices": ["The next GET displays the result without repeating the original POST on an ordinary refresh", "The redirect validates the data retroactively", "The redirect creates the inserted primary key", "The browser skips the controller entirely"], "explanation": "The write occurs in the POST handler. The redirect starts a separate display request; it is not the write or validation step.", "kind": "application"}, {"id": "m3q28-v2", "module": 3, "page": 26, "topic": "Independent upload checks", "prompt": "An image passes MIME validation but exceeds the file-size rule. What should the handler do?", "answer": "Reject it because all required validation rules must pass", "choices": ["Reject it because all required validation rules must pass", "Accept it because MIME validation overrides size", "Save it first and validate size next request", "Convert its filename to lowercase and accept it"], "explanation": "Different rules test different conditions. Passing one check does not cancel a failing required check.", "kind": "application"}, {"id": "m3q29-v2", "module": 3, "page": 7, "topic": "Checking route registrations", "prompt": "An upload form posts to /tasks/8/upload, but its handler never runs. Which evidence is most useful first?", "answer": "The registered route list and the form's actual method/action", "choices": ["The registered route list and the form's actual method/action", "The browser's preferred color theme", "The seed task titles", "The password-hash algorithm"], "explanation": "Compare the request with the route table before debugging file processing. The handler cannot process a request that never reaches it.", "kind": "application"}, {"id": "m3q30", "module": 3, "page": 11, "topic": "Forms, validation & files", "prompt": "What does is_unique[tasks.title] check?", "answer": "Uniqueness in the named table column", "choices": ["Uniqueness in the named table column", "Only whether the field is nonempty", "Only the maximum number of characters", "Whether the table's primary key is numeric"], "explanation": "The rule checks existing values in the specified table column. Updating an existing row requires accounting for that same row.", "kind": "concept"}, {"id": "m3q31", "module": 3, "page": 12, "topic": "Forms, validation & files", "prompt": "What does the validation failure branch return?", "answer": "A redirect back with input", "choices": ["A redirect back with input", "A success redirect after inserting the invalid row", "The saved task without returning the form", "A normal list page that discards all input and errors"], "explanation": "A redirect back with input. Validate before saving, then return useful errors and old input on failure. A stored invalid row is not repaired by a later error message.", "kind": "concept"}, {"id": "m3q32", "module": 3, "page": 13, "topic": "Forms, validation & files", "prompt": "Which identifiers must agree for a field error to appear correctly?", "answer": "The form name and validation/error field name", "choices": ["The form name and validation/error field name", "The database password and input label", "The view filename and task title text", "The route's HTTP method and CSS class"], "explanation": "The error lookup addresses the validated field key. A different input name or error key refers to a different field.", "kind": "concept"}, {"id": "m3q33", "module": 3, "page": 14, "topic": "Forms, validation & files", "prompt": "Which helper displays a CI field validation error?", "answer": "validation_show_error()", "choices": ["validation_show_error()", "old()", "csrf_field()", "site_url()"], "explanation": "validation_show_error(). Validate before saving, then return useful errors and old input on failure. A stored invalid row is not repaired by a later error message.", "kind": "concept"}, {"id": "m3q34", "module": 3, "page": 14, "topic": "Forms, validation & files", "prompt": "What does old('title') recover after a failed form submission?", "answer": "The previous submitted title", "choices": ["The previous submitted title", "The database default regardless of submitted input", "The first task's title", "The field's validation rule definition"], "explanation": "Old input supplies the failed submission for correction. It does not replace the actual saved record or perform validation.", "kind": "concept"}, {"id": "m3q35", "module": 3, "page": 17, "topic": "Forms, validation & files", "prompt": "Which CRUD operation changes an existing row?", "answer": "Update", "choices": ["Update", "Create", "Read", "Delete"], "explanation": "Update. CRUD means Create, Read, Update, and Delete. CodeIgniter’s task controller handles requests and calls TaskModel for the table operation. Do not put repeated SQL in a view.", "kind": "concept"}, {"id": "m3q36", "module": 3, "page": 17, "topic": "Forms, validation & files", "prompt": "Which CRUD operation retrieves records?", "answer": "Read", "choices": ["Read", "Create", "Update", "Delete"], "explanation": "Read. action is the destination URL. method determines the request method. name=\"title\" determines the submitted key, so the controller, validation rule, and error lookup must use title too. site_url() builds an application URL instead of assuming a fixed folder location. The controller reads the value through $this->request->getPost('title') rather than relying directly on $_POST.", "kind": "concept"}, {"id": "m3q37-v2", "module": 3, "page": 22, "topic": "Old input precedence", "prompt": "An edit form has a saved title. A failed submission contains a different title. What should old('title', $task['title']) display?", "answer": "The failed submitted value when old input exists", "choices": ["The failed submitted value when old input exists", "The database title in every case", "The primary key as the title", "The validation rule string"], "explanation": "The saved title is the fallback. Old input takes precedence so the user can correct the value that just failed.", "kind": "application"}, {"id": "m3q38-v2", "module": 3, "page": 11, "topic": "Unique updates", "prompt": "A task title must be unique. An edit keeps its current title but fails a create-style uniqueness rule. What needs adjustment?", "answer": "Exclude the current record when checking uniqueness for the update", "choices": ["Exclude the current record when checking uniqueness for the update", "Remove all title validation permanently", "Generate a new primary key for every edit", "Treat every existing title as an uploaded filename"], "explanation": "The existing row already contains that title. An update uniqueness check must distinguish that row from conflicting different records.", "kind": "application"}, {"id": "m3q39", "module": 3, "page": 19, "topic": "Forms, validation & files", "prompt": "Which model call changes one selected row?", "answer": "update($id, $data)", "choices": ["update($id, $data)", "insert($data)", "find($id)", "delete($id)"], "explanation": "update targets an existing record by its identifier. insert creates a new row, and retrieval operations do not change it.", "kind": "concept"}, {"id": "m3q40", "module": 3, "page": 20, "topic": "Forms, validation & files", "prompt": "Why is a normal Delete link the wrong submission mechanism?", "answer": "It makes a GET request for destructive work", "choices": ["It makes a GET request for destructive work", "GET automatically creates a CSRF token", "The link validates ownership before dispatch", "A link's label determines its HTTP method"], "explanation": "A plain link normally issues GET. Use the intended protected write request and checked target for destructive work.", "kind": "concept"}, {"id": "m3q41", "module": 3, "page": 21, "topic": "Forms, validation & files", "prompt": "What must the edit action load before rendering the form?", "answer": "The existing selected record", "choices": ["The existing selected record", "A new empty model in every case", "Every task before choosing one in the template", "The database schema instead of the selected row"], "explanation": "The edit view needs the selected saved values. Check the missing-record path before reading fields or rendering the form.", "kind": "concept"}, {"id": "m3q42", "module": 3, "page": 22, "topic": "Forms, validation & files", "prompt": "Which value has priority in old('title', $task['title'])?", "answer": "Old submitted input when available", "choices": ["Old submitted input when available", "The saved database title in every case", "The route ID as the title", "The field's validation error as the title"], "explanation": "Old input takes precedence so the user can correct the failed submission. The saved title is the initial-display fallback.", "kind": "concept"}, {"id": "m3q43-v2", "module": 3, "page": 23, "topic": "Forms, validation & files", "prompt": "Which variable identifies the target row in update($id,...)?", "answer": "$id", "choices": ["$id", "$data as an entire result collection", "The view's heading text", "The table's current row position"], "explanation": "$id. After validation, the update fragment is $model->update($id, ['title' => $this->request->getPost('title')]);. Delete uses $model->delete($id). The route supplies the ID; it should not accidentally update every task or a hard-coded unrelated record.", "kind": "concept"}, {"id": "m3q44", "module": 3, "page": 25, "topic": "Forms, validation & files", "prompt": "Which encoding sends file bytes in the form?", "answer": "multipart/form-data", "choices": ["multipart/form-data", "application/x-www-form-urlencoded", "text/plain", "application/json by itself"], "explanation": "multipart/form-data. Match the upload field name, validate on the server, check storage success, then persist the intended reference.", "kind": "concept"}, {"id": "m3q45-v2", "module": 3, "page": 19, "topic": "Update versus insert", "prompt": "An edit action creates another row instead of changing the selected task. Which model operation should you inspect?", "answer": "The action should update the selected ID with the validated data", "choices": ["The action should update the selected ID with the validated data", "The action should insert again with no ID", "The action should call findAll() instead of writing", "The view should rename the Submit button"], "explanation": "An insert adds a row. Updating an existing row requires identifying that row and applying the intended fields.", "kind": "application"}, {"id": "m3q46", "module": 3, "page": 26, "topic": "Forms, validation & files", "prompt": "Which file rule requires an uploaded file?", "answer": "uploaded[attachment]", "choices": ["uploaded[attachment]", "is_image[attachment]", "max_size[attachment,2048]", "mime_in[attachment,image/jpeg,image/png]"], "explanation": "uploaded[attachment]. Match the upload field name, validate on the server, check storage success, then persist the intended reference.", "kind": "concept"}, {"id": "m3q47", "module": 3, "page": 26, "topic": "Forms, validation & files", "prompt": "Which rule limits this CI file to 2048 KB?", "answer": "max_size[attachment,2048]", "choices": ["max_size[attachment,2048]", "max_size[attachment,2]", "max_length[2048]", "is_image[attachment]"], "explanation": "max_size[attachment,2048]. Match the upload field name, validate on the server, check storage success, then persist the intended reference.", "kind": "concept"}, {"id": "m3q48-v2", "module": 3, "page": 20, "topic": "Deletion requests", "prompt": "A task disappears when a visitor follows a plain link. Which workflow better fits a deliberate state-changing delete?", "answer": "A protected POST form with CSRF protection and a checked target record", "choices": ["A protected POST form with CSRF protection and a checked target record", "A GET link that deletes immediately", "A view that runs delete() while rendering", "A CSS rule that hides the row"], "explanation": "The taught delete workflow uses a write request. Check protection and the target before deleting, then redirect after success.", "kind": "application"}, {"id": "m3q49", "module": 3, "page": 27, "topic": "Forms, validation & files", "prompt": "Which method retrieves the uploaded file object?", "answer": "getFile('attachment')", "choices": ["getFile('attachment')", "getPost('attachment')", "getGet('attachment')", "getVar('attachment')"], "explanation": "getFile('attachment'). Match the upload field name, validate on the server, check storage success, then persist the intended reference.", "kind": "concept"}, {"id": "m3q50", "module": 3, "page": 27, "topic": "Forms, validation & files", "prompt": "Which method generates the stored upload name?", "answer": "getRandomName()", "choices": ["getRandomName()", "getName()", "getClientName()", "getExtension()"], "explanation": "getRandomName(). if (! $this->validateData([], $rules)) {\n    return redirect()->back()->withInput();\n}\n$file = $this->request->getFile('attachment');\n$newName = $file->getRandomName();", "kind": "concept"}, {"id": "m3q51", "module": 3, "page": 29, "topic": "Forms, validation & files", "prompt": "What does the third true argument in mkdir(..., 0775, true) request?", "answer": "Recursive directory creation", "choices": ["Recursive directory creation", "Automatically making every created file public", "Automatically validating the upload MIME type", "Automatically saving the filename to the database"], "explanation": "Recursive creation permits missing parent directories to be created. Effective write permissions still depend on the operating system and configuration.", "kind": "concept"}, {"id": "m3q52-v2", "module": 3, "page": 8, "topic": "CSRF versus validation", "prompt": "A form includes csrf_field(). Why must the title still be validated?", "answer": "CSRF protection does not check title presence or length", "choices": ["CSRF protection does not check title presence or length", "A CSRF token makes every request field trustworthy", "CSRF protection creates missing database columns", "The token automatically applies all model rules"], "explanation": "CSRF protection and input validation solve different problems. A valid token does not make a blank or overlong title acceptable.", "kind": "application"}, {"id": "m3q53", "module": 3, "page": 31, "topic": "Forms, validation & files", "prompt": "What must the model allow before writing attachment?", "answer": "The attachment field", "choices": ["The attachment field", "Only a matching label in the HTML", "Only a route named attachment", "Only an uploaded file with an original name"], "explanation": "The intended attachment field must be permitted for the model write. It must also exist in the schema; these are separate requirements.", "kind": "concept"}, {"id": "m3q54-v2", "module": 3, "page": 25, "topic": "Upload transport", "prompt": "A file input exists, but the request does not contain the uploaded file bytes. What form setting should you check?", "answer": "enctype=\"multipart/form-data\"", "choices": ["enctype=\"multipart/form-data\"", "method=\"GET\" as the upload method", "The table's sort order", "The label's CSS class"], "explanation": "File transfer requires multipart form encoding. A file input alone does not establish the required request encoding.", "kind": "application"}, {"id": "m3q55-v2", "module": 3, "page": 25, "topic": "Upload field names", "prompt": "The form sends a file named photo, but the controller calls getFile('attachment'). What is the direct correction?", "answer": "Match the input name and the getFile() key", "choices": ["Match the input name and the getFile() key", "Rename the database connection to photo", "Read the file with getPost('title')", "Change the upload folder to the input name"], "explanation": "Uploaded files are addressed by their form field name. A mismatch prevents the handler from reading the intended file object.", "kind": "application"}, {"id": "m3q56", "module": 3, "page": 32, "topic": "Forms, validation & files", "prompt": "What is the difference between a filesystem path and a URL?", "answer": "One identifies server storage; the other identifies a browser resource", "choices": ["One identifies server storage; the other identifies a browser resource", "Both always contain the same absolute string", "A URL directly names a private server file", "A filesystem path is always browser-accessible"], "explanation": "One identifies server storage; the other identifies a browser resource. Match the upload field name, validate on the server, check storage success, then persist the intended reference.", "kind": "concept"}, {"id": "m3q57", "module": 3, "page": 34, "topic": "Forms, validation & files", "prompt": "Which operation comes before moving an accepted upload?", "answer": "File validation", "choices": ["File validation", "Save the filename before any checks", "Show success and validate on the next GET", "Move the file first so its rules can be skipped"], "explanation": "Validation is the acceptance checkpoint before storing the upload. Moving first can persist a rejected file.", "kind": "concept"}, {"id": "m3q58", "module": 3, "page": 35, "topic": "Forms, validation & files", "prompt": "Which mismatch makes an uploaded-file reference unsuitable for browser display?", "answer": "Storing privately but building an unrelated public URL", "choices": ["Storing privately but building an unrelated public URL", "Using a random filename", "Checking the file size", "Saving only the filename"], "explanation": "The stored location and public URL must describe the same intended file. A private filesystem path is not itself a working browser URL.", "kind": "concept"}, {"id": "m3q59", "module": 3, "page": 35, "topic": "Forms, validation & files", "prompt": "Does restoring old text input restore a browser's chosen file?", "answer": "No; the user generally selects the file again", "choices": ["No; the user generally selects the file again", "Yes; old() restores the selected bytes", "Yes; redirect()->back() uploads it again automatically", "Only when the saved task already has an image"], "explanation": "No; the user generally selects the file again. Match the upload field name, validate on the server, check storage success, then persist the intended reference.", "kind": "concept"}, {"id": "m3q60", "module": 3, "page": 35, "topic": "Forms, validation & files", "prompt": "Does a writable-field list replace input validation?", "answer": "No; they have different responsibilities", "choices": ["No; they have different responsibilities", "Yes; permitted field names guarantee valid values", "Yes; it checks every file's MIME type", "Yes; it guarantees the selected row belongs to the visitor"], "explanation": "No; they have different responsibilities. Validate before saving, then return useful errors and old input on failure. A stored invalid row is not repaired by a later error message.", "kind": "concept"}, {"id": "m4q1", "module": 4, "page": 6, "topic": "Sessions", "prompt": "What problem do sessions solve for HTTP applications?", "answer": "Remembering small visitor values across separate requests", "choices": ["Remembering small visitor values across separate requests", "Making all HTTP requests share one local PHP variable", "Storing the user's password in every URL", "Authorizing every record after one login"], "explanation": "HTTP requests are separate; sessions connect small pieces of state to a visitor.", "kind": "concept"}, {"id": "m4q2", "module": 4, "page": 8, "topic": "Sessions", "prompt": "Which call stores a CodeIgniter session value?", "answer": "session()->set('username', 'admin')", "choices": ["session()->set('username', 'admin')", "session()->get('username')", "session()->remove('username')", "session()->getFlashdata('username')"], "explanation": "set() stores a value; get() or session('username') retrieves it.", "kind": "concept"}, {"id": "m4q3", "module": 4, "page": 9, "topic": "Sessions", "prompt": "Which method removes just one session value?", "answer": "remove()", "choices": ["remove()", "destroy()", "get()", "set()"], "explanation": "remove() targets a key, whereas destroy() clears the session.", "kind": "concept"}, {"id": "m4q4-v2", "module": 4, "page": 25, "topic": "Login sequence", "prompt": "A correct password redirects to /tasks, but the protected request treats the visitor as a guest. What should you inspect?", "answer": "Whether the success branch saves the exact session state that the filter checks", "choices": ["Whether the success branch saves the exact session state that the filter checks", "Whether the tasks view is stored under public/", "Whether the password is printed in the URL", "Whether the task table uses descending order"], "explanation": "The redirect starts a new request. The login action and filter must agree on the saved session keys and values.", "kind": "application"}, {"id": "m4q5", "module": 4, "page": 10, "topic": "Flash data", "prompt": "What is flash data intended for?", "answer": "A message available on the next request after a redirect", "choices": ["A message available on the next request after a redirect", "Permanent storage for the complete user record", "A message removed immediately on its first read", "A replacement for password verification"], "explanation": "Flash data lasts one subsequent request by default, making it suitable for redirect feedback.", "kind": "concept"}, {"id": "m4q6", "module": 4, "page": 11, "topic": "Flash data", "prompt": "Which method reads a next-request flash message?", "answer": "getFlashdata()", "choices": ["getFlashdata()", "get()", "setFlashdata()", "remove()"], "explanation": "getFlashdata('message') retrieves the message set before the redirect.", "kind": "concept"}, {"id": "m4q7", "module": 4, "page": 13, "topic": "Session safety", "prompt": "Which value is appropriate to store in the login session?", "answer": "user_id", "choices": ["user_id", "The typed password", "The stored password hash as the login credential", "The complete users table"], "explanation": "The module recommends small identifiers and login state, never passwords or large records.", "kind": "concept"}, {"id": "m4q8", "module": 4, "page": 19, "topic": "Passwords", "prompt": "Which function creates a password hash?", "answer": "password_hash()", "choices": ["password_hash()", "password_verify()", "hash()", "password_needs_rehash()"], "explanation": "password_hash($plainPassword, PASSWORD_DEFAULT) produces the hash stored in the database.", "kind": "concept"}, {"id": "m4q9", "module": 4, "page": 24, "topic": "Passwords", "prompt": "Which function checks a typed password against the stored hash?", "answer": "password_verify()", "choices": ["password_verify()", "password_hash()", "hash()", "password_needs_rehash()"], "explanation": "password_verify($password, $storedHash) checks the password; a direct equality comparison is unsuitable.", "kind": "concept"}, {"id": "m4q10", "module": 4, "page": 23, "topic": "Login", "prompt": "Why use $model->where('username', $username)->first()?", "answer": "To retrieve the user matching the submitted username", "choices": ["To retrieve the user matching the submitted username", "To return all users regardless of the submitted name", "To authenticate solely because the username exists", "To insert an account if none exists"], "explanation": "The login controller first looks up the user, then verifies the password hash.", "kind": "concept"}, {"id": "m4q11-v2", "module": 4, "page": 9, "topic": "Logout state", "prompt": "Logout removes username but leaves isLoggedIn=true. Why can the filter still admit the visitor?", "answer": "The filter still sees the remaining login-state flag", "choices": ["The filter still sees the remaining login-state flag", "Removing a username automatically destroys every session", "The browser's Back button creates a new authenticated account", "A GET route never reads session data"], "explanation": "Removing one key does not end the whole session. Destroy the login session or remove all relevant authentication state deliberately.", "kind": "application"}, {"id": "m4q12", "module": 4, "page": 27, "topic": "Filters", "prompt": "When does an authentication filter’s before() check run?", "answer": "Before the controller action", "choices": ["Before the controller action", "After the controller changes data", "Only after the view is printed", "Only during the first login request"], "explanation": "The before() method can redirect a guest before protected controller logic runs.", "kind": "concept"}, {"id": "m4q13", "module": 4, "page": 29, "topic": "Filters", "prompt": "Which interface does AuthFilter implement?", "answer": "FilterInterface", "choices": ["FilterInterface", "RequestInterface", "ResponseInterface", "SessionInterface"], "explanation": "The filter implements CodeIgniter\\Filters\\FilterInterface and defines before() and after().", "kind": "concept"}, {"id": "m4q14", "module": 4, "page": 30, "topic": "Filters", "prompt": "Where is the auth filter alias registered?", "answer": "app/Config/Filters.php", "choices": ["app/Config/Filters.php", "app/Filters/AuthFilter.php as the alias registry", "app/Config/Routes.php as the class definition", "app/Models/UserModel.php as the alias registry"], "explanation": "Filters.php maps the short auth alias to the AuthFilter class.", "kind": "concept"}, {"id": "m4q15", "module": 4, "page": 31, "topic": "Access control", "prompt": "What does ['filter' => 'auth'] on a CodeIgniter route do?", "answer": "Applies the registered authentication filter", "choices": ["Applies the registered authentication filter", "Stores the user in the session automatically", "Validates every form field automatically", "Checks ownership of every requested record automatically"], "explanation": "The alias attaches the filter to the route so login state can be checked.", "kind": "concept"}, {"id": "m4q16", "module": 4, "page": 31, "topic": "Access control", "prompt": "Does a basic login filter also establish role-based permissions?", "answer": "No; role checks are additional", "choices": ["No; role checks are additional", "Yes; a true login flag proves every role", "Yes; the username grants all permissions", "Only hiding a role's controls is necessary"], "explanation": "The module distinguishes authentication-based access from additional role-based permissions.", "kind": "concept"}, {"id": "m4q17-v2", "module": 4, "page": 10, "topic": "Flash lifecycle", "prompt": "A save message should appear after one redirect, then disappear on later ordinary requests. Which storage fits?", "answer": "Flash data", "choices": ["Flash data", "A permanent session value with no removal", "The user's password field", "The base URL setting"], "explanation": "Flash data is designed for the next-request feedback cycle. A normal session value persists until removal or expiration.", "kind": "application"}, {"id": "m4q18-v2", "module": 4, "page": 27, "topic": "Filter placement", "prompt": "The list page requires login, but an unprotected update route accepts guest requests. What fixes the access gap?", "answer": "Apply the authentication check to the protected write route too", "choices": ["Apply the authentication check to the protected write route too", "Hide the Update link in the list view", "Require a longer task title", "Sort private records by user ID"], "explanation": "Each protected endpoint needs its own effective gate. Protecting one list page does not automatically protect related write URLs.", "kind": "application"}, {"id": "m4q19-v2", "module": 4, "page": 31, "topic": "Direct requests", "prompt": "A guest cannot see the Delete button but can submit its URL manually. Which principle explains the failure?", "answer": "Hidden controls do not replace server-side access checks", "choices": ["Hidden controls do not replace server-side access checks", "HTML automatically authorizes visible buttons only", "CSRF protection automatically logs in guests", "The model knows which buttons were displayed"], "explanation": "The server must check access on the actual request. A client can send a request without using the rendered interface.", "kind": "application"}, {"id": "m4q20-v2", "module": 4, "page": 30, "topic": "Filter registration", "prompt": "AuthFilter.php exists, but a route's auth alias is not registered. Which missing connection should be inspected?", "answer": "The alias mapping in app/Config/Filters.php", "choices": ["The alias mapping in app/Config/Filters.php", "The task title's unique constraint", "The upload input's encoding", "The database sorting direction"], "explanation": "A class, alias registration, and route attachment are separate connections. Creating the class does not register its alias automatically.", "kind": "application"}, {"id": "m4q21-v2", "module": 4, "page": 29, "topic": "Before versus after", "prompt": "A guest must be redirected before a task controller changes data. Which hook fits?", "answer": "The filter's before() hook", "choices": ["The filter's before() hook", "The filter's after() hook as the first protection", "The task view's footer", "The flash-message display block"], "explanation": "The access decision must occur before the action. A check after the controller runs can be too late to prevent the write.", "kind": "application"}, {"id": "m4q22-v2", "module": 4, "page": 31, "topic": "Authentication limits", "prompt": "A logged-in user requests another user's task. What does a simple isLoggedIn filter establish?", "answer": "Identity state only; record permission still needs a separate check", "choices": ["Identity state only; record permission still needs a separate check", "Ownership of every task in the database", "Permission to bypass validation", "Permission to overwrite every upload"], "explanation": "Authentication and record authorization answer different questions. A login flag does not establish ownership of the selected record.", "kind": "application"}, {"id": "m4q23-v2", "module": 4, "page": 25, "topic": "Request continuity", "prompt": "Why must successful login save state before redirecting rather than keep only a local $user variable?", "answer": "The redirected request does not retain that action's local variables", "choices": ["The redirected request does not retain that action's local variables", "A local PHP variable is automatically a browser cookie", "A redirect sends the entire controller memory to the browser", "All model rows are shared across user sessions"], "explanation": "Local variables belong to the current request. A session carries the intended small identity values into later requests.", "kind": "application"}, {"id": "m4q24-v2", "module": 4, "page": 9, "topic": "One key versus whole session", "prompt": "A visitor removes a temporary preference while staying logged in. Which operation matches that narrow goal?", "answer": "Remove only the preference key", "choices": ["Remove only the preference key", "Destroy the entire session", "Delete the users table row", "Clear the stored password hash"], "explanation": "remove() targets a key. destroy() ends the whole session and is broader than removing a temporary preference.", "kind": "application"}, {"id": "m4q25-v2", "module": 4, "page": 18, "topic": "Unique identities", "prompt": "Why does a unique username constraint help a username-based login lookup?", "answer": "It prevents ambiguous duplicate usernames in stored records", "choices": ["It prevents ambiguous duplicate usernames in stored records", "It automatically verifies passwords", "It authorizes every record for that username", "It stores the login session automatically"], "explanation": "A unique username gives the lookup an unambiguous identity key. Password verification and session creation still happen separately.", "kind": "application"}, {"id": "m4q26-v2", "module": 4, "page": 20, "topic": "Account setup", "prompt": "The model class exists, but the users table has no rows. Why can no existing-account login succeed?", "answer": "The lookup has no stored user and hash to verify", "choices": ["The lookup has no stored user and hash to verify", "The browser needs a task attachment first", "The auth filter must invent the user", "The session automatically creates every submitted username"], "explanation": "A model definition does not insert accounts. Authentication needs an existing stored identity with a suitable password hash.", "kind": "application"}, {"id": "m4q27-v2", "module": 4, "page": 26, "topic": "Logout verification", "prompt": "Which check most directly tests whether logout closes protected access?", "answer": "Log out, then request the protected URL directly", "choices": ["Log out, then request the protected URL directly", "Check only that the Logout button disappears", "Refresh an unrelated public About page", "Count the user's stored task records"], "explanation": "A direct request exercises the server's access gate. Changes to visible controls do not prove protected access has ended.", "kind": "application"}, {"id": "m4q28-v2", "module": 4, "page": 21, "topic": "Credentials transport", "prompt": "A login form submits credentials in the query string. Which adjustment fits the taught form flow?", "answer": "Use the receiving POST action with the intended protected form setup", "choices": ["Use the receiving POST action with the intended protected form setup", "Rename password to title and keep GET", "Put the password into the route's path", "Store the plaintext password in flash data"], "explanation": "The login workflow separates a GET display action from a POST submission action. Do not place credentials in the URL.", "kind": "application"}, {"id": "m4q29-v2", "module": 4, "page": 24, "topic": "Failed authentication", "prompt": "A password check fails. Which outcome matches the taught control flow?", "answer": "Return failure feedback without establishing logged-in session state", "choices": ["Return failure feedback without establishing logged-in session state", "Set isLoggedIn and show an error afterward", "Redirect to protected tasks as a successful login", "Replace the stored hash with the failed password"], "explanation": "The failure branch must stop the success path. An error message does not undo login state that was already established.", "kind": "application"}, {"id": "m4q30-v2", "module": 4, "page": 6, "topic": "HTTP and sessions", "prompt": "The server returns a login success page but saves no state. Why does the next request need authentication again?", "answer": "HTTP requests do not inherit login state without an appropriate continuity mechanism", "choices": ["HTTP requests do not inherit login state without an appropriate continuity mechanism", "Every PHP view resets the database", "The task model destroys all cookies", "A redirect always deletes accounts"], "explanation": "HTTP requests are separate exchanges. The application needs a correctly functioning session mechanism to associate the next request with the authenticated visitor.", "kind": "application"}, {"id": "m4q31-v2", "module": 4, "page": 25, "topic": "Minimal identity", "prompt": "The task page needs the current user's identifier. Which stored value best supports that need?", "answer": "The authenticated user's ID", "choices": ["The authenticated user's ID", "The user's plaintext password", "The complete users collection", "The SMTP password"], "explanation": "A small identity value supports later lookups. The task page does not need the user's password or unrelated service credentials.", "kind": "application"}, {"id": "m4q32-v2", "module": 4, "page": 31, "topic": "Testing both outcomes", "prompt": "An auth filter works for guests. Which additional check verifies its success path?", "answer": "Log in and make the same protected request", "choices": ["Log in and make the same protected request", "Delete the users table and retry", "Remove the filter from every route", "Send an invalid image upload only"], "explanation": "Test both branches: guests should be redirected, and a valid authenticated session should reach the intended protected action.", "kind": "application"}, {"id": "m4q33", "module": 4, "page": 18, "topic": "Sessions & access checks", "prompt": "Which user column must contain a hash?", "answer": "password", "choices": ["password", "username", "user_id", "created_at"], "explanation": "password. HTTP requests are separate exchanges. A session lets the server associate small pieces of state with the same visitor across requests. The browser commonly sends a session cookie identifying the relevant server-side session data. The cookie is not a reason to store the user’s password in session data.", "kind": "concept"}, {"id": "m4q34-v2", "module": 4, "page": 11, "topic": "Flash ordering", "prompt": "A controller returns a redirect before calling setFlashdata(). Why is the message absent?", "answer": "The code after return does not execute", "choices": ["The code after return does not execute", "Redirects cannot work with sessions", "Flash data must be stored in the task table", "The browser deletes all session data on every GET"], "explanation": "Set the message before returning. A return exits that action, so the later setter never runs.", "kind": "application"}, {"id": "m4q35", "module": 4, "page": 19, "topic": "Sessions & access checks", "prompt": "What does password_hash() produce?", "answer": "A stored password hash", "choices": ["A stored password hash", "A reversibly encrypted password", "The original password with HTML escaping", "A verified login session automatically"], "explanation": "A stored password hash. Store a password hash and verify the candidate against it. A password input and a login session do not replace hashing.", "kind": "concept"}, {"id": "m4q36", "module": 4, "page": 19, "topic": "Sessions & access checks", "prompt": "What does PASSWORD_DEFAULT select?", "answer": "PHP's default password-hashing algorithm", "choices": ["PHP's default password-hashing algorithm", "The database's encryption key", "A fixed password shared by every user", "The current session identifier"], "explanation": "PHP's default password-hashing algorithm. Store a password hash and verify the candidate against it. A password input and a login session do not replace hashing.", "kind": "concept"}, {"id": "m4q37", "module": 4, "page": 19, "topic": "Sessions & access checks", "prompt": "Is password hashing the same as reversible password encryption?", "answer": "No", "choices": ["No", "Yes; the application decrypts the hash during login", "Yes; password_verify decrypts and returns plaintext", "Only when the hash column uses VARCHAR"], "explanation": "No. Store a password hash and verify the candidate against it. A password input and a login session do not replace hashing.", "kind": "concept"}, {"id": "m4q38", "module": 4, "page": 20, "topic": "Sessions & access checks", "prompt": "Which model table does UserModel manage?", "answer": "users", "choices": ["users", "tasks", "attachments", "migrations"], "explanation": "users. Authentication checks who the visitor is. The course’s minimal login looks up a user by username and verifies the typed password against a stored password hash. A users table therefore needs an ID, a unique username, and a password-hash column, illustrated as VARCHAR(255).", "kind": "concept"}, {"id": "m4q39-v2", "module": 4, "page": 12, "topic": "Flash keys", "prompt": "The controller sets flash key notice, but the view reads message. What should be corrected?", "answer": "Use the same key on both sides", "choices": ["Use the same key on both sides", "Hash the notice before setting it", "Change the route to DELETE", "Add notice to the model's primary key"], "explanation": "Session keys are exact names. Reading a different key does not retrieve the value that the controller set.", "kind": "application"}, {"id": "m4q40-v2", "module": 4, "page": 20, "topic": "Sessions & access checks", "prompt": "Why should a login action avoid inserting a test account on every attempt?", "answer": "Account setup is separate from checking an existing identity", "choices": ["Account setup is separate from checking an existing identity", "Every failed login should create a new account", "A username lookup must insert before it can select", "Creating an account automatically verifies the typed password"], "explanation": "Set up a test identity deliberately. A login request looks up an existing account and verifies its stored password hash.", "kind": "concept"}, {"id": "m4q41", "module": 4, "page": 21, "topic": "Sessions & access checks", "prompt": "What advantage does a filter provide over repeated manual checks?", "answer": "A centralized reusable route gate", "choices": ["A centralized reusable route gate", "It makes every protected action public", "It replaces the password verification step", "It authorizes all records for each signed-in user"], "explanation": "A centralized reusable route gate. The filter class, registered alias, and route attachment must agree. The before hook can stop the action before its data changes occur.", "kind": "concept"}, {"id": "m4q42", "module": 4, "page": 22, "topic": "Sessions & access checks", "prompt": "What field type obscures typed password characters on screen?", "answer": "password", "choices": ["password", "text", "hidden", "email"], "explanation": "password. Store a password hash and verify the candidate against it. A password input and a login session do not replace hashing.", "kind": "concept"}, {"id": "m4q43", "module": 4, "page": 22, "topic": "Sessions & access checks", "prompt": "Does a password input hash the password for storage?", "answer": "No", "choices": ["No", "Yes; the browser stores a server-ready password hash", "Yes; obscuring characters encrypts the database value", "Only when the form also includes csrf_field()"], "explanation": "No. Store a password hash and verify the candidate against it. A password input and a login session do not replace hashing.", "kind": "concept"}, {"id": "m4q44", "module": 4, "page": 23, "topic": "Sessions & access checks", "prompt": "Which query retrieves the matched username row?", "answer": "where('username', $username)->first()", "choices": ["where('username', $username)->first()", "find($username) using the numeric primary key", "where('password', $username)->first()", "findAll() without a username condition"], "explanation": "where('username', $username)->first(). // Validate required field types/presence before this lookup.\n$model = new UserModel();\n$user = $model->where('username', $username)->first();", "kind": "concept"}, {"id": "m4q45", "module": 4, "page": 24, "topic": "Sessions & access checks", "prompt": "Which condition must be rejected before reading a missing user's password field?", "answer": "No matching user record", "choices": ["No matching user record", "The username having a unique constraint", "The action receiving a POST request", "The stored password being hashed"], "explanation": "No matching user record. Store a password hash and verify the candidate against it. A password input and a login session do not replace hashing.", "kind": "concept"}, {"id": "m4q46", "module": 4, "page": 24, "topic": "Sessions & access checks", "prompt": "Which function checks the typed password against the hash?", "answer": "password_verify()", "choices": ["password_verify()", "password_hash()", "hash()", "password_needs_rehash()"], "explanation": "password_verify(). Store a password hash and verify the candidate against it. A password input and a login session do not replace hashing.", "kind": "concept"}, {"id": "m4q47", "module": 4, "page": 24, "topic": "Sessions & access checks", "prompt": "Why not compare the typed password directly with the stored hash?", "answer": "They are different representations", "choices": ["They are different representations", "The hash is the session identifier", "The browser password field always returns an empty value", "The route automatically rehashes the username"], "explanation": "They are different representations. Store a password hash and verify the candidate against it. A password input and a login session do not replace hashing.", "kind": "concept"}, {"id": "m4q48-v2", "module": 4, "page": 19, "topic": "Password verification", "prompt": "A developer hashes the submitted password again and compares hash strings. Correct logins fail. Which function should check the stored hash?", "answer": "password_verify($submitted, $storedHash)", "choices": ["password_verify($submitted, $storedHash)", "password_hash($storedHash, PASSWORD_DEFAULT)", "strcmp($submitted, $storedHash)", "htmlspecialchars($storedHash)"], "explanation": "Password hashing can produce different hashes for the same password. Verification uses the candidate and stored hash with its algorithm information.", "kind": "application"}, {"id": "m4q49", "module": 4, "page": 25, "topic": "Sessions & access checks", "prompt": "Which session value identifies the authenticated row?", "answer": "user_id", "choices": ["user_id", "username as proof of a unique numeric row", "isLoggedIn as the row's primary key", "The submitted password"], "explanation": "user_id. A session carries small values across requests. Setting, reading, removing one key, and destroying the whole session are different operations.", "kind": "concept"}, {"id": "m4q50", "module": 4, "page": 25, "topic": "Sessions & access checks", "prompt": "Should the success session include the typed password?", "answer": "No", "choices": ["No", "Yes; later pages need it to prove identity", "Yes; storing it avoids future hash checks", "Only when the password input masks the characters"], "explanation": "No. A session carries small values across requests. Setting, reading, removing one key, and destroying the whole session are different operations.", "kind": "concept"}, {"id": "m4q51", "module": 4, "page": 26, "topic": "Sessions & access checks", "prompt": "After logout, a guest needs the sign-in form. Which destination matches that purpose?", "answer": "/login", "choices": ["/login", "/tasks/create only", "/storage", "/database"], "explanation": "/login. A session carries small values across requests. Setting, reading, removing one key, and destroying the whole session are different operations.", "kind": "concept"}, {"id": "m4q52-v2", "module": 4, "page": 18, "topic": "Password storage", "prompt": "The password input hides its characters on screen. What additional server responsibility remains?", "answer": "Hash the password before persistent storage", "choices": ["Hash the password before persistent storage", "Store the typed value because the browser already hashes it", "Use the task title as the password salt", "Show the password in a success message"], "explanation": "A password input only obscures the display. It does not protect stored credentials or perform the server's password hashing.", "kind": "application"}, {"id": "m4q53", "module": 4, "page": 27, "topic": "Sessions & access checks", "prompt": "When does the authentication filter gate the protected controller?", "answer": "Before controller work", "choices": ["Before controller work", "After controller work", "After sending the completed response", "Only after rendering protected HTML"], "explanation": "Before controller work. The filter class, registered alias, and route attachment must agree. The before hook can stop the action before its data changes occur.", "kind": "concept"}, {"id": "m4q54", "module": 4, "page": 28, "topic": "Sessions & access checks", "prompt": "Which filter hook receives the controller's response afterward?", "answer": "after()", "choices": ["after()", "before()", "index()", "login()"], "explanation": "after(). The filter class, registered alias, and route attachment must agree. The before hook can stop the action before its data changes occur.", "kind": "concept"}, {"id": "m4q55", "module": 4, "page": 29, "topic": "Sessions & access checks", "prompt": "Which type represents the incoming request argument in AuthFilter::before()?", "answer": "RequestInterface", "choices": ["RequestInterface", "ResponseInterface", "FilterInterface", "UserModel"], "explanation": "RequestInterface. The filter class, registered alias, and route attachment must agree. The before hook can stop the action before its data changes occur.", "kind": "concept"}, {"id": "m4q56-v2", "module": 4, "page": 24, "topic": "Absent users", "prompt": "The login lookup returns null. Why must the controller check that before password verification?", "answer": "There is no user row from which to read a stored password hash", "choices": ["There is no user row from which to read a stored password hash", "The username automatically becomes the password", "An empty lookup always means the database is offline", "The controller must create an account for every missing name"], "explanation": "A missing user is a normal failed-login condition. Do not access fields on null or automatically turn a login attempt into registration.", "kind": "application"}, {"id": "m4q57-v2", "module": 4, "page": 13, "topic": "Session contents", "prompt": "A developer stores the complete users table in each login session. Which design better fits appropriate small-session storage?", "answer": "Store small identity values needed for subsequent requests", "choices": ["Store small identity values needed for subsequent requests", "Store plaintext passwords instead to save space", "Move the entire table into the session cookie", "Store all task files in the same session"], "explanation": "Sessions should hold small necessary values such as user ID and login state. Whole tables and credentials are unnecessary session contents.", "kind": "application"}, {"id": "m4q58", "module": 4, "page": 31, "topic": "Sessions & access checks", "prompt": "Does a login check establish record ownership automatically?", "answer": "No; ownership needs an additional check", "choices": ["No; ownership needs an additional check", "Yes; authenticated users own all records", "Yes; a private index grants access to every detail URL", "Only the view's hidden links determine ownership"], "explanation": "Authentication establishes identity. Permission for the selected record requires a separate access decision.", "kind": "concept"}, {"id": "m4q59", "module": 4, "page": 33, "topic": "Sessions & access checks", "prompt": "What should a guest encounter when directly requesting a protected task page?", "answer": "A redirect to login", "choices": ["A redirect to login", "The protected content with its navigation hidden", "An automatically created account", "A successful write followed by a login redirect"], "explanation": "The before filter redirects the guest before the protected controller action. A hidden navigation link is not the access check.", "kind": "concept"}, {"id": "m4q60", "module": 4, "page": 35, "topic": "Sessions & access checks", "prompt": "Why is removing only username insufficient for logout?", "answer": "Other login-state values can remain", "choices": ["Other login-state values can remain", "Removing a key automatically restores the old password", "The username is the only value a filter can read", "Logout must delete the user's database row"], "explanation": "A filter can still accept a remaining login flag. Removing one display key does not remove the complete authentication state.", "kind": "concept"}, {"id": "m5q1-v2", "module": 5, "page": 18, "topic": "Framework transfer", "prompt": "A developer copies $routes->get() directly from a CodeIgniter file into a Laravel web route file. What should be retained and adapted?", "answer": "Retain the method/path/handler idea and use Laravel's Route syntax", "choices": ["Retain the method/path/handler idea and use Laravel's Route syntax", "Retain the exact variable because both frameworks share a router", "Move all routes into the Blade view", "Replace every route with an Eloquent query"], "explanation": "The responsibility transfers across frameworks, but the routing APIs differ. Laravel's route definitions use its Route facade and handler conventions.", "kind": "application"}, {"id": "m5q2-v2", "module": 5, "page": 8, "topic": "File responsibilities", "prompt": "A Laravel page needs a layout change with no query change. Which file area is responsible?", "answer": "resources/views/", "choices": ["resources/views/", "database/migrations/", "app/Models/", "database/seeders/"], "explanation": "Blade templates present the supplied data. Schema, seed data, and model queries belong to separate parts of the application.", "kind": "application"}, {"id": "m5q3", "module": 5, "page": 9, "topic": "Structure", "prompt": "Where do normal Laravel web routes live?", "answer": "routes/web.php", "choices": ["routes/web.php", "app/Config/Routes.php", "app/Http/routes.php", "resources/views/routes.php"], "explanation": "The conventional web routes file is routes/web.php.", "kind": "concept"}, {"id": "m5q4", "module": 5, "page": 9, "topic": "Structure", "prompt": "Where are Laravel controllers stored?", "answer": "app/Http/Controllers", "choices": ["app/Http/Controllers", "app/Controllers", "resources/controllers", "routes/Controllers"], "explanation": "Laravel’s controller folder includes the Http subdirectory.", "kind": "concept"}, {"id": "m5q5", "module": 5, "page": 9, "topic": "Blade", "prompt": "Where are Blade views stored?", "answer": "resources/views", "choices": ["resources/views", "app/Views", "public/views", "app/Http/Views"], "explanation": "Laravel templates live in resources/views and use the .blade.php extension.", "kind": "concept"}, {"id": "m5q6-v2", "module": 5, "page": 11, "topic": "Configuration", "prompt": "Which .env setting specifies the application URL?", "answer": "APP_URL", "choices": ["APP_URL", "APP_NAME", "APP_ENV", "APP_DEBUG"], "explanation": "Laravel uses APP_URL, while the CodeIgniter examples use app.baseURL.", "kind": "concept"}, {"id": "m5q7", "module": 5, "page": 13, "topic": "CLI", "prompt": "Which command starts the simple Laravel development server?", "answer": "php artisan serve", "choices": ["php artisan serve", "php artisan route:list", "composer global require laravel/installer", "php spark serve"], "explanation": "Artisan is Laravel’s command-line tool. Its serve command runs the local development server.", "kind": "concept"}, {"id": "m5q8", "module": 5, "page": 21, "topic": "Routing", "prompt": "Which route helper serves a static about Blade view directly?", "answer": "Route::view('/about', 'about')", "choices": ["Route::view('/about', 'about')", "Route::redirect('/about', 'about')", "route('about') by itself", "view('/about', 'about') as a route registration"], "explanation": "Route::view is useful for simple pages that do not yet need controller logic.", "kind": "concept"}, {"id": "m5q9", "module": 5, "page": 23, "topic": "Routing", "prompt": "In Route::get('/tasks/{id}', function ($id) {...}), what does {id} represent?", "answer": "A URL parameter passed into the handler", "choices": ["A URL parameter passed into the handler", "A database model automatically in this untyped closure", "A query-string key that must follow ?", "A fixed view variable that ignores the URL"], "explanation": "Visiting /tasks/15 passes the URL value 15 into the handler.", "kind": "concept"}, {"id": "m5q10", "module": 5, "page": 24, "topic": "CLI", "prompt": "Which command generates PageController?", "answer": "php artisan make:controller PageController", "choices": ["php artisan make:controller PageController", "php artisan make:model PageController", "php artisan route:list PageController", "php artisan make:view PageController"], "explanation": "Artisan generates the controller in app/Http/Controllers.", "kind": "concept"}, {"id": "m5q11", "module": 5, "page": 26, "topic": "CLI", "prompt": "Which command inspects registered Laravel routes?", "answer": "php artisan route:list", "choices": ["php artisan route:list", "php artisan list", "php artisan serve", "php artisan make:controller"], "explanation": "route:list shows Laravel’s registered routes.", "kind": "concept"}, {"id": "m5q12", "module": 5, "page": 27, "topic": "Routing", "prompt": "What does [PageController::class, 'about'] identify?", "answer": "A controller class and its action method", "choices": ["A controller class and its action method", "A Blade template and its data array", "A model class and its table name", "A route URL and its query-string values"], "explanation": "The route calls about() on PageController; the controller class is imported into the route file.", "kind": "concept"}, {"id": "m5q13", "module": 5, "page": 28, "topic": "View data", "prompt": "What is passed as the second argument of view() to supply named variables?", "answer": "An associative array", "choices": ["An associative array", "Only the view filename again", "A controller namespace string", "The raw PHP source of the template"], "explanation": "The keys in the data array become variables that Blade can display.", "kind": "concept"}, {"id": "m5q14-v2", "module": 5, "page": 18, "topic": "Controller routing", "prompt": "A route points to PageController::about, but the action is absent. What must the developer make consistent?", "answer": "The route handler and the actual public controller method", "choices": ["The route handler and the actual public controller method", "The database name and the HTML heading", "The CSS class and the SMTP username", "The seed count and the route name"], "explanation": "A registered controller route identifies a callable action. A route declaration does not generate that action's implementation.", "kind": "application"}, {"id": "m5q15", "module": 5, "page": 32, "topic": "Blade", "prompt": "Which syntax escapes normal Blade output?", "answer": "{{ $title }}", "choices": ["{{ $title }}", "{!! $title !!}", "@php echo $title; @endphp", "<?php echo $title; ?>"], "explanation": "Double curly braces escape values; {!! !!} is raw output.", "kind": "concept"}, {"id": "m5q16-v2", "module": 5, "page": 22, "topic": "View data", "prompt": "A route returns view('about', ['course' => 'IT0049']). Which Blade expression reads the supplied value safely as text?", "answer": "{{ $course }}", "choices": ["{{ $course }}", "{{ $about }}", "{{ $request->course }} automatically", "{{ $view['IT0049'] }}"], "explanation": "The data key course becomes the view variable $course. Blade's ordinary double-brace output escapes that value for HTML.", "kind": "application"}, {"id": "m5q17-v2", "module": 5, "page": 22, "topic": "View-data keys", "prompt": "A controller passes ['heading' => $title]. Which variable belongs in the view?", "answer": "$heading", "choices": ["$heading", "$title automatically", "$data['title'] automatically", "$PageController"], "explanation": "View-data keys determine the view variables. The controller's local source variable does not automatically become a second view variable.", "kind": "application"}, {"id": "m5q18-v2", "module": 5, "page": 29, "topic": "Nested view names", "prompt": "A Laravel template exists at resources/views/tasks/show.blade.php. Which identifier should view() receive?", "answer": "tasks.show", "choices": ["tasks.show", "tasks/show.php", "app.Views.tasks.show", "public.tasks.show"], "explanation": "Laravel's dot notation identifies nested views relative to resources/views. The filename extension is not included in the helper identifier.", "kind": "application"}, {"id": "m5q19-v2", "module": 5, "page": 23, "topic": "Route captures", "prompt": "GET /tasks/18 matches /tasks/{id}. A handler displays a fixed ID of 1 instead. What should be corrected?", "answer": "Use the captured parameter rather than the hard-coded value", "choices": ["Use the captured parameter rather than the hard-coded value", "Rename every task to 18", "Change the route file to a Blade template", "Create eighteen controller methods"], "explanation": "A parameterized route supplies the selected path value. Hard-coded output does not represent the selected record or requested identifier.", "kind": "application"}, {"id": "m5q20-v2", "module": 5, "page": 18, "topic": "Method and path", "prompt": "A route registers GET /contact. A browser sends POST /contact. What does the GET definition establish?", "answer": "Only a GET handler for that path", "choices": ["Only a GET handler for that path", "A handler for all HTTP methods", "A POST handler whenever a form exists", "A resource controller automatically"], "explanation": "A route definition includes an HTTP method. The shared path does not remove that matching requirement.", "kind": "application"}, {"id": "m5q21-v2", "module": 5, "page": 7, "topic": "Package tools", "prompt": "A developer confuses installing the Laravel installer with creating an application. What is the distinction?", "answer": "Installing the installer adds the tool; laravel new creates a project", "choices": ["Installing the installer adds the tool; laravel new creates a project", "Both operations only start the development server", "Installing the tool creates all later projects automatically", "laravel new runs only database migrations"], "explanation": "Tool installation and project creation are different setup steps. Starting the project's server is another separate operation.", "kind": "application"}, {"id": "m5q22-v2", "module": 5, "page": 31, "topic": "Dynamic versus fixed data", "prompt": "Changing /tasks/4 to /tasks/9 leaves the displayed record ID unchanged. Which explanation best fits a hard-coded details action?", "answer": "The action ignores the captured ID when constructing its displayed data", "choices": ["The action ignores the captured ID when constructing its displayed data", "Laravel forbids numeric route parameters", "Blade automatically caches the first task forever", "All GET routes must return the same record"], "explanation": "A dynamic URL does not guarantee dynamic data. Trace whether the handler uses its parameter in the data it returns.", "kind": "application"}, {"id": "m5q23-v2", "module": 5, "page": 20, "topic": "Render versus redirect", "prompt": "A controller should render tasks.index during the current request. Which helper matches that goal?", "answer": "view('tasks.index', $data)", "choices": ["view('tasks.index', $data)", "redirect('/tasks')", "route('tasks.index') by itself", "asset('tasks.index')"], "explanation": "view() renders a template with data. redirect() starts another request, while route() and asset() generate URLs for different purposes.", "kind": "application"}, {"id": "m5q24-v2", "module": 5, "page": 8, "topic": "MVC organization", "prompt": "A Blade template runs its own database setup and queries. Which change best restores MVC separation?", "answer": "Retrieve records through the data layer and pass them through the controller", "choices": ["Retrieve records through the data layer and pass them through the controller", "Move the SQL into the page's CSS file", "Put credentials directly into each template", "Rename the template Controller.blade.php"], "explanation": "Separating retrieval from display keeps templates focused on presentation. Renaming a file does not change its responsibilities.", "kind": "application"}, {"id": "m5q25-v2", "module": 5, "page": 34, "topic": "Testing the page", "prompt": "The route responds with text, but the intended Blade view still fails. What conclusion is justified?", "answer": "Routing can work while the template or its data contract still needs correction", "choices": ["Routing can work while the template or its data contract still needs correction", "A working text response proves every template is valid", "The database must be empty", "The framework must be reinstalled"], "explanation": "A test proves the path it exercises. Rendering text does not test the separate view file and its required variables.", "kind": "application"}, {"id": "m5q26", "module": 5, "page": 10, "topic": "Routes, Blade & setup", "prompt": "Which environment setting names the application?", "answer": "APP_NAME", "choices": ["APP_NAME", "APP_URL", "APP_ENV", "APP_DEBUG"], "explanation": "APP_NAME identifies the application. It is separate from its address, database connection, and mail transport settings.", "kind": "concept"}, {"id": "m5q27-v2", "module": 5, "page": 10, "topic": "Environment configuration", "prompt": "A local project moves to another database while its view code stays the same. Where does the connection change primarily belong?", "answer": "The active environment's database settings", "choices": ["The active environment's database settings", "Every Blade interpolation", "The public image directory", "Each controller's class name"], "explanation": "Environment configuration supplies deployment-specific connection values. It does not require embedding credentials into presentation templates.", "kind": "application"}, {"id": "m5q28-v2", "module": 5, "page": 10, "topic": "Debug configuration", "prompt": "A local error page shows detailed debugging output. Which setting is directly relevant to that behavior?", "answer": "APP_DEBUG", "choices": ["APP_DEBUG", "DB_DATABASE", "MAIL_FROM_NAME", "The task model's $fillable"], "explanation": "APP_DEBUG controls detailed application debugging behavior. A database name or writable-field list does not serve that role.", "kind": "application"}, {"id": "m5q29-v2", "module": 5, "page": 13, "topic": "Development server", "prompt": "php artisan serve works, but the shell reports that artisan is missing from another folder. What explains the difference?", "answer": "The command must run from the Laravel project containing artisan", "choices": ["The command must run from the Laravel project containing artisan", "The browser deletes artisan after the first request", "The database creates artisan only after seeding", "Blade compiles artisan inside resources/views"], "explanation": "Artisan is the project's command-line entry file. Running PHP from an unrelated directory does not locate that file automatically.", "kind": "application"}, {"id": "m5q30", "module": 5, "page": 11, "topic": "Routes, Blade & setup", "prompt": "Does setting APP_URL start a development server?", "answer": "No", "choices": ["No", "Yes; it starts Apache automatically", "Yes; it runs artisan serve in the background", "Only when APP_DEBUG is true"], "explanation": "No. Laravel is another server-side PHP framework. The concept does not restart from zero: a route receives a request, a controller coordinates work, a model handles data, and a view presents the result. What changes is the framework’s conventions, syntax, and tooling. The module emphasizes looking for the same responsibility in a different location.", "kind": "concept"}, {"id": "m5q31", "module": 5, "page": 11, "topic": "Routes, Blade & setup", "prompt": "What does a local virtual-host URL require besides APP_URL?", "answer": "The corresponding local server/host setup", "choices": ["The corresponding local server/host setup", "Only a different Blade extension", "Only the application's display name", "Only a task model's table setting"], "explanation": "A URL setting does not create a web-server virtual host or local hostname mapping. The server setup must agree with the configured address.", "kind": "concept"}, {"id": "m5q32", "module": 5, "page": 12, "topic": "Routes, Blade & setup", "prompt": "What reads environment values into Laravel configuration?", "answer": "The config/ configuration files", "choices": ["The config/ configuration files", "The Blade output delimiter alone", "The route's captured parameter alone", "The seeder class name alone"], "explanation": "Configuration files obtain environment-specific values for their settings. Do not embed real connection secrets in view templates.", "kind": "concept"}, {"id": "m5q33", "module": 5, "page": 13, "topic": "Routes, Blade & setup", "prompt": "Which tool is Laravel's command-line interface?", "answer": "Artisan", "choices": ["Artisan", "Composer", "Spark", "Blade"], "explanation": "Artisan. Laravel uses the project-local Artisan tool. Package installation, project generation, and starting a development server are different steps.", "kind": "concept"}, {"id": "m5q34-v2", "module": 5, "page": 18, "topic": "Route files", "prompt": "An action exists in app/Http/Controllers, but there is no matching web route. What additional connection is required?", "answer": "A suitable definition in routes/web.php", "choices": ["A suitable definition in routes/web.php", "A duplicate class in resources/views", "A migration named after the controller", "A public image named after the action"], "explanation": "A controller class provides actions. The route maps an incoming web request to the intended action.", "kind": "application"}, {"id": "m5q35", "module": 5, "page": 13, "topic": "Routes, Blade & setup", "prompt": "When composer.json defines a dev script, which command runs that script?", "answer": "composer run dev", "choices": ["composer run dev", "php artisan migrate", "composer install", "php artisan route:list"], "explanation": "composer run dev. Laravel uses the project-local Artisan tool. Package installation, project generation, and starting a development server are different steps.", "kind": "concept"}, {"id": "m5q36", "module": 5, "page": 14, "topic": "Routes, Blade & setup", "prompt": "What should you check when laravel is not recognized?", "answer": "Composer's global bin directory on PATH", "choices": ["Composer's global bin directory on PATH", "Only the routes/web.php file", "Only the model's $fillable", "Only the browser's current URL"], "explanation": "A global Composer tool must be discoverable through the shell PATH. Creating a route cannot repair a missing executable command.", "kind": "concept"}, {"id": "m5q37", "module": 5, "page": 14, "topic": "Routes, Blade & setup", "prompt": "What does a port-in-use error indicate?", "answer": "Another process uses that port", "choices": ["Another process uses that port", "The database table has no records", "The route name already exists", "The view is missing a variable"], "explanation": "A port-in-use error concerns a listening process. Stop the conflicting server or deliberately choose another port and matching address.", "kind": "concept"}, {"id": "m5q38", "module": 5, "page": 17, "topic": "Routes, Blade & setup", "prompt": "Must every simple Laravel route use a controller?", "answer": "No; a route can respond directly", "choices": ["No; a route can respond directly", "Yes; closures cannot return a response", "Yes; Route::view requires a controller action", "Only if the response is a static string"], "explanation": "No; a route can respond directly. Laravel web routes map an HTTP method and path to a response or handler. A route name, template name, and filesystem path serve different roles.", "kind": "concept"}, {"id": "m5q39-v2", "module": 5, "page": 20, "topic": "Response forms", "prompt": "A route needs to return a small fixed text response without a template. Which approach is valid in the taught routing patterns?", "answer": "Return the text from a route closure", "choices": ["Return the text from a route closure", "Create a database table just to store the response", "Return the text only from a migration", "Require a Blade view for every possible response"], "explanation": "The foundation module shows multiple response patterns. A route closure can return text; a template is useful when presentation needs it.", "kind": "application"}, {"id": "m5q40", "module": 5, "page": 19, "topic": "Routes, Blade & setup", "prompt": "What does the closure in Route::get execute for?", "answer": "The matched request", "choices": ["The matched request", "Every application request regardless of method or path", "Only the migration command", "Only when the template name matches the URL"], "explanation": "The matched request. Laravel web routes map an HTTP method and path to a response or handler. A route name, template name, and filesystem path serve different roles.", "kind": "concept"}, {"id": "m5q41", "module": 5, "page": 20, "topic": "Routes, Blade & setup", "prompt": "Which CI file corresponds to Laravel's routes/web.php?", "answer": "app/Config/Routes.php", "choices": ["app/Config/Routes.php", "app/Config/App.php", "app/Controllers/Routes.php", "app/Views/routes.php"], "explanation": "app/Config/Routes.php. Laravel web routes map an HTTP method and path to a response or handler. A route name, template name, and filesystem path serve different roles.", "kind": "concept"}, {"id": "m5q42", "module": 5, "page": 21, "topic": "Routes, Blade & setup", "prompt": "Which route helper directly renders a static view?", "answer": "Route::view()", "choices": ["Route::view()", "Route::redirect()", "route()", "asset()"], "explanation": "Route::view(). Laravel view names use dots for nested templates under resources/views. The data keys passed to view() become template variables.", "kind": "concept"}, {"id": "m5q43-v2", "module": 5, "page": 25, "topic": "Generated controllers", "prompt": "After make:controller creates a controller file, what work still remains for a new page?", "answer": "Implement its action and connect a matching route and view as needed", "choices": ["Implement its action and connect a matching route and view as needed", "Assume every public method already has a URL", "Run migrate:fresh to generate the page HTML", "Insert the controller source into .env"], "explanation": "Generation creates a starting class. The page still needs an implemented handler and the intended request-to-response connections.", "kind": "application"}, {"id": "m5q44-v2", "module": 5, "page": 29, "topic": "Escaped output", "prompt": "A visitor's name contains HTML tags. How should ordinary Blade output display it as text?", "answer": "Use {{ $name }}", "choices": ["Use {{ $name }}", "Use raw output without checking its source", "Put the name in the database password setting", "Use a route placeholder as an escaping function"], "explanation": "Ordinary Blade double braces escape output. A dynamic value is not safe HTML merely because it came through a controller.", "kind": "application"}, {"id": "m5q45", "module": 5, "page": 23, "topic": "Routes, Blade & setup", "prompt": "Does capturing {id} itself retrieve a database record?", "answer": "No", "choices": ["No", "Yes; every captured ID becomes an Eloquent model", "Yes; the URL value creates its own database record", "Only when the ID is numeric"], "explanation": "No. Laravel is another server-side PHP framework. The concept does not restart from zero: a route receives a request, a controller coordinates work, a model handles data, and a view presents the result. What changes is the framework’s conventions, syntax, and tooling. The module emphasizes looking for the same responsibility in a different location.", "kind": "concept"}, {"id": "m5q46", "module": 5, "page": 24, "topic": "Routes, Blade & setup", "prompt": "After generation, where does PageController.php belong?", "answer": "app/Http/Controllers/PageController.php", "choices": ["app/Http/Controllers/PageController.php", "app/Controllers/PageController.php", "routes/PageController.php", "resources/views/PageController.php"], "explanation": "app/Http/Controllers/PageController.php. The exact comparison on p. 20 pairs app/Controllers/Pages.php with app/Http/Controllers/PageController.php. It pairs app/Views/about.php with resources/views/about.blade.php. Both frameworks use a view('about') call in the examples, but they resolve that name through their own view locations.", "kind": "concept"}, {"id": "m5q47", "module": 5, "page": 25, "topic": "Routes, Blade & setup", "prompt": "Which namespace does PageController use?", "answer": "App\\Http\\Controllers", "choices": ["App\\Http\\Controllers", "App\\Controllers", "App\\Models", "Illuminate\\Controllers"], "explanation": "The namespace matches the controller directory. A route import must identify that controller class correctly.", "kind": "concept"}, {"id": "m5q48-v2", "module": 5, "page": 23, "topic": "Parameter flow", "prompt": "Which sequence preserves the purpose of a selected task ID?", "answer": "Route capture → handler parameter → selected data → view", "choices": ["Route capture → handler parameter → selected data → view", "View filename → database password → route capture", "Migration batch → Composer install → fixed HTML", "Task title → APP_DEBUG → generated controller"], "explanation": "Trace the identifier from the URL through the action into its data. This makes it easier to find where a dynamic value became fixed or mismatched.", "kind": "application"}, {"id": "m5q49", "module": 5, "page": 26, "topic": "Routes, Blade & setup", "prompt": "Which command lists available Artisan commands?", "answer": "php artisan list", "choices": ["php artisan list", "php artisan route:list", "php artisan serve", "composer show"], "explanation": "php artisan list. Laravel uses the project-local Artisan tool. Package installation, project generation, and starting a development server are different steps.", "kind": "concept"}, {"id": "m5q50", "module": 5, "page": 26, "topic": "Routes, Blade & setup", "prompt": "Which command lists Laravel routes?", "answer": "php artisan route:list", "choices": ["php artisan route:list", "php artisan list", "php artisan make:controller", "php artisan migrate:status"], "explanation": "php artisan route:list. Laravel web routes map an HTTP method and path to a response or handler. A route name, template name, and filesystem path serve different roles.", "kind": "concept"}, {"id": "m5q51", "module": 5, "page": 27, "topic": "Routes, Blade & setup", "prompt": "What does PageController::class identify in the route handler array?", "answer": "The controller class", "choices": ["The controller class", "The Blade template filename", "The task model's table name", "The route's HTTP method"], "explanation": "The controller class. Laravel web routes map an HTTP method and path to a response or handler. A route name, template name, and filesystem path serve different roles.", "kind": "concept"}, {"id": "m5q52", "module": 5, "page": 27, "topic": "Routes, Blade & setup", "prompt": "What does the handler array's 'about' string identify?", "answer": "The controller action", "choices": ["The controller action", "The view filename", "The route's numeric parameter", "The database connection name"], "explanation": "The handler array pairs a controller class with its selected method name. It does not name a Blade file or database column.", "kind": "concept"}, {"id": "m5q53", "module": 5, "page": 28, "topic": "Routes, Blade & setup", "prompt": "What does view('about', $data) pass to the template?", "answer": "Named values from the array", "choices": ["Named values from the array", "The controller's entire local variable scope automatically", "The view filename as every variable", "A saved database record automatically"], "explanation": "Named values from the array. Laravel view names use dots for nested templates under resources/views. The data keys passed to view() become template variables.", "kind": "concept"}, {"id": "m5q54-v2", "module": 5, "page": 8, "topic": "Public assets", "prompt": "A developer places a CSS file under app/Http/Controllers and expects its browser URL to work. Which distinction matters?", "answer": "Publicly served assets and internal controller source have different locations", "choices": ["Publicly served assets and internal controller source have different locations", "Every PHP folder is automatically a public asset directory", "All assets must be stored as task rows", "Blade can only load files from database/migrations"], "explanation": "The public directory serves public files. Controller source belongs to internal application structure, not the browser asset path.", "kind": "application"}, {"id": "m5q55-v2", "module": 5, "page": 9, "topic": "CLI responsibilities", "prompt": "A developer runs php spark routes inside a Laravel project. What is the appropriate framework-specific equivalent?", "answer": "php artisan route:list", "choices": ["php artisan route:list", "php artisan make:routes --spark", "php spark route:list", "composer serve:routes"], "explanation": "Laravel uses Artisan, while CodeIgniter uses Spark. Learn the equivalent responsibility without treating the command names as interchangeable.", "kind": "application"}, {"id": "m5q56-v2", "module": 5, "page": 25, "topic": "Namespaces and imports", "prompt": "A route cannot resolve PageController even though its file exists. What should be checked before changing the database?", "answer": "The controller namespace and import in routes/web.php", "choices": ["The controller namespace and import in routes/web.php", "The title column's default", "The number of seeded records", "The storage disk's image dimensions"], "explanation": "Class resolution occurs before the page's data work. Check the imported class and namespace against the actual controller.", "kind": "application"}, {"id": "m5q57", "module": 5, "page": 32, "topic": "Routes, Blade & setup", "prompt": "Which syntax prints escaped Blade output?", "answer": "{{ $title }}", "choices": ["{{ $title }}", "{!! $title !!}", "@php echo $title; @endphp", "<?php echo $title; ?>"], "explanation": "Ordinary Blade double braces escape the value for HTML display. Raw output has a different security meaning.", "kind": "concept"}, {"id": "m5q58", "module": 5, "page": 32, "topic": "Routes, Blade & setup", "prompt": "Which Blade syntax permits raw unescaped output?", "answer": "{!! $title !!}", "choices": ["{!! $title !!}", "{{ $title }}", "{{ e($title) }}", "@{{ $title }} as server-side output"], "explanation": "Raw Blade output permits HTML interpretation. Do not use it for untrusted content merely to make tags render.", "kind": "concept"}, {"id": "m5q59", "module": 5, "page": 33, "topic": "Routes, Blade & setup", "prompt": "Why does a missing controller import break a class-based route?", "answer": "The route cannot resolve the intended class reference", "choices": ["The route cannot resolve the intended class reference", "Every controller must be placed in public/", "The database cannot find a table named after the route", "Blade requires a duplicate controller definition"], "explanation": "The route cannot resolve the intended class reference. Laravel web routes map an HTTP method and path to a response or handler. A route name, template name, and filesystem path serve different roles.", "kind": "concept"}, {"id": "m5q60", "module": 5, "page": 33, "topic": "Routes, Blade & setup", "prompt": "Which responsibility remains the controller's in both frameworks?", "answer": "Coordinate the request and choose the response", "choices": ["Coordinate the request and choose the response", "Render all database schema migrations", "Store presentation HTML in the model", "Perform every query directly inside the view"], "explanation": "Both controllers coordinate requests and responses. Their framework APIs differ, while the MVC responsibility remains recognizable.", "kind": "concept"}, {"id": "m6q1", "module": 6, "page": 6, "topic": "Data layer", "prompt": "Which Laravel component describes database table structure changes?", "answer": "Migration", "choices": ["Migration", "Seeder", "Blade view", "Route middleware"], "explanation": "Migrations define and version schema; seeders insert sample records.", "kind": "concept"}, {"id": "m6q2", "module": 6, "page": 8, "topic": "Structure", "prompt": "Where are Laravel seeders stored?", "answer": "database/seeders", "choices": ["database/seeders", "database/migrations", "app/Models", "resources/seeders"], "explanation": "Laravel separates database/migrations, database/seeders, and app/Models.", "kind": "concept"}, {"id": "m6q3", "module": 6, "page": 10, "topic": "Migrations", "prompt": "Which migration helper adds created_at and updated_at columns?", "answer": "$table->timestamps()", "choices": ["$table->timestamps()", "$table->timestamp('created_at') alone", "$table->softDeletes()", "$table->id()"], "explanation": "timestamps() creates the pair of timestamp columns.", "kind": "concept"}, {"id": "m6q4", "module": 6, "page": 11, "topic": "Migrations", "prompt": "Which column modifier permits an empty database value represented by NULL?", "answer": "nullable()", "choices": ["nullable()", "unique()", "default(false)", "timestamps()"], "explanation": "nullable() allows NULL; it is separate from setting a default value.", "kind": "concept"}, {"id": "m6q5", "module": 6, "page": 12, "topic": "CLI", "prompt": "Which command runs pending Laravel migrations?", "answer": "php artisan migrate", "choices": ["php artisan migrate", "php artisan db:seed", "php artisan make:migration", "php artisan migrate:status"], "explanation": "migrate applies migrations that have not yet run.", "kind": "concept"}, {"id": "m6q6", "module": 6, "page": 12, "topic": "CLI", "prompt": "What does php artisan migrate:rollback undo?", "answer": "The last batch of migrations", "choices": ["The last batch of migrations", "Every migration and all backups automatically", "Only the most recently inserted task", "Only the latest seeder run"], "explanation": "rollback reverses the last migration batch.", "kind": "concept"}, {"id": "m6q7", "module": 6, "page": 12, "topic": "CLI", "prompt": "What does php artisan migrate:fresh do?", "answer": "Rebuilds all tables from zero", "choices": ["Rebuilds all tables from zero", "Runs only migrations not yet applied while preserving tables", "Rolls back only the latest batch", "Restores all deleted rows from a backup"], "explanation": "fresh drops tables and reruns migrations, so the module reserves destructive resets for local development.", "kind": "concept"}, {"id": "m6q8", "module": 6, "page": 13, "topic": "Seeders", "prompt": "What is the purpose of TaskSeeder?", "answer": "Insert predictable sample task records", "choices": ["Insert predictable sample task records", "Define the table's columns", "Render the task-list template", "Authorize access to a selected task"], "explanation": "Seeders make demos and debugging repeatable by providing known data.", "kind": "concept"}, {"id": "m6q9", "module": 6, "page": 18, "topic": "Eloquent", "prompt": "Which command generates the Task model?", "answer": "php artisan make:model Task", "choices": ["php artisan make:model Task", "php artisan make:controller Task", "php artisan make:migration Task", "php artisan make:seeder Task"], "explanation": "The model is generated as app/Models/Task.php.", "kind": "concept"}, {"id": "m6q10", "module": 6, "page": 19, "topic": "Eloquent", "prompt": "Which Eloquent model property allows fields for mass assignment?", "answer": "$fillable", "choices": ["$fillable", "$table", "$primaryKey", "$casts"], "explanation": "The module lists title and status in $fillable for create() and update().", "kind": "concept"}, {"id": "m6q11", "module": 6, "page": 21, "topic": "Eloquent", "prompt": "Which Eloquent call retrieves all task records?", "answer": "Task::all()", "choices": ["Task::all()", "Task::first()", "Task::count()", "Task::find(1)"], "explanation": "Task::all() retrieves all records; latest() alone still describes a query.", "kind": "concept"}, {"id": "m6q12", "module": 6, "page": 21, "topic": "View data", "prompt": "What does compact('tasks') create?", "answer": "An array with the key tasks and the value of $tasks", "choices": ["An array with the key tasks and the value of $tasks", "A database query that automatically runs findAll", "A new collection containing all tasks", "A renamed database table"], "explanation": "PHP compact() builds an array from existing variable names.", "kind": "concept"}, {"id": "m6q13", "module": 6, "page": 24, "topic": "Eloquent", "prompt": "Which method executes the filtered query Task::where(...)->orderBy(...)?", "answer": "get()", "choices": ["get()", "first()", "count()", "exists()"], "explanation": "where() filters, orderBy() sorts, and get() retrieves the matching results.", "kind": "concept"}, {"id": "m6q14", "module": 6, "page": 25, "topic": "Missing records", "prompt": "What happens when Task::findOrFail($id) cannot find a task?", "answer": "A not-found exception produces a 404 response", "choices": ["A not-found exception produces a 404 response", "A null model that Blade always handles automatically", "An empty collection with a title property", "An automatic insertion of the missing task"], "explanation": "findOrFail() is used when a missing row should become a 404 page.", "kind": "concept"}, {"id": "m6q15", "module": 6, "page": 23, "topic": "Blade", "prompt": "Which expression accesses a Task object’s title in Blade?", "answer": "{{ $task->title }}", "choices": ["{{ $task->title }}", "{{ $tasks->title }} after retrieving a collection", "{{ Task.title }}", "{{ $task('title') }}"], "explanation": "The module’s Eloquent records are model objects displayed with -> property access.", "kind": "concept"}, {"id": "m6q16", "module": 6, "page": 32, "topic": "Debugging", "prompt": "Which command opens Laravel’s interactive environment for quick model checks?", "answer": "php artisan tinker", "choices": ["php artisan tinker", "php artisan route:list", "php artisan migrate:status", "php artisan make:model"], "explanation": "Tinker lets you inspect records with calls such as Task::count() and Task::first().", "kind": "concept"}, {"id": "m6q17-v2", "module": 6, "page": 25, "topic": "Missing records", "prompt": "A details page should stop with a normal not-found response when its ID is absent. Which lookup fits?", "answer": "Task::findOrFail($id)", "choices": ["Task::findOrFail($id)", "Task::all()", "Task::where('id', $id) without retrieval", "Task::count()"], "explanation": "findOrFail retrieves one model by primary key or raises the not-found path. A collection or count does not supply that same contract.", "kind": "application"}, {"id": "m6q18-v2", "module": 6, "page": 6, "topic": "Data-layer responsibilities", "prompt": "A teammate wants repeatable demo rows, while another wants the table's columns defined. Which pairing is correct?", "answer": "Seeder for rows; migration for schema", "choices": ["Seeder for rows; migration for schema", "Migration for rows; Blade for schema", "Model for schema; route for rows", "Controller namespace for both"], "explanation": "Migrations describe database structure. Seeders insert intended sample records. These responsibilities remain separate even when a setup command runs both.", "kind": "application"}, {"id": "m6q19-v2", "module": 6, "page": 10, "topic": "Migration execution", "prompt": "A migration file exists, but the tasks table is absent in the active database. What should you check?", "answer": "Whether the migration ran against that configured database", "choices": ["Whether the migration ran against that configured database", "Whether the Blade title is bold", "Whether the view uses a dark theme", "Whether a seeder has a descriptive class name"], "explanation": "Generating a migration file does not execute it. Check the active connection and migration state before assuming the schema exists.", "kind": "application"}, {"id": "m6q20-v2", "module": 6, "page": 25, "topic": "Collection versus model", "prompt": "A template reads $tasks->title after Task::all(). Why is that the wrong expectation?", "answer": "all() returns a collection that should be iterated for individual models", "choices": ["all() returns a collection that should be iterated for individual models", "all() returns only the first title string", "The title column can only be read in SQL", "The route must use POST for property access"], "explanation": "A collection contains models. Read $task->title from an individual task, usually inside a loop.", "kind": "application"}, {"id": "m6q21-v2", "module": 6, "page": 23, "topic": "Object properties", "prompt": "An Eloquent task model is passed to Blade. Which access form matches the taught object pattern?", "answer": "$task->title", "choices": ["$task->title", "$task::title()", "Task.title", "$task('title')"], "explanation": "Eloquent returns model objects in this pattern. Their attribute access differs from the CI array-row pattern taught earlier.", "kind": "application"}, {"id": "m6q22-v2", "module": 6, "page": 22, "topic": "Ordering intent", "prompt": "A list must show the most recently created tasks first. What does latest()->get() express in the standard timestamp setup?", "answer": "Order by created_at descending, then retrieve", "choices": ["Order by created_at descending, then retrieve", "Filter only completed tasks", "Select the largest title alphabetically", "Return only one record automatically"], "explanation": "latest() normally orders by created_at descending. It neither adds a status filter nor reduces the collection to one record by itself.", "kind": "application"}, {"id": "m6q23-v2", "module": 6, "page": 30, "topic": "Empty data diagnosis", "prompt": "The task view renders correctly but shows no seeded tasks. Which development check is useful before rewriting the view?", "answer": "Inspect Task::count() against the active database", "choices": ["Inspect Task::count() against the active database", "Change every foreach to a database migration", "Run migrate:fresh without checking the data", "Rename the route to the seeder class"], "explanation": "An empty result can be correct when no rows exist. Check the connection and actual data before blaming a functioning template.", "kind": "application"}, {"id": "m6q24-v2", "module": 6, "page": 12, "topic": "Destructive commands", "prompt": "A database contains work that must be preserved. Why is migrate:fresh unsuitable as a routine page repair?", "answer": "It drops tables before rebuilding the schema", "choices": ["It drops tables before rebuilding the schema", "It only recompiles Blade views", "It only sorts existing task rows", "It only clears the browser session"], "explanation": "migrate:fresh destroys existing tables. Diagnose the failure and protect required data before using destructive classroom reset commands.", "kind": "application"}, {"id": "m6q25-v2", "module": 6, "page": 30, "topic": "Null inspection", "prompt": "In Tinker, Task::first() returns null. Why does immediately reading ->title fail?", "answer": "There is no model on which to read the property", "choices": ["There is no model on which to read the property", "The first title is always an empty string", "Tinker only permits array access", "The migration has renamed title automatically"], "explanation": "first() can return no result. Check the result before reading model properties during inspection.", "kind": "application"}, {"id": "m6q26-v2", "module": 6, "page": 11, "topic": "Column choices", "prompt": "A notes field is optional. Which schema modifier permits SQL NULL for that column?", "answer": "nullable()", "choices": ["nullable()", "default(false) by itself", "unique() by itself", "timestamps()"], "explanation": "nullable() allows a null value. Defaults, uniqueness, and timestamps describe other schema behavior.", "kind": "application"}, {"id": "m6q27-v2", "module": 6, "page": 11, "topic": "Defaults", "prompt": "A boolean is_active column has default(false). An insertion omits that field. What does the database default supply?", "answer": "false", "choices": ["false", "true because a record was created", "The current user's ID", "The previous row's value"], "explanation": "A default supplies an omitted column value. It does not infer activation or copy unrelated record data.", "kind": "application"}, {"id": "m6q28-v2", "module": 6, "page": 20, "topic": "Table naming", "prompt": "The Task model follows the standard naming convention. Which table does Eloquent normally infer?", "answer": "tasks", "choices": ["tasks", "TaskController", "task_views", "TaskSeeder"], "explanation": "Eloquent normally infers a plural snake-case table name from the model. Explicit configuration can change conventions, so the model and actual schema must agree.", "kind": "application"}, {"id": "m6q29-v2", "module": 6, "page": 24, "topic": "View contract", "prompt": "The controller uses compact('tasks'), but no $tasks variable was assigned. What must be corrected?", "answer": "Retrieve and assign $tasks before constructing the view data", "choices": ["Retrieve and assign $tasks before constructing the view data", "Create a database column named compact", "Rename the view to tasks.compact", "Add compact to $fillable"], "explanation": "compact() builds an array from existing variables. It does not query the database or invent the missing variable.", "kind": "application"}, {"id": "m6q30-v2", "module": 6, "page": 13, "topic": "Repeatable setup", "prompt": "A seeder's run() inserts rows unconditionally. What can happen if it runs again against an existing table?", "answer": "Additional rows or a constraint failure, depending on the data and schema", "choices": ["Additional rows or a constraint failure, depending on the data and schema", "Automatic removal of all old rows", "Automatic rollback of every migration", "Automatic conversion of rows into Blade views"], "explanation": "Repeatable setup code does not imply deduplication. Unconditional inserts repeat unless the code or constraints prevent them.", "kind": "application"}, {"id": "m6q31-v2", "module": 6, "page": 12, "topic": "Rollback meaning", "prompt": "A migration's down() drops a table. What does rolling it back fail to guarantee?", "answer": "Recovery of the rows removed by that drop", "choices": ["Recovery of the rows removed by that drop", "Execution of the migration's reverse operation", "A change to the tracked migration state when successful", "Removal of the schema change described by down()"], "explanation": "Rollback executes reverse schema operations; it is not a data backup. Dropping and recreating a table does not restore lost records.", "kind": "application"}, {"id": "m6q32-v2", "module": 6, "page": 6, "topic": "Environment diagnosis", "prompt": "Migration commands succeed, but the app uses a different configured SQLite file. What should be made consistent?", "answer": "The active database connection and file path used by both operations", "choices": ["The active database connection and file path used by both operations", "The task title's capitalization", "The Blade heading's ID attribute", "The number of controller methods"], "explanation": "A successful operation on one database does not populate another. Confirm the active configuration before assuming the app reads the migrated file.", "kind": "application"}, {"id": "m6q33-v2", "module": 6, "page": 13, "topic": "Seeding order", "prompt": "TaskSeeder tries to insert rows before the tasks table exists. Which order fits a clean setup?", "answer": "Create the schema, then seed the records", "choices": ["Create the schema, then seed the records", "Render the list, then create the database", "Seed records, then define their columns", "Run the controller generator after every insert"], "explanation": "Insert operations need the target table. Migration and model setup must support the seeder's writes.", "kind": "application"}, {"id": "m6q34-v2", "module": 6, "page": 18, "topic": "Mass assignment", "prompt": "Task::create($validated) does not accept a desired field. Which model configuration should you inspect?", "answer": "The intended writable fields in $fillable", "choices": ["The intended writable fields in $fillable", "The view's filename extension", "The route's display label", "The database host's spelling as the only cause"], "explanation": "Eloquent mass-assignment protection controls permitted fields for create() and similar array-based writes. Validation and schema definitions are separate checks.", "kind": "application"}, {"id": "m6q35-v2", "module": 6, "page": 24, "topic": "MVC data flow", "prompt": "Which arrangement keeps a task list aligned with the taught Laravel MVC flow?", "answer": "Model retrieves records; controller passes tasks; Blade loops and displays", "choices": ["Model retrieves records; controller passes tasks; Blade loops and displays", "Blade migrates tables; model prints HTML; route stores passwords", "Seeder renders HTML on every page request", "Migration handles the visitor's GET request directly"], "explanation": "The controller coordinates retrieval and presentation. Migrations and seeders support database setup, not normal page rendering.", "kind": "application"}, {"id": "m6q36-v2", "module": 6, "page": 12, "topic": "Reset commands", "prompt": "Which statement correctly distinguishes migrate:refresh from migrate:fresh?", "answer": "refresh rolls back and reruns migrations; fresh drops tables and migrates", "choices": ["refresh rolls back and reruns migrations; fresh drops tables and migrates", "Both commands only add sample rows", "fresh preserves all existing table data", "refresh only restarts the web server"], "explanation": "Both can destroy data, but they rebuild through different operations. Neither is a harmless substitute for diagnosing a display error.", "kind": "application"}, {"id": "m6q37-v2", "module": 6, "page": 26, "topic": "Status display", "prompt": "A Blade condition prints Done for done and Pending for every other value. A new unexpected status appears. What is the limitation?", "answer": "The display branch assumes two statuses and does not validate arbitrary stored values", "choices": ["The display branch assumes two statuses and does not validate arbitrary stored values", "Blade automatically rejects the new status at insertion", "The migration automatically converts it to pending", "The route placeholder validates the status"], "explanation": "Presentation logic labels values; it does not enforce database or request validity. Keep the accepted values and displayed cases consistent.", "kind": "application"}, {"id": "m6q38", "module": 6, "page": 18, "topic": "Schema & Eloquent", "prompt": "What does generating the Task model NOT do by itself?", "answer": "Insert the demonstration task records", "choices": ["Insert the demonstration task records", "Define the model class", "Provide a place to configure writable fields", "Provide a class used for record queries"], "explanation": "Insert the demonstration task records. Eloquent models represent records. Collections, one model, counts, and query builders require different handling.", "kind": "concept"}, {"id": "m6q39", "module": 6, "page": 19, "topic": "Schema & Eloquent", "prompt": "Which property controls allowed mass-assignment attributes?", "answer": "$fillable", "choices": ["$fillable", "$table", "$primaryKey", "$casts"], "explanation": "$fillable. $fillable identifies attributes allowed through mass-assignment operations such as create([...]) and update([...]). It is comparable in purpose to CodeIgniter’s $allowedFields for the course’s writes. <mark>It does not validate input or authorize the person performing the write.</mark> A column must still exist in the schema, and validation should still return the fields you intend to save.", "kind": "concept"}, {"id": "m6q40", "module": 6, "page": 19, "topic": "Schema & Eloquent", "prompt": "Does fillable validate the content of title?", "answer": "No; validation is separate", "choices": ["No; validation is separate", "Yes; writable fields pass every validation rule", "Yes; it enforces required and max length automatically", "Only when the column is a string"], "explanation": "Mass-assignment permission identifies writable attributes. Request validation must separately check values such as required text and length.", "kind": "concept"}, {"id": "m6q41", "module": 6, "page": 19, "topic": "Schema & Eloquent", "prompt": "Which default table convention pairs with Task?", "answer": "tasks", "choices": ["tasks", "task", "TaskModel", "task_records by requirement"], "explanation": "tasks. Under the convention used here, Task maps to tasks, its primary key is id, and timestamps use the conventional columns. These conventions explain why the Laravel example needs fewer explicit table properties than TaskModel in CodeIgniter.", "kind": "concept"}, {"id": "m6q42", "module": 6, "page": 20, "topic": "Schema & Eloquent", "prompt": "Which earlier CI concept corresponds to Eloquent's model role?", "answer": "CodeIgniter Models", "choices": ["CodeIgniter Models", "CodeIgniter Views", "CodeIgniter route filters", "CodeIgniter environment files"], "explanation": "CodeIgniter Models. Eloquent models represent records. Collections, one model, counts, and query builders require different handling.", "kind": "concept"}, {"id": "m6q43", "module": 6, "page": 21, "topic": "Schema & Eloquent", "prompt": "What does compact('tasks') construct?", "answer": "An array using the existing $tasks variable", "choices": ["An array using the existing $tasks variable", "A new query that reads all task rows", "A view filename with no data", "A new task model instance"], "explanation": "compact builds view data from an existing variable. It does not execute a model query or retrieve missing records.", "kind": "concept"}, {"id": "m6q44", "module": 6, "page": 22, "topic": "Schema & Eloquent", "prompt": "Which Blade variable receives the 'tasks' array key?", "answer": "$tasks", "choices": ["$tasks", "$task", "$items automatically", "$data['Task'] automatically"], "explanation": "$tasks. Task::all() retrieves all tasks. compact('tasks') is a PHP helper that builds ['tasks' => $tasks] from an existing local variable; it does not query the database. view('tasks.index') uses Laravel’s dotted view naming and resolves to resources/views/tasks/index.blade.php.", "kind": "concept"}, {"id": "m6q45", "module": 6, "page": 23, "topic": "Schema & Eloquent", "prompt": "Which directive begins the collection loop?", "answer": "@foreach", "choices": ["@foreach", "@if", "@error", "@isset"], "explanation": "The loop visits the models in the collection. Read each individual task attribute inside the loop, then close the directive.", "kind": "concept"}, {"id": "m6q46-v2", "module": 6, "page": 18, "topic": "Three responsibilities", "prompt": "A title field exists in the schema and $fillable. Why must a request still validate it?", "answer": "Column existence and write permission do not establish acceptable input", "choices": ["Column existence and write permission do not establish acceptable input", "$fillable checks every business rule automatically", "A migration runs on every form submission", "A string column automatically enforces the form's required rule"], "explanation": "Schema defines storage, fillable controls array-based writes, and validation checks input. All three can be necessary for the same field.", "kind": "application"}, {"id": "m6q47", "module": 6, "page": 24, "topic": "Schema & Eloquent", "prompt": "Which method executes the filtered Eloquent retrieval?", "answer": "get()", "choices": ["get()", "first()", "count()", "exists()"], "explanation": "get(). Read the chain as condition → order → execute retrieval. get() retrieves the query’s results. all() is the simple retrieve-everything method, not the terminal method to append after a where() chain in these examples.", "kind": "concept"}, {"id": "m6q48", "module": 6, "page": 24, "topic": "Schema & Eloquent", "prompt": "Which call filters the query to pending status?", "answer": "Task::where('status', 'pending')", "choices": ["Task::where('status', 'pending')", "Task::orderBy('status', 'ASC')", "Task::latest()", "Task::count()"], "explanation": "where describes the status condition. Add a retrieval operation such as get when the controller needs the matching records.", "kind": "concept"}, {"id": "m6q49", "module": 6, "page": 25, "topic": "Schema & Eloquent", "prompt": "What response normally results when findOrFail cannot find the task?", "answer": "404", "choices": ["404", "200 with a new task inserted", "302 to a task selected at random", "An empty model guaranteed to have title"], "explanation": "404. findOrFail() retrieves one primary-key match or raises the missing-model exception that Laravel normally turns into a 404 response. That is different from CodeIgniter’s earlier find() example, where the controller explicitly checks for null. Do not blindly access a field on a missing record.", "kind": "concept"}, {"id": "m6q50-v2", "module": 6, "page": 22, "topic": "Retrieval versus builder", "prompt": "A controller assigns Task::where('status', 'pending') and expects fetched models. Which step is missing?", "answer": "Execute retrieval, such as ->get()", "choices": ["Execute retrieval, such as ->get()", "Call ->view() on the query", "Change the seeder class name", "Set APP_DEBUG to the desired task count"], "explanation": "The where call builds a query. get() executes it and returns the matching collection.", "kind": "application"}, {"id": "m6q51", "module": 6, "page": 26, "topic": "Schema & Eloquent", "prompt": "Which method inserts an Eloquent record?", "answer": "Task::create([...])", "choices": ["Task::create([...])", "Task::all()", "Task::findOrFail($id)", "Task::where('title', $title)->get()"], "explanation": "create performs a new model insertion from intended permitted attributes. It does not merely prepare a read query.", "kind": "concept"}, {"id": "m6q52", "module": 6, "page": 27, "topic": "Schema & Eloquent", "prompt": "Which conventional TaskController action handles the resource list request?", "answer": "TaskController::index", "choices": ["TaskController::index", "TaskController::mail", "TaskSeeder::run as the HTTP action", "Task::rules as the HTTP action"], "explanation": "TaskController::index. Register GET /tasks to TaskController::index and GET /tasks/{id} to TaskController::show, importing the controller in routes/web.php as in M5. The route connects the request to the data-loading action; it does not replace that action.", "kind": "concept"}, {"id": "m6q53-v2", "module": 6, "page": 28, "topic": "Schema & Eloquent", "prompt": "A Blade condition prints Done when $task->status === 'done'. Which stored value enters that branch?", "answer": "done", "choices": ["done", "pending", "true_mail", "complete_route"], "explanation": "The comparison tests the stored status string. The display label Done is different from the stored value done.", "kind": "concept"}, {"id": "m6q54", "module": 6, "page": 29, "topic": "Schema & Eloquent", "prompt": "Which Laravel view identifier maps to resources/views/tasks/show.blade.php?", "answer": "tasks.show", "choices": ["tasks.show", "tasks.index_only", "mail.tasks.completed", "auth.login_only"], "explanation": "A nested view identifier must match the file under resources/views. That identifier selects the template, not the record.", "kind": "concept"}, {"id": "m6q55-v2", "module": 6, "page": 22, "topic": "Result shape", "prompt": "What does Task::where('status', 'pending')->get() supply to a normal list view?", "answer": "A collection of matching task models", "choices": ["A collection of matching task models", "One task guaranteed to exist", "The number of matching tasks only", "A rendered HTML table"], "explanation": "get() retrieves a collection. first(), count(), and view rendering have different return purposes.", "kind": "application"}, {"id": "m6q56", "module": 6, "page": 31, "topic": "Schema & Eloquent", "prompt": "A controller passes ['task' => $task] to the details view. Which view variable does that key create?", "answer": "$task", "choices": ["$task", "$tasks_only", "$migration", "$smtp"], "explanation": "$task. Task::all() retrieves all tasks. compact('tasks') is a PHP helper that builds ['tasks' => $tasks] from an existing local variable; it does not query the database. view('tasks.index') uses Laravel’s dotted view naming and resolves to resources/views/tasks/index.blade.php.", "kind": "concept"}, {"id": "m6q57", "module": 6, "page": 32, "topic": "Schema & Eloquent", "prompt": "Which command opens Laravel's interactive inspection shell?", "answer": "php artisan tinker", "choices": ["php artisan tinker", "php artisan serve", "php artisan route:list", "php artisan migrate:status"], "explanation": "Tinker is a development shell for inspecting model queries and data. It is separate from the visitor-facing Blade page.", "kind": "concept"}, {"id": "m6q58", "module": 6, "page": 32, "topic": "Schema & Eloquent", "prompt": "What does Task::count() return in Tinker?", "answer": "The number of matching task rows", "choices": ["The number of matching task rows", "A collection of every task", "The first Task model", "The maximum task primary key"], "explanation": "count returns a number. It does not supply a collection of titles or one guaranteed existing model.", "kind": "concept"}, {"id": "m6q59", "module": 6, "page": 32, "topic": "Schema & Eloquent", "prompt": "What must you consider before first()->title on an empty table?", "answer": "first() can return null", "choices": ["first() can return null", "first always creates an empty task", "Tinker automatically seeds missing records", "A numeric route guarantees a record"], "explanation": "An empty table supplies no first model. Check for a missing result before reading a property.", "kind": "concept"}, {"id": "m6q60", "module": 6, "page": 33, "topic": "Schema & Eloquent", "prompt": "Which layer should own the database query?", "answer": "The model/controller data flow", "choices": ["The model/controller data flow", "The Blade template's presentation loop", "The public CSS asset", "A migration executed on every GET request"], "explanation": "Keep database retrieval in the data flow coordinated by the controller. Blade should present the supplied records rather than perform setup or queries.", "kind": "concept"}, {"id": "m7q1-v2", "module": 7, "page": 8, "topic": "Create versus store", "prompt": "A form action uses the create route name, which accepts GET. The form submits POST. What should it target?", "answer": "The registered store route for the POST submission", "choices": ["The registered store route for the POST submission", "The create route with its existing GET definition", "The migration filename", "The Blade view's filesystem path"], "explanation": "create displays the form; store receives its new-record submission. The form's method and target must match the receiving route.", "kind": "application"}, {"id": "m7q2-v2", "module": 7, "page": 9, "topic": "CSRF protection", "prompt": "A web POST form validates the title but omits @csrf. Which check is still missing?", "answer": "The token used by the web CSRF protection", "choices": ["The token used by the web CSRF protection", "The title's maximum length", "The model's table convention", "The database's sort direction"], "explanation": "Input validation and CSRF protection serve different purposes. Passing validation does not supply the form's required CSRF token.", "kind": "application"}, {"id": "m7q3", "module": 7, "page": 9, "topic": "CSRF", "prompt": "Which Blade directive inserts the CSRF token field?", "answer": "@csrf", "choices": ["@csrf", "@method", "@error", "@csrf_token"], "explanation": "@csrf is included in the module’s state-changing web forms.", "kind": "concept"}, {"id": "m7q4", "module": 7, "page": 11, "topic": "Request", "prompt": "Which class is injected as the current request?", "answer": "Illuminate\\Http\\Request", "choices": ["Illuminate\\Http\\Request", "Illuminate\\Http\\Response", "Illuminate\\Http\\UploadedFile", "App\\Models\\Task"], "explanation": "A controller imports Illuminate\\Http\\Request and accepts Request $request.", "kind": "concept"}, {"id": "m7q5", "module": 7, "page": 12, "topic": "Validation", "prompt": "What does $request->validate() do on failed validation in this web-form workflow?", "answer": "Redirects back with errors and old input", "choices": ["Redirects back with errors and old input", "Saves the invalid fields and shows success", "Returns an empty validated array and always continues the write", "Deletes the selected model"], "explanation": "Laravel returns the user to the form with errors and prior input.", "kind": "concept"}, {"id": "m7q6", "module": 7, "page": 13, "topic": "Validation", "prompt": "What does ['required', 'string', 'max:100'] mean for title?", "answer": "A required string no longer than 100 characters", "choices": ["A required string no longer than 100 characters", "An optional string with no maximum", "A required file no larger than 100 KB", "A string that must be exactly 100 characters"], "explanation": "Validation rules should fit the application’s field requirements.", "kind": "concept"}, {"id": "m7q7", "module": 7, "page": 14, "topic": "Feedback", "prompt": "Which Blade directive checks for a title validation error?", "answer": "@error('title')", "choices": ["@error('title')", "@if(old('title'))", "@csrf('title')", "@method('title')"], "explanation": "Inside @error('title'), $message contains the validation message.", "kind": "concept"}, {"id": "m7q8", "module": 7, "page": 19, "topic": "Model binding", "prompt": "In edit(Task $task), what does the route-bound Task represent?", "answer": "The existing task selected by the route parameter", "choices": ["The existing task selected by the route parameter", "Every task belonging to every user", "A new unsaved Task in every case", "The request validation rules"], "explanation": "The route uses {task}, and the controller receives the selected Task model.", "kind": "concept"}, {"id": "m7q9", "module": 7, "page": 22, "topic": "HTTP methods", "prompt": "Which directive makes an HTML POST form target the PATCH update route?", "answer": "@method('PATCH')", "choices": ["@method('PATCH')", "@csrf", "@error('PATCH')", "@method('POST')"], "explanation": "The form uses method=\"POST\" plus @method('PATCH') for method spoofing.", "kind": "concept"}, {"id": "m7q10", "module": 7, "page": 22, "topic": "Old input", "prompt": "What does old('title', $task->title) show after a failed submission?", "answer": "The submitted title, with the saved title as fallback", "choices": ["The submitted title, with the saved title as fallback", "Only the saved title regardless of submitted input", "Only the validation error text", "Only the route's task ID"], "explanation": "old() prioritizes prior form input and otherwise uses the existing record value.", "kind": "concept"}, {"id": "m7q11", "module": 7, "page": 24, "topic": "Uploads", "prompt": "In file validation, what does max:2048 mean?", "answer": "A maximum of 2048 KB", "choices": ["A maximum of 2048 KB", "A maximum of 2048 pixels in width", "A maximum of 2048 filename characters", "A required file of exactly 2048 bytes"], "explanation": "For uploaded files the limit is in kilobytes, approximately 2 MB here.", "kind": "concept"}, {"id": "m7q12", "module": 7, "page": 25, "topic": "Uploads", "prompt": "What does store('attachments', 'public') return for saving in the record?", "answer": "The stored file path", "choices": ["The stored file path", "The complete UploadedFile object", "An HTML image element", "The original client-side absolute path"], "explanation": "The upload is saved on the public disk; the task stores its generated path.", "kind": "concept"}, {"id": "m7q13", "module": 7, "page": 26, "topic": "Storage", "prompt": "Which command exposes files on the public storage disk through /storage?", "answer": "php artisan storage:link", "choices": ["php artisan storage:link", "php artisan serve", "php artisan storage:unlink", "php artisan vendor:publish"], "explanation": "storage:link creates the public storage link used by the display URL.", "kind": "concept"}, {"id": "m7q14-v2", "module": 7, "page": 12, "topic": "Validation return", "prompt": "For an ordinary web form, what does successful $request->validate($rules) provide?", "answer": "An array of validated data", "choices": ["An array of validated data", "An automatically saved Task model", "A generated migration file", "A guaranteed ownership permission"], "explanation": "Successful validation supplies data that met its rules. Saving and access decisions still require the intended application code.", "kind": "application"}, {"id": "m7q15", "module": 7, "page": 30, "topic": "Form requests", "prompt": "Which command creates a class for longer validation rules?", "answer": "php artisan make:request UpdateTaskRequest", "choices": ["php artisan make:request UpdateTaskRequest", "php artisan make:controller UpdateTaskRequest", "php artisan make:model UpdateTaskRequest", "php artisan make:middleware UpdateTaskRequest"], "explanation": "A Form Request moves rules() out of a crowded controller.", "kind": "concept"}, {"id": "m7q16", "module": 7, "page": 33, "topic": "Replacing files", "prompt": "When should an old attachment be deleted in a reliable replacement workflow?", "answer": "After the replacement succeeds", "choices": ["After the replacement succeeds", "Before validating the incoming file", "Immediately when the edit form loads", "Before attempting to store the replacement"], "explanation": "The module’s checklist says to clean up old files only after replacement succeeds. Page 28’s short snippet omits that full ordering.", "kind": "concept"}, {"id": "m7q17-v2", "module": 7, "page": 13, "topic": "Failed validation", "prompt": "A blank title fails Laravel's ordinary web-form validation. Which result fits the taught flow?", "answer": "Redirect back with validation errors and old input", "choices": ["Redirect back with validation errors and old input", "Save the invalid row and redirect with success", "Run the update without checking its target", "Delete the form's CSRF field"], "explanation": "Laravel's web validation failure handles the return and feedback path. The invalid write must not happen before that validation.", "kind": "application"}, {"id": "m7q18-v2", "module": 7, "page": 14, "topic": "Field feedback", "prompt": "An input is named title, but the view uses @error('name'). Why is its title message absent?", "answer": "The error block checks a different field key", "choices": ["The error block checks a different field key", "The title must be a primary key", "The database has too many rows", "The view must use the CI validation helper"], "explanation": "Validation errors are addressed by their field keys. The rule, input name, old input, and error block must use consistent names.", "kind": "application"}, {"id": "m7q19-v2", "module": 7, "page": 27, "topic": "Avoid double paths", "prompt": "The saved path already begins attachments/. Which URL-building pattern avoids repeating that directory?", "answer": "asset('storage/' . $task->attachment)", "choices": ["asset('storage/' . $task->attachment)", "asset('storage/attachments/' . $task->attachment)", "asset($task->id . '/storage/attachments')", "asset('app/Models/' . $task->attachment)"], "explanation": "The stored relative path already includes its directory. Prefix only the public storage segment rather than adding attachments twice.", "kind": "application"}, {"id": "m7q20-v2", "module": 7, "page": 26, "topic": "Replacing files", "prompt": "A handler deletes the old attachment before validating or storing the replacement. What is the risk?", "answer": "A failed replacement can leave the task without its old usable file", "choices": ["A failed replacement can leave the task without its old usable file", "The old file automatically moves back on validation failure", "The database recreates the old file from its filename", "The CSRF token preserves the deleted bytes"], "explanation": "Validation and successful replacement storage should precede destructive cleanup. Filesystem operations are not automatically undone by a failed database or validation step.", "kind": "application"}, {"id": "m7q21-v2", "module": 7, "page": 20, "topic": "Old input", "prompt": "An edit submission fails with title Draft 2. The saved title is Draft 1. Which value should old('title', $task->title) prefer?", "answer": "Draft 2 when old input exists", "choices": ["Draft 2 when old input exists", "Draft 1 in all circumstances", "The task's numeric ID", "The route name tasks.update"], "explanation": "Old input keeps the just-submitted value available for correction. The saved model value is the fallback for the initial form display.", "kind": "application"}, {"id": "m7q22-v2", "module": 7, "page": 26, "topic": "No replacement selected", "prompt": "An edit changes only the title and supplies no new attachment. What should a normal optional-file update preserve?", "answer": "The existing attachment reference and file", "choices": ["The existing attachment reference and file", "A null attachment unconditionally", "A new empty file at the old path", "A random attachment from another task"], "explanation": "Only perform replacement when a new upload is actually supplied and accepted. An omitted optional upload is not an instruction to remove the existing file.", "kind": "application"}, {"id": "m7q23-v2", "module": 7, "page": 31, "topic": "Form Request roles", "prompt": "A Form Request has valid rules but authorize() returns false. What explains rejection before the controller action?", "answer": "Authorization and validation are separate checks in the Form Request", "choices": ["Authorization and validation are separate checks in the Form Request", "The rules automatically override authorize()", "The uploaded file must be renamed to authorize", "The controller always runs before these checks"], "explanation": "A Form Request can define both authorization and rules. Correct input does not bypass a denied authorization decision.", "kind": "application"}, {"id": "m7q24-v2", "module": 7, "page": 31, "topic": "Validated fields", "prompt": "A controller uses a Form Request, then passes all raw input to create(). What safer contract should it use for intended fields?", "answer": "Use the validated fields and the intended model write rules", "choices": ["Use the validated fields and the intended model write rules", "Skip the Form Request because the model exists", "Put the entire request into the attachment column", "Trust hidden inputs because they are not visible"], "explanation": "The Form Request's validated data gives the intended input boundary. Model fillable protection is a separate layer and does not justify passing arbitrary raw input.", "kind": "application"}, {"id": "m7q25-v2", "module": 7, "page": 29, "topic": "Image processing", "prompt": "An image-processing class is unresolved after copying a sample. What should be checked before changing the file rules?", "answer": "The installed package version and its matching API/import", "choices": ["The installed package version and its matching API/import", "The number of rows in tasks", "The route's numeric task ID", "The browser's theme setting"], "explanation": "Third-party image APIs differ by installed version. Confirm the package and its supported calls rather than assuming every copied facade is available.", "kind": "application"}, {"id": "m7q26-v2", "module": 7, "page": 21, "topic": "Update order", "prompt": "Which sequence best describes a checked update?", "answer": "Resolve target and access → validate → update intended fields → redirect", "choices": ["Resolve target and access → validate → update intended fields → redirect", "Redirect → validate → look up the target → update", "Delete the target → validate → restore from old input", "Render success → write raw input → check access"], "explanation": "The target and access must be established before a protected write. Validation precedes persistence, and the response follows the operation.", "kind": "application"}, {"id": "m7q27-v2", "module": 7, "page": 12, "topic": "Limits and storage", "prompt": "A database title permits 150 characters but validation permits 100. A 120-character title is submitted. What should happen?", "answer": "The request fails the stricter application validation", "choices": ["The request fails the stricter application validation", "The database capacity automatically overrides validation", "$fillable shortens the text to 100 automatically", "Blade converts the title into a file upload"], "explanation": "The database's storage capacity does not cancel the request rule. These layers can intentionally enforce different limits.", "kind": "application"}, {"id": "m7q28-v2", "module": 7, "page": 25, "topic": "Disk consistency", "prompt": "An attachment was stored on the public disk. Cleanup runs against another disk. What should be made consistent?", "answer": "The disk and relative path used for storage and deletion", "choices": ["The disk and relative path used for storage and deletion", "The task title and the mail subject", "The view filename and the image width", "The create route and the migration batch number"], "explanation": "A relative path is interpreted within a disk. Deletion must address the same storage location as the original file.", "kind": "application"}, {"id": "m7q29-v2", "module": 7, "page": 9, "topic": "Request injection", "prompt": "A controller receives Request $request. What does this injection establish?", "answer": "Access to the current request, not proof that its input is valid", "choices": ["Access to the current request, not proof that its input is valid", "Automatic ownership of the requested task", "Automatic saving of every request field", "Successful upload processing"], "explanation": "Request injection supplies an object. Validation, authorization, and persistence still need their intended checks and operations.", "kind": "application"}, {"id": "m7q30", "module": 7, "page": 17, "topic": "Request validation & storage", "prompt": "What happens first in the edit workflow?", "answer": "Load the existing record", "choices": ["Load the existing record", "Delete the current attachment", "Save raw request fields", "Render success before resolving the record"], "explanation": "Resolve and check the selected record before presenting its saved values. A missing record cannot supply the edit form data.", "kind": "concept"}, {"id": "m7q31", "module": 7, "page": 18, "topic": "Request validation & storage", "prompt": "In conventional task resource naming, which route name identifies the update endpoint?", "answer": "tasks.update", "choices": ["tasks.update", "tasks.edit", "tasks.store", "tasks.show"], "explanation": "tasks.update. The form method, named route, parameter, and controller action must agree. PATCH and DELETE forms use Laravel method spoofing.", "kind": "concept"}, {"id": "m7q32-v2", "module": 7, "page": 18, "topic": "Method spoofing", "prompt": "A browser form must reach a PATCH update route. Which combination fits Laravel's form pattern?", "answer": "method=\"POST\", @csrf, and @method('PATCH')", "choices": ["method=\"POST\", @csrf, and @method('PATCH')", "method=\"GET\" and @method('PATCH') alone", "method=\"PATCH\" as a standard HTML form method", "method=\"POST\" with only a hidden title"], "explanation": "HTML forms use GET or POST. Laravel's hidden method field expresses PATCH, while the token supports web CSRF protection.", "kind": "application"}, {"id": "m7q33", "module": 7, "page": 18, "topic": "Request validation & storage", "prompt": "Which parameter name pairs with Task $task for implicit binding?", "answer": "{task}", "choices": ["{task}", "{id} without matching the task parameter", "{user}", "{title}"], "explanation": "{task}. With use App\\Models\\Task, an action such as edit(Task $task) uses implicit route model binding for the matching {task} parameter. Laravel resolves the selected task model instead of making the action manually call findOrFail($id). An unfound model normally produces a 404. Binding finds the record; it does not alone prove the current user owns it.", "kind": "concept"}, {"id": "m7q34", "module": 7, "page": 19, "topic": "Request validation & storage", "prompt": "What does implicit model binding supply?", "answer": "The selected Task model instance", "choices": ["The selected Task model instance", "Permission to change every task", "A collection of all tasks", "An array of validated request values"], "explanation": "Binding resolves the matching route parameter to one model or the not-found path. It does not establish record ownership.", "kind": "concept"}, {"id": "m7q35", "module": 7, "page": 19, "topic": "Request validation & storage", "prompt": "Does binding alone prove ownership of the task?", "answer": "No", "choices": ["No", "Yes; finding a task authorizes it", "Yes; every model belongs to the current user", "Only a view's hidden controls decide ownership"], "explanation": "No. create displays a form; store receives and saves a new record. These names become especially important in M8’s resource controller. A route name, such as tasks.store, is a label used by helpers; it is not the literal URL path and not the view filename.", "kind": "concept"}, {"id": "m7q36", "module": 7, "page": 20, "topic": "Request validation & storage", "prompt": "Which CI concept matches Laravel's old() purpose?", "answer": "Restore previous form input", "choices": ["Restore previous form input", "Create a new database row", "Validate an uploaded file's content", "Resolve a record from a route parameter"], "explanation": "Old input restores the failed submission. A model attribute can provide the initial fallback on an edit form.", "kind": "concept"}, {"id": "m7q37", "module": 7, "page": 21, "topic": "Request validation & storage", "prompt": "What does $task->update($validated) change?", "answer": "The selected model's allowed attributes", "choices": ["The selected model's allowed attributes", "Every task in the table", "Only the model's table name", "The migration file rather than stored attributes"], "explanation": "The selected model's allowed attributes. Validation establishes the acceptable submitted fields. It is separate from authentication, ownership, database schema, and mass-assignment protection.", "kind": "concept"}, {"id": "m7q38-v2", "module": 7, "page": 19, "topic": "Model binding", "prompt": "The route contains {task} and the action receives Task $task. What does implicit binding supply?", "answer": "The selected task model, or the normal not-found path", "choices": ["The selected task model, or the normal not-found path", "Proof that the current user owns the task", "Every task model in the database", "The controller's validated request array"], "explanation": "Binding resolves the route parameter into a model. Validation and record-level access remain separate responsibilities.", "kind": "application"}, {"id": "m7q39", "module": 7, "page": 22, "topic": "Request validation & storage", "prompt": "Why is the form's method POST while the route is PATCH?", "answer": "A hidden method override supplies PATCH", "choices": ["A hidden method override supplies PATCH", "The CSRF token changes POST to PATCH", "The route name changes the HTTP method", "Every POST is treated as PATCH automatically"], "explanation": "A hidden method override supplies PATCH. The form method, named route, parameter, and controller action must agree. PATCH and DELETE forms use Laravel method spoofing.", "kind": "concept"}, {"id": "m7q40", "module": 7, "page": 22, "topic": "Request validation & storage", "prompt": "Which directive supplies that override?", "answer": "@method('PATCH')", "choices": ["@method('PATCH')", "@csrf", "@error('PATCH')", "@method('POST')"], "explanation": "@method('PATCH'). HTML forms submit using POST here. @method('PATCH') supplies Laravel’s hidden method override so the request matches the PATCH route. It does not replace @csrf. old('title', $task->title) prefers the failed submitted input, falling back to the currently saved value when old input is absent.", "kind": "concept"}, {"id": "m7q41", "module": 7, "page": 22, "topic": "Request validation & storage", "prompt": "Does the method override replace @csrf?", "answer": "No", "choices": ["No", "Yes; overriding the method proves the request is trusted", "Yes; a task ID replaces the token", "Only when the form edits an existing task"], "explanation": "No. create displays a form; store receives and saves a new record. These names become especially important in M8’s resource controller. A route name, such as tasks.store, is a label used by helpers; it is not the literal URL path and not the view filename.", "kind": "concept"}, {"id": "m7q42", "module": 7, "page": 23, "topic": "Request validation & storage", "prompt": "Which encoding does the upload form require?", "answer": "multipart/form-data", "choices": ["multipart/form-data", "application/x-www-form-urlencoded", "text/plain", "application/json without multipart transfer"], "explanation": "File bytes need multipart form encoding. The presence of a file input alone does not establish that encoding.", "kind": "concept"}, {"id": "m7q43-v2", "module": 7, "page": 19, "topic": "Binding and access", "prompt": "A bound task exists but belongs to another user. What does successful binding fail to establish?", "answer": "Permission for the current user to change that task", "choices": ["Permission for the current user to change that task", "That the route matched a model", "That a task model was resolved", "That the supplied identifier found a record"], "explanation": "Finding a record is not authorization. Check access before allowing the update or upload operation.", "kind": "application"}, {"id": "m7q44", "module": 7, "page": 24, "topic": "Request validation & storage", "prompt": "Which rule restricts the attachment to image input?", "answer": "image", "choices": ["image", "nullable", "max:2048", "unique:tasks"], "explanation": "image. nullable makes absence/null acceptable in the illustrated optional-upload workflow; it does not mean any nonempty value is acceptable. image checks that the upload is an image. mimes restricts accepted file types. For this file rule, max:2048 is 2048 KB, approximately 2 MB, not 2048 characters or pixels. Compare this with the earlier string max:100.", "kind": "concept"}, {"id": "m7q45", "module": 7, "page": 24, "topic": "Request validation & storage", "prompt": "What does mimes:jpg,jpeg,png restrict?", "answer": "The accepted file types", "choices": ["The accepted file types", "Only the spelling of the filename extension", "Only the maximum file size", "Only the image's pixel dimensions"], "explanation": "Laravel checks the file type from content-derived MIME information for this rule. A renamed extension alone does not establish accepted content.", "kind": "concept"}, {"id": "m7q46", "module": 7, "page": 24, "topic": "Request validation & storage", "prompt": "What does max:2048 measure for the file?", "answer": "File size in KB", "choices": ["File size in KB", "Image width in pixels", "Title length in characters", "Number of files in the storage directory"], "explanation": "File size in KB. Validate the file, store it on the intended disk, and persist its relative path. The public URL and server filesystem path are different values.", "kind": "concept"}, {"id": "m7q47", "module": 7, "page": 25, "topic": "Request validation & storage", "prompt": "Which check handles the optional file before storing it?", "answer": "hasFile('attachment')", "choices": ["hasFile('attachment')", "input('attachment') as a text-presence check", "old('attachment')", "route('tasks.upload')"], "explanation": "hasFile('attachment'). Validate the file, store it on the intended disk, and persist its relative path. The public URL and server filesystem path are different values.", "kind": "concept"}, {"id": "m7q48-v2", "module": 7, "page": 24, "topic": "Optional uploads", "prompt": "An attachment rule allows nullable and image. The form sends no attachment. Which interpretation fits?", "answer": "The absence can pass that optional field rule", "choices": ["The absence can pass that optional field rule", "An image upload is required on every submission", "The old attachment must always be deleted", "The title becomes optional too"], "explanation": "nullable permits an absent or null optional value under this rule setup. It does not change unrelated field rules or demand deletion of an existing file.", "kind": "application"}, {"id": "m7q49-v2", "module": 7, "page": 24, "topic": "File size rules", "prompt": "For an uploaded file, max:2048 appears in Laravel validation. What unit applies?", "answer": "Kilobytes", "choices": ["Kilobytes", "Pixels", "Characters in the original filename", "Number of task records"], "explanation": "Laravel's file maximum uses kilobytes. The same rule name can mean a different measure for other data types, such as string length.", "kind": "application"}, {"id": "m7q50", "module": 7, "page": 25, "topic": "Request validation & storage", "prompt": "What does store() return for the task record?", "answer": "The generated relative path", "choices": ["The generated relative path", "A complete browser URL in every disk setup", "The browser's original local path", "The database model automatically"], "explanation": "The generated relative path. hasFile() checks whether a file was supplied, which matters when the upload is optional. store('attachments', 'public') stores it in the attachments directory on Laravel’s configured public disk and returns the generated relative path. The database saves that path, for example attachments/generated-name.png, rather than the uploaded file object or its raw bytes.", "kind": "concept"}, {"id": "m7q51", "module": 7, "page": 26, "topic": "Request validation & storage", "prompt": "What does storage:link expose in the standard local arrangement?", "answer": "Public-disk files through public/storage", "choices": ["Public-disk files through public/storage", "Every private storage disk without access checks", "The entire application source directory", "Only the database attachment column"], "explanation": "The standard local public-disk link connects the storage location to the web-visible public/storage path. It does not expose every private disk.", "kind": "concept"}, {"id": "m7q52-v2", "module": 7, "page": 23, "topic": "Upload transport", "prompt": "The controller expects file('attachment'), but the form omits multipart encoding. Which setting must be added?", "answer": "enctype=\"multipart/form-data\"", "choices": ["enctype=\"multipart/form-data\"", "A second title input", "A database unique constraint", "An SMTP port"], "explanation": "The form must send file bytes using the appropriate encoding. Changing database or mail settings does not repair the upload request.", "kind": "application"}, {"id": "m7q53", "module": 7, "page": 27, "topic": "Request validation & storage", "prompt": "Which check prevents printing an attachment image for an empty path?", "answer": "@if ($task->attachment)", "choices": ["@if ($task->attachment)", "@if ($task->id)", "@error('attachment')", "@csrf"], "explanation": "Check that an attachment reference exists before generating its image element. This prevents an empty reference from becoming a broken image request.", "kind": "concept"}, {"id": "m7q54", "module": 7, "page": 28, "topic": "Request validation & storage", "prompt": "When should a reliable replacement remove the old file?", "answer": "After the replacement path is saved successfully", "choices": ["After the replacement path is saved successfully", "Before validating the replacement", "Before storing the replacement", "Whenever the edit form opens"], "explanation": "After the replacement path is saved successfully. Validate the file, store it on the intended disk, and persist its relative path. The public URL and server filesystem path are different values.", "kind": "concept"}, {"id": "m7q55-v2", "module": 7, "page": 25, "topic": "Stored path", "prompt": "store('attachments', 'public') returns attachments/generated.png. What should the model store in this pattern?", "answer": "That relative stored path", "choices": ["That relative stored path", "The full UploadedFile object", "The visitor's original local file path", "An HTML img tag"], "explanation": "The returned path identifies the file on the chosen disk. The database reference should remain separate from the browser URL and uploaded object.", "kind": "application"}, {"id": "m7q56", "module": 7, "page": 29, "topic": "Request validation & storage", "prompt": "What does cover(300, 300) prepare?", "answer": "A square display image", "choices": ["A square display image", "A file-size limit of 300 KB", "A filename exactly 300 characters long", "A new storage disk named 300"], "explanation": "The cover operation prepares a square crop for the requested dimensions. Confirm the installed image package supports that API.", "kind": "concept"}, {"id": "m7q57-v2", "module": 7, "page": 27, "topic": "Public disk URLs", "prompt": "The file exists on the public disk, but /storage/attachments/generated.png is unavailable. What setup should be checked?", "answer": "The public storage link created by storage:link", "choices": ["The public storage link created by storage:link", "The number of validation messages", "The namespace of TaskSeeder", "The task status sort order"], "explanation": "The public disk's storage location differs from the public web path. The storage link connects the intended public URL to that storage.", "kind": "application"}, {"id": "m7q58", "module": 7, "page": 30, "topic": "Request validation & storage", "prompt": "Which method holds the Form Request's validation definitions?", "answer": "rules()", "choices": ["rules()", "authorize()", "validated()", "messages()"], "explanation": "rules(). Validation establishes the acceptable submitted fields. It is separate from authentication, ownership, database schema, and mass-assignment protection.", "kind": "concept"}, {"id": "m7q59", "module": 7, "page": 30, "topic": "Request validation & storage", "prompt": "How does a controller use the generated Form Request rules?", "answer": "Inject the Form Request class for that action", "choices": ["Inject the Form Request class for that action", "Instantiate it only after saving the model", "Add its class name only to the Blade filename", "Generate it without using its rules in the receiving action"], "explanation": "Injecting the generated Form Request applies its authorization and rule checks before the controller action proceeds. Use its validated fields for the intended write.", "kind": "concept"}, {"id": "m7q60", "module": 7, "page": 33, "topic": "Request validation & storage", "prompt": "Does a database transaction automatically undo filesystem changes?", "answer": "No", "choices": ["No", "Yes; rollback restores deleted files automatically", "Yes; commit creates all missing files", "Only when the disk is public"], "explanation": "No. Validate the file, store it on the intended disk, and persist its relative path. The public URL and server filesystem path are different values.", "kind": "concept"}, {"id": "m8q1", "module": 8, "page": 8, "topic": "Resource routes", "prompt": "Which call registers standard Laravel task CRUD routes?", "answer": "Route::resource('tasks', TaskController::class)", "choices": ["Route::resource('tasks', TaskController::class)", "Route::get('tasks', [TaskController::class, 'index'])", "Route::view('tasks', 'tasks.index')", "Route::post('tasks', [TaskController::class, 'store'])"], "explanation": "One resource registration creates the standard routes for index, create, store, show, edit, update, and destroy.", "kind": "concept"}, {"id": "m8q2-v2", "module": 8, "page": 8, "topic": "Resource routes", "prompt": "A resource route is registered, but store() is empty. What does registration provide?", "answer": "The standard request-to-action map, not completed save logic", "choices": ["The standard request-to-action map, not completed save logic", "Automatic validation and insertion of every form field", "Automatic ownership checks for every task", "A complete email workflow"], "explanation": "Resource routing connects standard methods and URLs. The controller still implements validation, access checks, persistence, and responses.", "kind": "application"}, {"id": "m8q3", "module": 8, "page": 10, "topic": "Resource routes", "prompt": "Which action handles DELETE /tasks/{task}?", "answer": "destroy", "choices": ["destroy", "delete", "remove", "update"], "explanation": "The resource action and route name are destroy and tasks.destroy.", "kind": "concept"}, {"id": "m8q4-v2", "module": 8, "page": 10, "topic": "Create versus store", "prompt": "A resource controller receives GET /tasks/create. Which action should display the form?", "answer": "create", "choices": ["create", "store", "update", "destroy"], "explanation": "create displays the new-record form. store receives its POST submission; the names represent different requests in the resource map.", "kind": "application"}, {"id": "m8q5", "module": 8, "page": 10, "topic": "Resource routes", "prompt": "Which methods match the standard tasks.update route?", "answer": "PUT/PATCH", "choices": ["PUT/PATCH", "GET/POST", "POST/DELETE", "GET/PATCH"], "explanation": "The module’s resource route table maps PUT or PATCH to update.", "kind": "concept"}, {"id": "m8q6-v2", "module": 8, "page": 10, "topic": "Edit versus update", "prompt": "A resource route receives PATCH /tasks/12. Which controller responsibility fits?", "answer": "Update the selected task after the required checks", "choices": ["Update the selected task after the required checks", "Display the empty create form", "List every task without writing", "Delete the selected task"], "explanation": "PATCH maps to update in the resource workflow. The edit action displays a form; it does not itself handle the update submission.", "kind": "application"}, {"id": "m8q7-v2", "module": 8, "page": 11, "topic": "Read versus write", "prompt": "A resource's show action renders one task. Which request pattern matches that role?", "answer": "GET /tasks/{task}", "choices": ["GET /tasks/{task}", "POST /tasks", "DELETE /tasks/{task}", "GET /tasks/create"], "explanation": "The show route reads one selected resource. Creation, deletion, and the new-record form use different methods or paths.", "kind": "application"}, {"id": "m8q8-v2", "module": 8, "page": 15, "topic": "Delete forms", "prompt": "A Blade form should reach the resource destroy action. Which combination fits?", "answer": "POST form with @csrf and @method('DELETE')", "choices": ["POST form with @csrf and @method('DELETE')", "GET link with a delete label", "POST form targeting tasks.create", "GET form with @method('POST')"], "explanation": "Laravel uses method spoofing for DELETE forms. The route target must identify the selected resource and the destroy action.", "kind": "application"}, {"id": "m8q9-v2", "module": 8, "page": 19, "topic": "Authentication gate", "prompt": "A resource sits inside auth middleware. Which claim is justified?", "answer": "Its requests require authentication, but selected-record access still needs checking", "choices": ["Its requests require authentication, but selected-record access still needs checking", "Every signed-in user owns all its tasks", "All request values already pass validation", "Every completion email will arrive"], "explanation": "Authentication checks identity. It does not automatically validate fields, authorize a selected record, or guarantee mail delivery.", "kind": "application"}, {"id": "m8q10", "module": 8, "page": 21, "topic": "Relationships", "prompt": "Which User relationship supports $request->user()->tasks()->create($validated)?", "answer": "hasMany(Task::class)", "choices": ["hasMany(Task::class)", "belongsTo(Task::class)", "hasOne(Task::class)", "belongsToMany(Mailable::class)"], "explanation": "The User model defines a hasMany Task relationship, paired with a user_id foreign key.", "kind": "concept"}, {"id": "m8q11", "module": 8, "page": 22, "topic": "User records", "prompt": "Which query retrieves only the current user's tasks with newest-created ordering?", "answer": "$request->user()->tasks()->latest()->get()", "choices": ["$request->user()->tasks()->latest()->get()", "Task::latest()->get()", "Task::all()", "$request->user()->tasks()->oldest()->get()"], "explanation": "Starting from the current user’s tasks() relationship scopes results by user_id.", "kind": "concept"}, {"id": "m8q12-v2", "module": 8, "page": 22, "topic": "Scoped lists", "prompt": "A private task index uses Task::all(). Why is authentication alone insufficient?", "answer": "The query still selects records belonging to other users", "choices": ["The query still selects records belonging to other users", "The query automatically logs out the current user", "The auth middleware changes every task owner", "Eloquent cannot query authenticated users' tasks"], "explanation": "A route gate does not automatically scope a model query. Start from the current user's relationship for the intended private list.", "kind": "application"}, {"id": "m8q13-v2", "module": 8, "page": 21, "topic": "Trusted ownership", "prompt": "A form submits user_id for a new private task. Which creation approach follows the user-owned pattern?", "answer": "Create through the authenticated user's tasks relationship using intended validated fields", "choices": ["Create through the authenticated user's tasks relationship using intended validated fields", "Trust the submitted user_id without checking it", "Assign ownership from the task title", "Allow the view to choose any stored user"], "explanation": "The server's authenticated relationship establishes ownership. A client-supplied hidden owner value can be altered.", "kind": "application"}, {"id": "m8q14", "module": 8, "page": 28, "topic": "Mail", "prompt": "What does the mailable content() method select?", "answer": "The email’s Markdown view", "choices": ["The email’s Markdown view", "The recipient and delivery result automatically", "The database record's access permission", "The SMTP account credentials"], "explanation": "new Content(markdown: 'mail.tasks.completed') selects the email template.", "kind": "concept"}, {"id": "m8q15", "module": 8, "page": 30, "topic": "Mail", "prompt": "Which call sends the completion mailable to the user?", "answer": "Mail::to($request->user()->email)->send(new TaskCompletedMail($task))", "choices": ["Mail::to($request->user()->email)->send(new TaskCompletedMail($task))", "Mail::to($request->user()->email) without sending", "new TaskCompletedMail($task) without sending", "view('mail.tasks.completed', compact('task'))"], "explanation": "The Mail facade addresses and sends a TaskCompletedMail instance after a successful update.", "kind": "concept"}, {"id": "m8q16", "module": 8, "page": 33, "topic": "Email triggers", "prompt": "Why check $task->wasChanged('status') && $task->status === 'done'?", "answer": "To send on a change to done instead of every later update", "choices": ["To send on a change to done instead of every later update", "To send on every edit while status remains done", "To authorize the current user's record access", "To validate the title before saving"], "explanation": "Checking the changed field plus its new value avoids repeatedly sending completion mail when status has not changed.", "kind": "concept"}, {"id": "m8q17-v2", "module": 8, "page": 33, "topic": "Transition conditions", "prompt": "A task is pending, then successfully changes to done. Which condition expresses the taught completion trigger?", "answer": "wasChanged('status') and the saved status is done", "choices": ["wasChanged('status') and the saved status is done", "The saved status is done regardless of change", "The title changed regardless of status", "Any GET request opened the details page"], "explanation": "The trigger needs both a saved status change and the intended destination value. A page read is not a completion event.", "kind": "application"}, {"id": "m8q18-v2", "module": 8, "page": 22, "topic": "Direct-record access", "prompt": "The index lists only the user's tasks. A show action still finds any task by ID. What remains necessary?", "answer": "A record-level access check or appropriately scoped lookup for show", "choices": ["A record-level access check or appropriately scoped lookup for show", "No further check because the index is private", "A stronger task title length rule only", "A different mail transport"], "explanation": "Private lists do not protect guessed or directly requested IDs. Each selected-record action needs the intended access restriction.", "kind": "application"}, {"id": "m8q19-v2", "module": 8, "page": 33, "topic": "Avoid repeated triggers", "prompt": "A task is already done. Saving only its title should not resend a completion notice. Which check matters?", "answer": "Whether status changed in the successful save", "choices": ["Whether status changed in the successful save", "Whether the title is nonempty", "Whether the task still has an ID", "Whether the user can see the list"], "explanation": "The status being done alone is insufficient. Checking the changed attribute avoids treating a title-only edit as a new completion transition.", "kind": "application"}, {"id": "m8q20-v2", "module": 8, "page": 21, "topic": "Relationships", "prompt": "One user can own many tasks, and each task stores user_id. Which relationship belongs on User for that collection?", "answer": "hasMany(Task::class)", "choices": ["hasMany(Task::class)", "belongsTo(Task::class)", "hasMany(Mailable::class)", "hasOne(Route::class)"], "explanation": "User::tasks() represents a collection of owned tasks. The foreign key connects those tasks to their user; mail and routes are different concerns.", "kind": "application"}, {"id": "m8q21-v2", "module": 8, "page": 33, "topic": "Destination state", "prompt": "A task changes from done to pending. Why should the completion condition remain false?", "answer": "The saved status is not done, despite changing", "choices": ["The saved status is not done, despite changing", "The task no longer has an owner", "The update was necessarily invalid", "wasChanged always returns false for every change"], "explanation": "A changed status can move in either direction. Combine change detection with the destination-state comparison.", "kind": "application"}, {"id": "m8q22-v2", "module": 8, "page": 33, "topic": "Delivery guarantees", "prompt": "A controller checks a saved transition to done. What does that condition alone fail to guarantee?", "answer": "Exactly one delivered email under every failure or retry", "choices": ["Exactly one delivered email under every failure or retry", "That the saved status equals done when the condition is true", "That the checked attribute changed for that save", "That the condition excludes an unchanged done status"], "explanation": "A local condition expresses when the application tries to send. It is not an end-to-end delivery or duplicate-prevention guarantee.", "kind": "application"}, {"id": "m8q23-v2", "module": 8, "page": 32, "topic": "Two status values", "prompt": "return back()->with('status', 'Updated') is used after saving. How does that status differ from $task->status?", "answer": "It is session feedback rather than the task's stored workflow state", "choices": ["It is session feedback rather than the task's stored workflow state", "It always overwrites the task status column", "It is the SMTP server's login status", "It is the name of the resource controller"], "explanation": "Read the owning method and object. The same word can name redirect feedback and a separate database attribute.", "kind": "application"}, {"id": "m8q24-v2", "module": 8, "page": 8, "topic": "Duplicate registration", "prompt": "A resource is registered publicly and again inside an auth group. What should be checked and simplified?", "answer": "Remove unintended duplicate registration and verify the effective route table", "choices": ["Remove unintended duplicate registration and verify the effective route table", "Keep both because the second encrypts the first", "Add a third route group to cancel the public one", "Hide the public navigation link only"], "explanation": "Duplicate routes can leave unintended mappings or confusing effective behavior. Use one intended protected registration and inspect route:list.", "kind": "application"}, {"id": "m8q25-v2", "module": 8, "page": 18, "topic": "Scaffolding limits", "prompt": "An authentication scaffold supplies login screens. What still belongs in the task feature?", "answer": "Validation, owned-record access, and the task operations", "choices": ["Validation, owned-record access, and the task operations", "No code because scaffolding implements all task CRUD", "Only a logo change", "Only the SMTP sender name"], "explanation": "Authentication scaffolding supplies authentication functionality. It does not implement the application's private task rules and full record workflow.", "kind": "application"}, {"id": "m8q26-v2", "module": 8, "page": 25, "topic": "Testing mail settings", "prompt": "The app has placeholder SMTP credentials. Why does a correct mailable still fail to establish working email?", "answer": "The transport needs a real usable test service and valid connection settings", "choices": ["The transport needs a real usable test service and valid connection settings", "The mailable automatically creates an SMTP account", "The task's status doubles as the SMTP password", "Blade cannot generate email content"], "explanation": "Content generation and transport are separate. Valid rendering cannot make placeholder server credentials connect or deliver messages.", "kind": "application"}, {"id": "m8q27-v2", "module": 8, "page": 22, "topic": "Access across actions", "prompt": "An owner check protects edit, but destroy and upload lack it. What remains vulnerable?", "answer": "Direct requests to those unprotected record actions", "choices": ["Direct requests to those unprotected record actions", "Only the page heading", "Only the resource route names", "Nothing because edit protects the model globally"], "explanation": "A check in one action is not a global permission on the model. Apply the intended record restriction to every relevant action.", "kind": "application"}, {"id": "m8q28", "module": 8, "page": 11, "topic": "CRUD, access & mail", "prompt": "Which method normally applies newest-created ordering?", "answer": "latest()", "choices": ["latest()", "oldest()", "first()", "get()"], "explanation": "latest(). latest() orders by the creation timestamp by default; get() retrieves the results. This short unscoped example shows all matching tasks. The user-scoped version later in the module is the appropriate pattern for private records.", "kind": "concept"}, {"id": "m8q29", "module": 8, "page": 11, "topic": "CRUD, access & mail", "prompt": "Does Task::latest()->get() automatically scope to the authenticated user?", "answer": "No", "choices": ["No", "Yes; latest always means the current user's records", "Yes; authentication rewrites every global model query", "Only when the collection contains done tasks"], "explanation": "No. Authentication establishes identity. Scope private lists and check access to selected records before reading or changing them.", "kind": "concept"}, {"id": "m8q30", "module": 8, "page": 12, "topic": "CRUD, access & mail", "prompt": "Which action displays rather than saves the new-record form?", "answer": "create", "choices": ["create", "store", "show", "update"], "explanation": "create. Full CRUD is the complete create/read/update/delete workflow for a resource. Laravel’s resource controller uses conventional action names so another developer can predict which method shows a form and which method saves it.", "kind": "concept"}, {"id": "m8q31-v2", "module": 8, "page": 25, "topic": "Mail configuration", "prompt": "An email uses the wrong displayed sender name. Which setting directly describes that value?", "answer": "MAIL_FROM_NAME", "choices": ["MAIL_FROM_NAME", "MAIL_HOST", "MAIL_PASSWORD", "DB_USERNAME"], "explanation": "The sender name is distinct from server connection credentials and the recipient. Inspect the corresponding sender setting first.", "kind": "application"}, {"id": "m8q32", "module": 8, "page": 14, "topic": "CRUD, access & mail", "prompt": "What do show and edit commonly receive through binding?", "answer": "One Task model", "choices": ["One Task model", "A collection of all users' tasks", "The request's validated array", "A newly generated migration"], "explanation": "Model binding resolves the selected record. show displays it; edit presents its change form. Each still needs the intended access checks.", "kind": "concept"}, {"id": "m8q33", "module": 8, "page": 17, "topic": "CRUD, access & mail", "prompt": "What does auth middleware establish before the protected action?", "answer": "The visitor is authenticated", "choices": ["The visitor is authenticated", "Ownership of every selected task", "Validity of every submitted field", "Successful completion of every model save"], "explanation": "The middleware verifies authentication before the action. It does not automatically authorize every task or validate submitted fields.", "kind": "concept"}, {"id": "m8q34", "module": 8, "page": 18, "topic": "CRUD, access & mail", "prompt": "Which Composer option marks Breeze as a development dependency?", "answer": "--dev", "choices": ["--dev", "--resource", "--model", "--seed"], "explanation": "The --dev flag records the package as a development dependency. It does not choose the authentication view flavor or run its installer.", "kind": "concept"}, {"id": "m8q35-v2", "module": 8, "page": 30, "topic": "Recipient versus sender", "prompt": "Mail::to($request->user()->email) is used after an update. Which address does it select?", "answer": "The authenticated user's email as the recipient", "choices": ["The authenticated user's email as the recipient", "MAIL_FROM_ADDRESS as the recipient automatically", "The task title as the sender", "The SMTP hostname as a user address"], "explanation": "Mail::to() selects the recipient in that call. The configured from address and SMTP account serve different roles.", "kind": "application"}, {"id": "m8q36", "module": 8, "page": 18, "topic": "CRUD, access & mail", "prompt": "Which command installs the scaffold's JavaScript dependencies?", "answer": "npm install", "choices": ["npm install", "composer install", "php artisan migrate", "php artisan breeze:install as the JavaScript package installer"], "explanation": "npm install. These are the PDF’s workflow and scaffold, not a claim that Breeze is the default starter for every Laravel release. Composer installs the PHP package; Artisan installs the selected scaffold and runs schema changes; npm installs/builds the frontend dependencies. Use a framework/package version compatible with the classroom project.", "kind": "concept"}, {"id": "m8q37-v2", "module": 8, "page": 28, "topic": "Mailable responsibilities", "prompt": "A mailable's content() selects markdown: 'mail.tasks.completed'. What does that operation establish?", "answer": "The email content view, not dispatch by itself", "choices": ["The email content view, not dispatch by itself", "The current user's ownership of the task", "The SMTP account password", "Proof that the message reached an inbox"], "explanation": "Content selection tells the mailable how to render. A sending operation, valid transport, and suitable recipient are separate requirements.", "kind": "application"}, {"id": "m8q38", "module": 8, "page": 19, "topic": "CRUD, access & mail", "prompt": "Which call groups protected routes under authentication?", "answer": "Route::middleware('auth')->group(...)", "choices": ["Route::middleware('auth')->group(...)", "Route::resource('tasks', TaskController::class) with no middleware", "Task::where('auth', true)", "Route::name('auth')->group(...)"], "explanation": "Route::middleware('auth')->group(...). Resource routes provide a conventional request-to-action map. The controller must still implement validation, access, persistence, and the response.", "kind": "concept"}, {"id": "m8q39-v2", "module": 8, "page": 29, "topic": "Named task links", "prompt": "An email renders route('tasks.show', $task). Why must the destination still check access?", "answer": "Possessing a task URL does not grant permission to read the task", "choices": ["Possessing a task URL does not grant permission to read the task", "An email link bypasses all server middleware automatically", "Named routes validate task ownership when rendered", "The mail template deletes private data before navigation"], "explanation": "A generated link is only a destination. The later browser request must still satisfy authentication and record access checks.", "kind": "application"}, {"id": "m8q40", "module": 8, "page": 20, "topic": "CRUD, access & mail", "prompt": "Which earlier CI feature plays a similar route-gate role?", "answer": "An authentication filter", "choices": ["An authentication filter", "A model's writable-field list", "A view's old-input helper", "A database migration"], "explanation": "An authentication filter. Resource routes provide a conventional request-to-action map. The controller must still implement validation, access, persistence, and the response.", "kind": "concept"}, {"id": "m8q41", "module": 8, "page": 21, "topic": "CRUD, access & mail", "prompt": "Which migration column associates a task with its owner?", "answer": "user_id", "choices": ["user_id", "id as the user identifier for every task", "status", "created_at"], "explanation": "user_id. Associate each task with its owner. The course adds a user_id foreign key and a relationship on User:", "kind": "concept"}, {"id": "m8q42", "module": 8, "page": 21, "topic": "CRUD, access & mail", "prompt": "Which relationship does User define for its tasks?", "answer": "hasMany(Task::class)", "choices": ["hasMany(Task::class)", "belongsTo(Task::class)", "hasOne(Task::class)", "belongsToMany(Mailable::class)"], "explanation": "hasMany(Task::class). Authentication establishes identity. Scope private lists and check access to selected records before reading or changing them.", "kind": "concept"}, {"id": "m8q43", "module": 8, "page": 21, "topic": "CRUD, access & mail", "prompt": "Why create tasks through the authenticated user's relationship?", "answer": "To associate the created task with that user", "choices": ["To associate the created task with that user", "To bypass title validation", "To grant all users access to the task", "To send mail before a row exists"], "explanation": "To associate the created task with that user. Authentication establishes identity. Scope private lists and check access to selected records before reading or changing them.", "kind": "concept"}, {"id": "m8q44", "module": 8, "page": 22, "topic": "CRUD, access & mail", "prompt": "Which query starts from the current user's task relationship?", "answer": "$request->user()->tasks()", "choices": ["$request->user()->tasks()", "Task::query() without a user condition", "Task::latest() without a user condition", "User::query() without selecting the current user"], "explanation": "$request->user()->tasks(). Authentication establishes identity. Scope private lists and check access to selected records before reading or changing them.", "kind": "concept"}, {"id": "m8q45", "module": 8, "page": 22, "topic": "CRUD, access & mail", "prompt": "Which actions still need record-level access checks after a scoped index?", "answer": "Show, edit, update, destroy, and uploads", "choices": ["Show, edit, update, destroy, and uploads", "Only the index action", "Only the edit form's visual controls", "No other action after a scoped list"], "explanation": "Each selected-record endpoint needs the intended access restriction. A private list does not protect direct requests to other actions.", "kind": "concept"}, {"id": "m8q46", "module": 8, "page": 25, "topic": "CRUD, access & mail", "prompt": "Which setting selects SMTP transport?", "answer": "MAIL_MAILER=smtp", "choices": ["MAIL_MAILER=smtp", "MAIL_HOST=smtp", "MAIL_FROM_NAME=smtp", "APP_ENV=smtp"], "explanation": "MAIL_MAILER=smtp. MAIL_MAILER=smtp selects SMTP transport. MAIL_HOST, MAIL_PORT, MAIL_USERNAME, and MAIL_PASSWORD describe that connection. MAIL_FROM_ADDRESS and MAIL_FROM_NAME identify the sender. The recipient comes from Mail::to($request->user()->email) in the controller, not from the sender configuration.", "kind": "concept"}, {"id": "m8q47", "module": 8, "page": 25, "topic": "CRUD, access & mail", "prompt": "Which setting identifies the outgoing server hostname?", "answer": "MAIL_HOST", "choices": ["MAIL_HOST", "MAIL_PORT", "MAIL_FROM_ADDRESS", "MAIL_USERNAME"], "explanation": "MAIL_HOST. MAIL_MAILER=smtp selects SMTP transport. MAIL_HOST, MAIL_PORT, MAIL_USERNAME, and MAIL_PASSWORD describe that connection. MAIL_FROM_ADDRESS and MAIL_FROM_NAME identify the sender. The recipient comes from Mail::to($request->user()->email) in the controller, not from the sender configuration.", "kind": "concept"}, {"id": "m8q48", "module": 8, "page": 25, "topic": "CRUD, access & mail", "prompt": "Which setting identifies the sender address?", "answer": "MAIL_FROM_ADDRESS", "choices": ["MAIL_FROM_ADDRESS", "MAIL_HOST", "MAIL_PORT", "MAIL_USERNAME"], "explanation": "MAIL_FROM_ADDRESS. MAIL_MAILER=smtp selects SMTP transport. MAIL_HOST, MAIL_PORT, MAIL_USERNAME, and MAIL_PASSWORD describe that connection. MAIL_FROM_ADDRESS and MAIL_FROM_NAME identify the sender. The recipient comes from Mail::to($request->user()->email) in the controller, not from the sender configuration.", "kind": "concept"}, {"id": "m8q49", "module": 8, "page": 25, "topic": "CRUD, access & mail", "prompt": "Do placeholder SMTP settings send mail without a valid service?", "answer": "No", "choices": ["No", "Yes; any nonempty credentials establish SMTP access", "Yes; a Markdown view supplies an SMTP account", "Only when the task status is done"], "explanation": "No. Mail content, recipient selection, transport configuration, and the business trigger have separate jobs. A rendered message does not prove delivery.", "kind": "concept"}, {"id": "m8q50", "module": 8, "page": 26, "topic": "CRUD, access & mail", "prompt": "Where is TaskCompletedMail.php generated?", "answer": "app/Mail/", "choices": ["app/Mail/", "app/Models/", "app/Http/Controllers/", "resources/views/mail/"], "explanation": "app/Mail/. Mail content, recipient selection, transport configuration, and the business trigger have separate jobs. A rendered message does not prove delivery.", "kind": "concept"}, {"id": "m8q51", "module": 8, "page": 26, "topic": "CRUD, access & mail", "prompt": "A mailable uses --markdown=mail.tasks.completed. Which generated view path matches that identifier?", "answer": "resources/views/mail/tasks/completed.blade.php", "choices": ["resources/views/mail/tasks/completed.blade.php", "app/Views/mail.php", "database/mail.sql", "routes/mail.php"], "explanation": "resources/views/mail/tasks/completed.blade.php. Mail content, recipient selection, transport configuration, and the business trigger have separate jobs. A rendered message does not prove delivery.", "kind": "concept"}, {"id": "m8q52", "module": 8, "page": 27, "topic": "CRUD, access & mail", "prompt": "Which optional command publishes mail views for customization?", "answer": "php artisan vendor:publish --tag=laravel-mail", "choices": ["php artisan vendor:publish --tag=laravel-mail", "php artisan storage:link --mail", "php spark publish:mail", "npm mail:views"], "explanation": "php artisan vendor:publish --tag=laravel-mail. Mail content, recipient selection, transport configuration, and the business trigger have separate jobs. A rendered message does not prove delivery.", "kind": "concept"}, {"id": "m8q53", "module": 8, "page": 28, "topic": "CRUD, access & mail", "prompt": "What does public Task $task in the constructor expose?", "answer": "The received task as a public property", "choices": ["The received task as a public property", "An automatically delivered message", "The SMTP password as a task field", "The complete task collection"], "explanation": "Constructor property promotion both receives and exposes the typed task property. It does not load every task or send the message by itself.", "kind": "concept"}, {"id": "m8q54", "module": 8, "page": 28, "topic": "CRUD, access & mail", "prompt": "Does content() itself select the recipient and dispatch the mail?", "answer": "No; it selects the content definition", "choices": ["No; it selects the content definition", "Yes; rendering dispatches to every configured sender", "Yes; markdown selects the authenticated recipient", "Only when the task status is done"], "explanation": "No; it selects the content definition. Mail content, recipient selection, transport configuration, and the business trigger have separate jobs. A rendered message does not prove delivery.", "kind": "concept"}, {"id": "m8q55", "module": 8, "page": 29, "topic": "CRUD, access & mail", "prompt": "Which Blade mail component supplies the message wrapper?", "answer": "x-mail::message", "choices": ["x-mail::message", "x-task::database", "x-route::csrf", "x-storage::public"], "explanation": "x-mail::message. Mail content, recipient selection, transport configuration, and the business trigger have separate jobs. A rendered message does not prove delivery.", "kind": "concept"}, {"id": "m8q56", "module": 8, "page": 29, "topic": "CRUD, access & mail", "prompt": "Under standard task resource naming, which named route displays one task from its email link?", "answer": "tasks.show", "choices": ["tasks.show", "tasks.destroy", "tasks.store", "tasks.create"], "explanation": "tasks.show. Mail content, recipient selection, transport configuration, and the business trigger have separate jobs. A rendered message does not prove delivery.", "kind": "concept"}, {"id": "m8q57-v2", "module": 8, "page": 30, "topic": "Send ordering", "prompt": "A completion email is sent before the task update succeeds. What failure can that create?", "answer": "The recipient can be told about a change that was not saved", "choices": ["The recipient can be told about a change that was not saved", "The email automatically rolls back the update", "The SMTP server validates the task data", "The mailable automatically saves the task"], "explanation": "Send success notifications only after the relevant write succeeds. A rendering or sending call does not establish persistence.", "kind": "application"}, {"id": "m8q58-v2", "module": 8, "page": 32, "topic": "CRUD, access & mail", "prompt": "What does return back()->with('status', 'Status updated') create?", "answer": "Session feedback for the redirected request", "choices": ["Session feedback for the redirected request", "A new value in the task status column", "An outgoing SMTP delivery report", "A validation rule for the next update"], "explanation": "The with call adds redirect feedback to the session. It does not update $task->status or prove that an email was delivered.", "kind": "concept"}, {"id": "m8q59", "module": 8, "page": 33, "topic": "CRUD, access & mail", "prompt": "Why combine wasChanged('status') with status === 'done'?", "answer": "To target a saved transition to done", "choices": ["To target a saved transition to done", "To send on every save of an already-done task", "To authorize access to every task", "To detect only a title change"], "explanation": "The condition combines a saved attribute change with its destination state. Merely remaining done after another edit is not a completion transition.", "kind": "concept"}, {"id": "m8q60", "module": 8, "page": 33, "topic": "CRUD, access & mail", "prompt": "Does that condition guarantee exactly-once delivery under every retry?", "answer": "No", "choices": ["No", "Yes; the condition is a global delivery lock", "Yes; SMTP cannot retry messages", "Only when a user refreshes the page"], "explanation": "No. Full CRUD is the complete create/read/update/delete workflow for a resource. Laravel’s resource controller uses conventional action names so another developer can predict which method shows a form and which method saves it.", "kind": "concept"}]};
